(45382, 'frFR', 'Maître de métier', 'Maître de métier', 26124),
(45383, 'frFR', 'Maître des écuries', 'Maître des écuries', 26124),
(45385, 'frFR', 'Comme elle est belle…', '', 26124),
(45386, 'frFR', 'Alors, $gprêt:prête; ? On se bouge ! Essayez de suivre, $n.', '', 26124),
(45387, 'frFR', 'En avant, frères et sœurs !', '', 26124),
