(45405, 'frFR', 'Prêtre', 'Prêtre', 26124),
(45406, 'frFR', 'Voleur', 'Voleur', 26124),
(45407, 'frFR', 'Démoniste', 'Démoniste', 26124),
(45408, 'frFR', 'Guerrier', 'Guerrier', 26124),
