(91250, 'frFR', 'Je vais vous faire une balafre dont vous pourrez vous vanter !', 'Je vais vous faire une balafre dont vous pourrez vous vanter !', 26124),
(91251, 'frFR', 'Sale vermine chanceuse !', 'Sale vermine chanceuse !', 26124),
(91252, 'frFR', 'Laissez-moi souffrir !', 'Laissez-moi souffrir !', 26124),
(91253, 'frFR', 'Kargath ne va pas aimer ça…', 'Kargath ne va pas aimer ça…', 26124),
(91254, 'frFR', 'Cette souffrance… si… glorieuse…', 'Cette souffrance… si… glorieuse…', 26124),
(91255, 'frFR', 'C’est l’heure de la pause baston !', 'C’est l’heure de la pause baston !', 26124),
(91256, 'frFR', 'J’ai un crochet de libre pour vous.', 'J’ai un crochet de libre pour vous.', 26124),
(91257, 'frFR', 'Vous devez vous sentir en veine.', 'Vous devez vous sentir en veine.', 26124),
(91258, 'frFR', 'Vous venez vous joindre aux bêtes ?', 'Vous venez vous joindre aux bêtes ?', 26124),
(91259, 'frFR', 'Bien. Quelque chose à écorcher !', 'Bien. Quelque chose à écorcher !', 26124),
(91260, 'frFR', 'Laissez-moi écouter vos hurlements !', 'Laissez-moi écouter vos hurlements !', 26124),
