(116673, 'frFR', 'Pour les Shal’dorei !', '', 26124),
(116674, 'frFR', 'Partez, misérables !', '', 26124),
(116675, 'frFR', 'Votre destin est scellé !', '', 26124),
(116676, 'frFR', 'Goûtez à la puissance des Shal’dorei !', '', 26124),
(116677, 'frFR', 'L’heure des Shal’dorei arrive !', '', 26124),
(116678, 'frFR', 'Vous n’avez rien à faire ici, prolétaire !', '', 26124),
(116679, 'frFR', 'Nous sommes les élus !', '', 26124),
(116680, 'frFR', 'Pas de pitié pour les étrangers !', '', 26124),
(116681, 'frFR', 'Anath’ashar !', '', 26124),
(116682, 'frFR', 'Vous n’avez aucune chance !', '', 26124),
(116683, 'frFR', 'Tremblez devant notre puissance !', '', 26124),
(116684, 'frFR', 'Votre étoile pâlit à vue d’œil !', '', 26124),
(116685, 'frFR', 'Vermine !', '', 26124),
(116686, 'frFR', 'Vous tomberez à genoux !', '', 26124),
(116687, 'frFR', 'Personne ne nous défiera !', '', 26124),
(116688, 'frFR', 'Anath’ashar !', '', 26124),
(116689, 'frFR', 'Votre destin est scellé !', 'Vous n’avez aucune chance !', 26124),
