(117287, 'frFR', 'Restez où vous êtes !', '', 26124),
(117288, 'frFR', 'Vous n’irez nulle part !', '', 26124),
(117289, 'frFR', 'Restez donc… un instant !', '', 26124),
(117290, 'frFR', 'C’est une tâche indigne de moi.', '', 26124),
(117291, 'frFR', 'Vous allez brûler !', '', 26124),
(117292, 'frFR', 'Il n’en restera que des cendres !', '', 26124),
(117293, 'frFR', 'Je les réduis en cendres !', '', 26124),
(117294, 'frFR', 'Tout brûlera !', '', 26124),
(117295, 'frFR', 'Mes flammes dévorent tout.', '', 26124),
(117296, 'frFR', 'Un… écueil… mineur…', '', 26124),
(117297, 'frFR', 'Arrgghhh…', '', 26124),
(117298, 'frFR', 'Je suis blessé… Continuez sans moi.', '', 26124),
(117299, 'frFR', '', 'À votre avis, y a quoi dans le sac ?', 26124),
(117300, 'frFR', '', 'Je me sens en veine !', 26124),
