(120072, 'frFR', 'Effets sonores pour soldats', '', 26124),
(120073, 'frFR', 'Pitié… je n’ai pas mangé depuis des semaines…', '', 26124),
(120074, 'frFR', 'Effets sonores pour soldats', 'Effets sonores pour soldats', 26124),
(120075, 'frFR', 'Du mana… j’ai besoin… de mana.', '', 26124),
(120076, 'frFR', 'Effets sonores pour soldats', 'Effets sonores pour soldats', 26124),
(120077, 'frFR', 'Effets sonores pour soldats', 'Effets sonores pour soldats', 26124),
