(131515, 'frFR', 'La croisée est désormais active.', '', 26124),
(131516, 'frFR', 'La croisée sera bientôt désactivée.', '', 26124),
(131517, 'frFR', 'La croisée n’est plus active.', '', 26124),
(131518, 'frFR', 'Le moulin à eau sera bientôt actif.', '', 26124),
(131519, 'frFR', 'Le moulin à eau est désormais actif.', '', 26124),
(131520, 'frFR', 'Le moulin à eau sera bientôt désactivé.', '', 26124),
(131521, 'frFR', 'Le moulin à eau n’est plus actif.', '', 26124),
(131522, 'frFR', 'Le pont sera bientôt actif.', '', 26124),
(131523, 'frFR', 'Le pont est désormais actif.', '', 26124),
(131524, 'frFR', 'Le pont sera bientôt désactivé.', '', 26124),
(131525, 'frFR', 'Le pont n’est plus actif.', '', 26124),
(131526, 'frFR', 'Le phare sera bientôt actif.', '', 26124),
(131527, 'frFR', 'Le phare est désormais actif.', '', 26124),
(131528, 'frFR', 'Le phare sera bientôt désactivé.', '', 26124),
