(131530, 'frFR', 'L’escarpement sera bientôt actif.', '', 26124),
(131531, 'frFR', 'L’escarpement est désormais actif.', '', 26124),
(131532, 'frFR', 'L’escarpement sera bientôt désactivé.', '', 26124),
(131533, 'frFR', 'L’escarpement n’est plus actif.', '', 26124),
(131534, 'frFR', 'Les mines seront bientôt actives.', '', 26124),
(131535, 'frFR', 'Les mines sont désormais actives.', '', 26124),
(131536, 'frFR', 'Les mines seront bientôt désactivées.', '', 26124),
(131537, 'frFR', 'Les mines ne sont plus actives.', '', 26124),
(131538, 'frFR', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s commence à lancer |cFFFF0000|Hspell:244509|h[Sororité des Sargereï]|h|r.', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s commence à lancer |cFFFF0000|Hspell:244509|h[Sororité des Sargereï]|h|r.', 26124),
(131545, 'frFR', 'Beurk…', '', 26124),
(131546, 'frFR', 'Au secours…', '', 26124),
(131547, 'frFR', 'Vous aidez, s’il vous plaît.', '', 26124),
(131548, 'frFR', 'Aidez-moi.', '', 26124),
(131549, 'frFR', '…', '', 26124),
(131550, 'frFR', 'Administrer l’antidote.', 'Administrer l’antidote.', 26124),
(131551, 'frFR', '<Le bébé sélénien semble ravi de vous voir.>', '', 26124),
(131552, 'frFR', 'Je vous aime.', '', 26124),
(131553, 'frFR', 'Merci !', '', 26124),
(131554, 'frFR', 'Ouais !', '', 26124),
(131555, 'frFR', 'Hourra !', '', 26124),
(131556, 'frFR', 'Vous êtes formidable.', '', 26124),
(131557, 'frFR', 'Vous êtes $gle meilleur:la meilleure; !', '', 26124),
(131559, 'frFR', 'Jadefeu a antidote !', '', 26124),
(131561, 'frFR', 'Aidez Clouklou !', '', 26124),
(131563, 'frFR', 'Trouvez Clouklou !', '', 26124),
(131564, 'frFR', 'Sauvez Clouklou !', '', 26124),
(131565, 'frFR', 'Clouklou sous terre !', '', 26124),
(131566, 'frFR', 'Tuez Jadefeu !', '', 26124),
(131567, 'frFR', 'Merci.', '', 26124),
(131568, 'frFR', 'Merci de m’avoir sauvé.', '', 26124),
(131569, 'frFR', 'Tuez les responsables de tout ça !', '', 26124),
(131570, 'frFR', 'L’Alliance a pris le contrôle du surplomb !', '', 26124),
(131571, 'frFR', 'L’Alliance a perdu le contrôle du surplomb !', '', 26124),
(131572, 'frFR', 'La Horde a pris le contrôle du surplomb !', '', 26124),
(131573, 'frFR', 'La Horde a perdu le contrôle du surplomb !', '', 26124),
(131574, 'frFR', 'L’Alliance a pris le contrôle de la côte !', '', 26124),
(131575, 'frFR', 'L’Alliance a perdu le contrôle de la côte !', '', 26124),
(131576, 'frFR', 'La Horde a pris le contrôle de la côte !', '', 26124),
(131577, 'frFR', 'La Horde a perdu le contrôle de la côte !', '', 26124),
(131578, 'frFR', 'L’Alliance a pris le contrôle de la croisée !', '', 26124),
(131579, 'frFR', 'L’Alliance a perdu le contrôle de la croisée !', '', 26124),
(131580, 'frFR', 'La Horde a pris le contrôle de la croisée !', '', 26124),
(131581, 'frFR', 'La Horde a perdu le contrôle de la croisée !', '', 26124),
(131582, 'frFR', 'L’Alliance a pris le contrôle du moulin à eau !', '', 26124),
(131583, 'frFR', 'L’Alliance a perdu le contrôle du moulin à eau !', '', 26124),
(131584, 'frFR', 'La Horde a pris le contrôle du moulin à eau !', '', 26124),
(131585, 'frFR', 'La Horde a perdu le contrôle du moulin à eau !', '', 26124),
(131586, 'frFR', 'L’Alliance a pris le contrôle du pont !', '', 26124),
(131587, 'frFR', 'L’Alliance a perdu le contrôle du pont !', '', 26124),
(131588, 'frFR', 'La Horde a pris le contrôle du pont !', '', 26124),
(131589, 'frFR', 'La Horde a perdu le contrôle du pont !', '', 26124),
(131590, 'frFR', 'L’Alliance a pris le contrôle du phare !', '', 26124),
(131591, 'frFR', 'L’Alliance a perdu le contrôle du phare !', '', 26124),
(131592, 'frFR', 'La Horde a pris le contrôle du phare !', '', 26124),
(131593, 'frFR', 'La Horde a perdu le contrôle du phare !', '', 26124),
(131594, 'frFR', 'L’Alliance a pris le contrôle de l’escarpement !', '', 26124),
(131595, 'frFR', 'L’Alliance a perdu le contrôle de l’escarpement !', '', 26124),
(131596, 'frFR', 'La Horde a pris le contrôle de l’escarpement !', '', 26124),
(131597, 'frFR', 'La Horde a perdu le contrôle de l’escarpement !', '', 26124),
(131598, 'frFR', 'L’Alliance a pris le contrôle des mines !', '', 26124),
(131599, 'frFR', 'L’Alliance a perdu le contrôle des mines !', '', 26124),
(131600, 'frFR', 'La Horde a pris le contrôle des mines !', '', 26124),
(131601, 'frFR', 'La Horde a perdu le contrôle des mines !', '', 26124),
(131647, 'frFR', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|tApportez l’|cFFFF0000|Hspell:232913|h[Encre répugnante]|h|r à Sarukel pour fermer sa |cFFFF0000|Hspell:234621|h[Gueule vorace]|h|r !', '', 26124),
(131669, 'frFR', '', 'La bête faiblit. Visez bien !', 26124),
(131673, 'frFR', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|tVous êtes victime de |cFFFF0000|Hspell:236329|h[Brûlure stellaire]|h|r. Cachez-vous derrière des piliers infernaux lorsque vous êtes la cible d’Étoile fracassante !', '', 26124),
(131740, 'frFR', '', 'Ne faisons pas attendre notre fils.', 26124),
(131753, 'frFR', 'Sans le cimier de la Connaissance, nous ne pouvons pas l’emporter.', '', 26124),
(131756, 'frFR', '', 'Il y a une présence familière ici. Je la sens qui m’appelle.', 26124),
(131757, 'frFR', '', 'Des forces qui dépassent notre imagination sont à l’œuvre par ici. Restez sur vos gardes.', 26124),
(131758, 'frFR', '', 'Ouvrez l’œil et restez $gdiscret:discrète;, $n.', 26124),
(131759, 'frFR', '', 'Les ténèbres se referment sur nous de toutes parts. Restez sur vos gardes.', 26124),
(131760, 'frFR', '', 'Il faut que je vous montre ce que j’ai vu.', 26124),
(131762, 'frFR', 'Montrez-moi.', 'Montrez-moi.', 26124),
(131778, 'frFR', '|TInterface\\ICONS\\Spell_Deathknight_Necroticplague.blp:20|t Vous subissez l’effet d’|cFFF00000|Hspell:244093|h[Étreinte nécrotique]|h|r !', '', 26124),
(131817, 'frFR', 'Ne laissez pas la nuit longue et interminable vous briser. Acceptez son don.', '', 26124),
(131820, 'frFR', '', 'J’ai trouvé un survivant. Venez.', 26124),
(131821, 'frFR', '', 'Montrez-vous. Nous ne vous voulons aucun mal.', 26124),
(131822, 'frFR', 'Une voix ! Arkhaan n’avait jamais entendu cette voix avant.', '', 26124),
(131823, 'frFR', '', 'Nous avons trouvé vos messages.', 26124),
(131833, 'frFR', 'Pas vouloir dormir !', '', 26124),
(131834, 'frFR', 'Pas dormir !', '', 26124),
(131835, 'frFR', 'Pas fatigué !', '', 26124),
(131837, 'frFR', 'Debout !', '', 26124),
(131846, 'frFR', '', 'Je vous retrouverai dans les ruines, $n. Nous commencerons là où les ténèbres prennent fin.', 26124),
(131856, 'frFR', 'Ahiiii !', '', 26124),
(131857, 'frFR', 'Aaaaaaaaaaaah !', '', 26124),
(131858, 'frFR', 'Hiiiiiiiiiiiii !', '', 26124),
(131859, 'frFR', 'Aiiiiiiyaaaaahhhhhhh !', '', 26124),
(131860, 'frFR', 'Ooooooooooooooooh !', '', 26124),
(131861, 'frFR', 'Woooooouuuuuh !', '', 26124),
(131866, 'frFR', 'Oui, Arkhaan a appelé… mais il ne pensait pas que…', '', 26124),
(131871, 'frFR', 'J’ai toujours su que je reverrais Argus un jour. Mes visions me l’ont révélé à maintes reprises.

Pourtant, j’étais loin de m’imaginer une chose pareille.

Il ne fait aucun doute que le destins de nos mondes sont intimement liés. Parviendrons-nous à sauver Argus, ou faudra-t-il le sacrifier pour arrêter Sargeras ? Sur ce point, mes visions laissent l’incertitude.

Il semble que nous devions forger notre propre destinée. Puisse la Lumière nous venir en aide, $n.', '', 26124),
(131872, 'frFR', 'La clé sargerite a déchiré le tissu de la réalité. Nous devons à présent combattre les armées de la Légion sur ses propres terres.

Turalyon est là, quelque part ; Alleria aussi, je l’espère. Nous devons retrouver mes vieux amis et rallier l’armée de la Lumière à notre combat, peut-être alors l’emporterons-nous.', '', 26124),
(131873, 'frFR', 'Argus, trône de la Légion ardente. Grâce à ses machines infernales, Sargeras dispose d’effectifs illimités.

Il est grand temps de priver le Titan noir de son trophée.

Nous savons ce qu’il nous reste à faire : assiéger Argus et soumettre la Légion.', '', 26124),
(131876, 'frFR', '<Le jugement de la Lumière est encastré dans la falaise. Il semble relativement intact, mais aura néanmoins besoin de réparations avant d’être à nouveau opérationnel.$b$bVous devriez pouvoir activer les contre-mesures de sécurité pour le téléporter à bord du Vindicaar.>', '', 26124),
(131877, 'frFR', '<Activer la séquence de téléportation.>', '<Activer la séquence de téléportation.>', 26124),
(131889, 'frFR', 'Mais… N’auriez-vous pas pu entrer en contact avec nous ? Avec votre peuple ? Avec moi ?', '', 26124),
(131890, 'frFR', 'Arator… Pas un jour ne s’est écoulé sans que ta mère et moi ne…', '', 26124),
(131891, 'frFR', '', 'Tous nos choix, nous les avons faits pour assurer ta sécurité. Cela nous a brisé le cœur d’être séparés de toi.', 26124),
(131898, 'frFR', '', 'Accrochez-vous à votre casque… On va voyager dans le TEMPS !', 26124),
(131899, 'frFR', '', 'Très bien… Voyons voir. Je crois que nous sommes au bon moment, à une minute près. Est-ce que je suis déjà morte ?', 26124),
(131900, 'frFR', '', 'Oh, bien. C’est moi, là-bas. Salut, moi !', 26124),
(131901, 'frFR', '', 'Oh, bonjour ! Qu’est-ce que tu fais là ?', 26124),
(131902, 'frFR', '', 'Et c’est reparti !', 26124),
(131903, 'frFR', '', 'Je nous ai fait gagner quelques secondes, mais nous devons agir vite.', 26124),
(131904, 'frFR', '', 'Hé ! Chromie !', 26124),
(131905, 'frFR', '', 'Oh, bonjour ! Qu’est-ce que je fais là ?', 26124),
(131906, 'frFR', '', 'Suivez-moi ! Le temps presse !', 26124),
(131907, 'frFR', '', 'Oh ! Bon, très bien. Tu as toujours été de bons conseil par le passé. Ou dans l’avenir.', 26124),
(131908, 'frFR', '', 'Alors, où allons-nous ? Pourquoi quittons-nous le Repos du ver ?', 26124),
(131909, 'frFR', '', 'Quelqu’un essaie de te tuer. En fait, ça devrait se produire d’une seconde à l’autre…', 26124),
(131910, 'frFR', '', 'Très bien, je vais nous chronoporter quatre heures avant le début de l’attaque. Ça devrait nous laisser TOUT le temps de démêler cet imbroglio.', 26124),
(131911, 'frFR', '', 'Hum ! Bizarre. Quelque chose me bloque l’accès à ce moment précis du temps.', 26124),
(131912, 'frFR', '', 'Pas de souci ! C’était sans doute trop tôt de tout façon. Essayons une heure avant.', 26124),
(131913, 'frFR', '', 'Je commence à être vraiment inquiète, $n. La personne qui a orchestré cette attaque est bien renseignée. Elle a trouvé un moyen de bloquer mes chronoportations !', 26124),
(131914, 'frFR', '', 'Essayons une dernière fois…', 26124),
(131915, 'frFR', '', 'Maintenant, ça devrait être bon !', 26124),
(131916, 'frFR', '', 'Il reste 15 minutes avant ma mort.', 26124),
(131917, 'frFR', '', 'Ça ne sera pas suffisant pour me sauver, mais c’est le mieux que je puisse faire pour l’instant.', 26124),
(131918, 'frFR', '', 'Renseignons-nous pour voir si nous pouvons découvrir d’où venaient ces éclairs de l’ombre.', 26124),
(131919, 'frFR', '', 'Des attaques de morts-vivants au sanctuaire draconique Rubis ? Nous allons enquêter. Merci, Allie.', 26124),
(131920, 'frFR', '', 'Étrange ? Laissez-moi réfléchir… Oh ! J’ai vu ce dragon noir un peu plus tôt aujourd’hui. C’est quoi son nom déjà ? Aile de mort ? Non, non, non, pas lui… L’autre. Celui avec le chapeau.', 26124),
(131921, 'frFR', '', 'Je suis presque certaine qu’il se dirigeait vers le sanctuaire draconique Obsidien.', 26124),
(131922, 'frFR', '', 'On va vérifier. Merci !', 26124),
(131923, 'frFR', '', 'Merci, seigneur Itharius, on va vérifier. On vous préviendra si on découvre quelque chose.', 26124),
(131924, 'frFR', '', 'Des perturbations des lignes telluriques ? Pff… Des problèmes typiques de dragon bleu.', 26124),
(131925, 'frFR', '', 'On dirait que nous allons devoir inspecter quelques sanctuaires draconiques. Allons, euh… inspecter ces sanctuaires draconiques !', 26124),
(131926, 'frFR', '', '$n, allons nous occuper des chefs. Ils nous apprendront peut-être quelque chose sur la prochaine attaque.', 26124),
(131927, 'frFR', '', 'Une liche ! Rah ! Je m’en doutais… C’est tout de même étonnant que je n’aie jamais vu ça dans une future ligne temporelle.', 26124),
(131928, 'frFR', '', 'Dans l’arbre, c’est ça ? Allons-y. Son heure est venue !', 26124),
(131929, 'frFR', '', 'Attaquons directement cette liche, $n. Si c’est vraiment elle qui orchestre cette attaque, la tuer devrait disperser ses troupes.', 26124),
(131930, 'frFR', '', 'Voilà une menace éliminée dans les temps !', 26124),
(131932, 'frFR', '', 'Hein ? Qu’est-ce que c’est ? Une sorte d’éclat de temps ? Je vais l’apporter au Repos du ver pour l’étudier.', 26124),
(131933, 'frFR', '', 'Il marque un point. Allons explorer cette grotte effrayante à la recherche d’indices.', 26124),
(131934, 'frFR', '', 'Un seigneur de l’effroi ? Et un dragon de bronze… Une minute, est-ce qu’il parle de moi ?', 26124),
(131935, 'frFR', '', 'Et on dirait bien qu’il a dévoilé sa position. Ha ! Rendons-nous au sanctuaire draconique Obsidien et éliminons-le !', 26124),
(131936, 'frFR', '', 'Heureusement pour nous, nous savons déjà qui tire les ficelles. Tuons ce seigneur de l’effroi avant qu’il ne me tue !', 26124),
(131937, 'frFR', '', 'Huh ! Je me demande ce que la Légion peut bien me vouloir.', 26124),
(131938, 'frFR', '', 'Hmm… un éclat de temps. Rapportons-le au Repos du ver. Je me demande quand et où il conduit.', 26124),
(131940, 'frFR', '', 'Nous pouvons aider !', 26124),
(131941, 'frFR', '', 'Nous pouvons aider, pas vrai ?', 26124),
(131942, 'frFR', '', 'Les rêveurs nous ont donné trois indices… un puissant cauchemar, près de l’eau, la paume du dragon. Nous devons juste comprendre ce qu’ils signifient.', 26124),
(131943, 'frFR', '', 'C’est parti !', 26124),
(131944, 'frFR', '', 'N’oubliez pas, le Satyre se trouve dans ces restes de griffe près de l’eau. Débarrassons-nous de lui !', 26124),
(131945, 'frFR', '', 'Étrange. Je ne me souviens pas avoir contrarié ce Satyre, que ce soit récemment ou dans l’avenir.', 26124),
(131946, 'frFR', '', 'Regardez ! Un éclat de temps. Nous devrions le rapporter au Repos du ver.', 26124),
(131947, 'frFR', '', 'Descendons et cherchons des indices. Les perturbations proviennent peut-être de celui ou celle qui veut me tuer.', 26124),
(131948, 'frFR', '', 'Évitons les lignes telluriques et rendez-nous directement auprès de ce seigneur du Vide. Le temps presse !', 26124),
(131949, 'frFR', '', 'Je ne m’attendais pas à me retrouver face à un SEIGNEUR DU VIDE. Pff.', 26124),
(131950, 'frFR', '', 'Et regardez ça… il transportait un éclat de temps. Je dois le rapporter au Repos du ver pour voir où il conduit.', 26124),
(131951, 'frFR', '', 'J’ai la désagréable impression que l’ennemi prévoit une attaque sur plusieurs plans dimensionnels à la fois. Sinon, pourquoi aurait-il besoin d’éclats de temps ?', 26124),
(131952, 'frFR', '', 'Je vois que ce que j’ai dit n’est pas clair. Pour faire simple, on m’attaque simultanément dans plusieurs époques de ma ligne temporelle.', 26124),
(131953, 'frFR', '', 'Ils savent vraiment ce qu’ils font ! Je ne serais pas surprise s’ils faisaient équipe avec un dragon de bronze.', 26124),
(131954, 'frFR', '', 'Intéressant… Un portail pour Andorhal. C’est un de mes endroits préférés de tous les temps ! Allons voir si j’ai des problèmes.', 26124),
(131955, 'frFR', '', 'Aha ! Un portail pour le mont Hyjal. J’y suis déjà allée deux ou trois mois. FOIS. Je voulais dire fois.', 26124),
(131956, 'frFR', '', 'Je vois… un portail pour Stratholme, à l’époque de la Troisième guerre.', 26124),
(131957, 'frFR', '', 'Ouah… Ce portail est vraiment ancien ! Il conduit au Puits d’éternité.', 26124),
(131958, 'frFR', '', 'Andorhal, quelques mois après le Cataclysme. Nous sommes au beau milieu d’un combat entre la Horde et l’Alliance.', 26124),
(131959, 'frFR', 'Le voilà ! Vous avez vos ordres. Tuez le dragon !', '', 26124),
(131960, 'frFR', '', 'Vous voyez, c’est l’un des inconvénients d’être gnome. Parfois, les soldats de la Horde ont le besoin irrépressible de vous donner des coups de pied.', 26124),
(131961, 'frFR', 'Soldats de l’Alliance ! Tenez bon ! Elle ne pourra pas se cacher indéfiniment.', '', 26124),
(131962, 'frFR', '', 'L’ALLIANCE en a aussi après moi ? Mais qu’est-ce qui se passe ?', 26124),
(131963, 'frFR', '', 'Je peux me débrouiller seule, mais je ne peux pas m’envoler avec ce canon pointé vers les cieux.', 26124),
(131964, 'frFR', '', 'Le canon est hors d’usage. Ça ira ?', 26124),
(131965, 'frFR', '', 'Je pense, oui. À la prochaine !', 26124),
(131966, 'frFR', '', 'Stratholme, lors de la Troisième guerre. Je me souviens de cette époque. Le prince Arthas ne s’y est pas présenté sous son meilleur jour.', 26124),
(131967, 'frFR', 'Chromie ! Loués soient les sables, vous voilà ! Ils vous ont conduite en ville !', '', 26124),
(131968, 'frFR', 'Je n’ai pas pu les repousser. Ils vous ont emmenée en ville !', '', 26124),
(131969, 'frFR', '', 'On dirait bien qu’il faut se rendre à Stratholme ! Dépêchons-nous, le temps presse !', 26124),
(131970, 'frFR', '', 'Beurk ! Cette créature n’a vraiment pas l’air commode. Mais nous n’avons pas le choix, nous allons devoir l’affronter.', 26124),
(131971, 'frFR', '', 'Merci beaucoup de m’avoir sauvée !', 26124),
(131972, 'frFR', '', 'Au plaisir !', 26124),
(131973, 'frFR', '', 'Voyons voir… Nous sommes au mont Hyjal, peu de temps après le Cataclysme.', 26124),
(131974, 'frFR', '', 'Je me souviens de ça ! Je devrais me trouver un peu plus loin.', 26124),
(131975, 'frFR', '', 'Mais je ne me souviens pas qu’il y ait eu autant d’élémentaires de feu par ici…', 26124),
(131976, 'frFR', '', 'Me voilà !', 26124),
(131977, 'frFR', '', 'Ahh, je suis blessée ! Je peux me soigner… mais j’ai besoin d’un peu plus de temps.', 26124),
(131978, 'frFR', '', 'Ne t’inquiète pas. Nous allons te protéger !', 26124),
(131979, 'frFR', '', 'Tu te sens mieux ?', 26124),
(131980, 'frFR', '', 'Ça va aller, je crois. Merci de votre aide !', 26124),
(131981, 'frFR', '', 'Le Puits d’éternité, juste avant la guerre des Anciens. Environ dix mille ans avant votre époque, $n. Enfin, plus ou moins.', 26124),
(131982, 'frFR', '', 'Oh non ! Me voilà !', 26124),
(131983, 'frFR', '', 'Ces blessures gangrenées sont profondes. Nous devons me ramener au Repos du ver.', 26124),
(131984, 'frFR', '', 'Il devrait y avoir un portail temporel de l’autre côté du Puits. Je connais le chemin. Suivez-moi !', 26124),
(131985, 'frFR', '', 'Voilà le portail ! Allons-y !', 26124),
(131986, 'frFR', '', 'Pfiou ! Je devrais être en sécurité, maintenant.', 26124),
(131987, 'frFR', '', 'Tout semble être… de retour à la normale. Les lignes temporelles sont plus nettes. Je ne me vois plus mourir.', 26124),
(131988, 'frFR', '', 'Tant mieux !', 26124),
(131989, 'frFR', '', 'Mais il y a encore quelques petites choses qui me tracassent…', 26124),
(131990, 'frFR', '', 'De nombreuses personnes semblaient déterminées à me tuer. Des démons, des élémentaires, des Morts-vivants, des seigneurs du Vide… Même la Horde et l’Alliance !', 26124),
(131991, 'frFR', '', 'Pourquoi sont-ils tous aussi remontés contre moi ? Je pense que nous devrions essayer de le découvrir un jour.', 26124),
(131992, 'frFR', '', 'Mais c’est un problème pour notre futur nous ! Ou plutôt, ton futur toi et mon moi passé. Ahh, ne t’inquiète pas. Le temps, c’est compliqué.', 26124),
(131993, 'frFR', '', 'À la prochaine fois, $n !', 26124),
(132005, 'frFR', '', 'Est-ce que c’est une clé de portail de Stratholme ? Ha ! Ça doit être notre jour de chance !', 26124),
(132006, 'frFR', '', 'Gardons-la, elle nous sera utile la prochaine fois que nous irons à Stratholme.', 26124),
(132007, 'frFR', '', 'Une balise de soufre… Fascinant !', 26124),
(132008, 'frFR', '', 'Je pense qu’elle peut nous servir à importuner les élémentaires de feu du mont Hyjal.', 26124),
(132011, 'frFR', '', 'La pierre de lune de Tyrande ? Où est-ce que vous avez trouvé ÇA ?', 26124),
(132012, 'frFR', '', 'Elle ne nous est pas très utile ici, mais peut-être qu’au Puits d’éternité…', 26124),
(132013, 'frFR', '', 'Intéressant… Ces documents indiquent que leur propriétaire est une sorte de ponte du Cercle cénarien.', 26124),
(132014, 'frFR', '', 'Nous pourrons peut-être en faire bon usage à Andorhal.', 26124),
(132018, 'frFR', 'Je ne fais qu’un avec la Lumière. La Lumière est avec moi.', '', 26124),
(132021, 'frFR', '', 'Hum… désolée pour ça.', 26124),
(132022, 'frFR', '', 'Très bien… Maintenant, je dois attaquer celui-ci…', 26124),
(132023, 'frFR', '', 'Il est temps que je prenne les choses en main !', 26124),
(132024, 'frFR', '', 'Le flux temporel ne va pas se réparer tout seul !', 26124),
(132025, 'frFR', '', 'C’est parti !', 26124),
(132026, 'frFR', '', 'Je suis plus puissante que j’en ai l’air, vous savez…', 26124),
(132027, 'frFR', '', 'Ooh ! Ton temps est écoulé !', 26124),
(132028, 'frFR', '', 'Désolée, mais… c’est comme ça que ça se passe !', 26124),
(132029, 'frFR', '', 'Oh, merveilleux ! Tout s’est bien passé !', 26124),
(132030, 'frFR', '', 'Ouais ! J’ai réussi !', 26124),
(132031, 'frFR', '', 'Non… Ça ne devait pas se passer comme ça…', 26124),
(132032, 'frFR', '', 'La prochaine fois, peut-être…', 26124),
(132033, 'frFR', '', 'On dirait que l’heure est venue pour moi… de…', 26124),
(132034, 'frFR', '', 'Ce n’est pas ça qui doit se passer…', 26124),
(132035, 'frFR', '', 'Désolée…', 26124),
(132036, 'frFR', '', 'Le temps soigne toutes les blessures… sauf… les mortelles…', 26124),
(132051, 'frFR', '', 'Arkhaan, c’est ça ? Pouvez-vous nous dire ce qui est arrivé à votre peuple ?', 26124),
(132052, 'frFR', 'Arkhaan le sait, oui.', '', 26124),
(132062, 'frFR', '', 'Rebonjour !', 26124),
(132063, 'frFR', 'Je suis prêt. Allons-y !', 'Je suis prête. Allons-y !', 26124),
(132064, 'frFR', '', 'Vous êtes $gprêt:prête; ? Le temps nous est compté… enfin, surtout pour moi.', 26124),
(132065, 'frFR', '', 'Essayons une fois de plus. Nous allons nous laisser UN PEU plus de temps avant mon assassinat.

$gPrêt:Prête; ?', 26124),
(132069, 'frFR', 'Regardez, la voie est fermée. Comment aller à Isolon, maintenant ?', '', 26124),
(132071, 'frFR', '', 'Je suis sûre que nous allons réussir à tirer cette affaire au clair. Faites-moi savoir quand vous serez $gprêt:prête;.', 26124),
(132072, 'frFR', 'L’eau est maudite. Ne succombez pas à la soif.', '', 26124),
(132073, 'frFR', 'Allons essayer de vous sauver une fois de plus !', 'Allons essayer de vous sauver une fois de plus !', 26124),
(132074, 'frFR', 'Les Man’ari tourmentent mon peuple avec leurs rituels de magie gangrenée. Purgeons leurs occultes paroles… par le feu !', '', 26124),
(132075, 'frFR', 'Le parchemin calciné que vous avez laissé sur place rappellera à la Légion que nul n’éteindra notre résistance. Merci.', '', 26124),
(132077, 'frFR', '<Vous voyez le coin d’une missive dépasser du brassard de la messagère.>', '', 26124),
(132078, 'frFR', '<Prendre la missive.>', '<Prendre la missive.>', 26124),
(132080, 'frFR', '<Ramasser le livre de codes.>', '<Ramasser le livre de codes.>', 26124),
(132082, 'frFR', '<Les yeux sans vie de la cryptographe sont rivés sur le ciel. Vous remarquez un opuscule, coincé sous son corps.>', '', 26124),
(132083, 'frFR', '', 'Bienvenue au Repos du ver, $gvoyageur temporel:voyageuse temporelle;. Le conseil se tient à votre disposition.', 26124),
(132084, 'frFR', '', 'Est-ce que je vais avoir des ennuis ?', 26124),
(132085, 'frFR', 'Je vois que Chronormu vous accompagne. Excusez ma curiosité, mais… venez-vous du futur ou du passé ?

À bien y réfléchir, ne vous donnez pas la peine de répondre. Mieux vaut laisser cette affaire au bronze.', '', 26124),
(132086, 'frFR', 'Votre aura est des plus étranges, $R. Votre présence a quelque chose de… surnaturel, comme si vous n’aviez pas votre place ici.

<Kalecgos baisse la tête et regarde Chromie.>.

Ah, je vois. Vous voyagez dans le temps. Cela… cela pourrait expliquer ce phénomène.

<Kalecgos vous observe avec méfiance.>', '', 26124),
(132087, 'frFR', 'Avez-vous remarqué quelque chose d’étrange ces derniers temps ?', 'Avez-vous remarqué quelque chose d’étrange ces derniers temps ?', 26124),
(132088, 'frFR', '', 'Les morts sont sortis de leurs tombes.

Le sanctuaire draconique Rubis est en conflit avec les Morts-vivants depuis fort longtemps. La situation s’était pourtant calmée après la chute du roi-liche, mais les incidents se multiplient depuis quelque temps.', 26124),
(132089, 'frFR', 'Oui. La gardienne du jardin du sanctuaire draconique Émeraude a le plus grand mal à protéger le sommeil des rêveurs. Plusieurs anciens se sont malencontreusement réveillés et nous ignorons toujours pourquoi.', '', 26124),
(132090, 'frFR', 'Pas particulièrement. Les lignes telluriques font de nouveau des leurs, mais cela n’a rien d’anormal dans la région.', '', 26124),
(132091, 'frFR', 'Je vois. Merci.', 'Je vois. Merci.', 26124),
(132097, 'frFR', '', 'Ça sonnait bien mieux dans ma tête.', 26124),
(132098, 'frFR', '', 'J’espère que vous trouverez ce Raalgar avant la Légion. Il y aura sans doute quelqu’un sur le Vindicaar pour vous aider.', 26124),
(132099, 'frFR', 'Vous avez entendu ?', '', 26124),
(132100, 'frFR', 'Non, non… non.', '', 26124),
(132101, 'frFR', 'Nnghh… Restez avec nous !', '', 26124),
(132102, 'frFR', 'Arrêtez ! N’écoutez pas !', '', 26124),
(132103, 'frFR', 'Ah !', '', 26124),
(132104, 'frFR', 'Chuuuut.', '', 26124),
(132108, 'frFR', 'Même torturé par la Légion, mon peuple s’est rebellé contre sa croisade maudite. Les démons ont peut-être brisé leur corps, mais pas leur volonté. Libérez leur esprit afin qu’ils reposent en paix.', '', 26124),
(132109, 'frFR', 'Les esprits de ceux qui ont résisté à la Légion nous inspirent tous.', '', 26124),
(132110, 'frFR', '', 'Rebonjour !', 26124),
(132115, 'frFR', '<Modifier les talents de Chromie.>', '<Modifier les talents de Chromie.>', 26124),
(132116, 'frFR', 'Ajustons notre stratégie.
|cFF0000FF(Modifier les talents de Chromie).|r', 'Ajustons notre stratégie.
|cFF0000FF(Modifier les talents de Chromie).|r', 26124),
(132118, 'frFR', 'Je vais prouver une fois pour toutes que seul un champion du tombeau peut régner en maître sur le monde du heavy metal.', '', 26124),
(132119, 'frFR', 'Luttez tant que vous le voudrez, vos corps finiront par geler et se briser !', '', 26124),
(132120, 'frFR', 'Viennent les ténèbres vagabondes et les banshees forment la ronde !', '', 26124),
(132121, 'frFR', 'J’invoque des goules depuis chaque tombe. Ça t’ fout les boules, adieu ton monde !', '', 26124),
(132122, 'frFR', 'Une âme de plus pour ma musique !', '', 26124),
(132123, 'frFR', 'Encore une âme pour mes armées !', '', 26124),
(132124, 'frFR', 'Les Sangliers noirs sont finis. Vos fans appartiennent désormais à mes armées des morts !', '', 26124),
(132125, 'frFR', 'Comment ?! Personne peut me battre !', '', 26124),
(132126, 'frFR', '|TInterface\\Icons\\INV_Axe_2H_UndeadGuitar_C_01.blp:20|tDes accords puissants pleuvent, utilisez-les pour |cFFFF0000|Hspell:245034|h[Abasourdir]|h|r vos ennemis !', '|TInterface\\Icons\\INV_Axe_2H_UndeadGuitar_C_01.blp:20|tDes accords puissants pleuvent, utilisez-les pour |cFFFF0000|Hspell:245034|h[Abasourdir]|h|r vos ennemis !', 26124),
(132127, 'frFR', 'Une fois que vous aurez atteint l’Arcatraz, je resterai en contact avec vous.', '', 26124),
(132153, 'frFR', 'Merci ! Merci !', '', 26124),
(132154, 'frFR', 'Tout sera détruit ! Il n’y a rien… que le Vide.', '', 26124),
(132155, 'frFR', 'Vous devez connaître la vérité !', '', 26124),
(132156, 'frFR', 'Arkhaan va vous faire comprendre !', '', 26124),
(132157, 'frFR', 'Pourquoi… ils n’écoutent… pas ?', '', 26124),
(132158, 'frFR', '', 'Je suis désolée que vous ayez dû payer ce prix. Reposez en paix maintenant.', 26124),
(132159, 'frFR', 'Je vais partir en avant nous frayer un chemin. Le pont menant au Xénédar a l’air d’être le moins surveillé. Que la Lumière soit avec nous.', '', 26124),
(132160, 'frFR', '', 'Qui est-ce ?', 26124),
(132161, 'frFR', 'Tu ne me retiendras pas, démon !', '', 26124),
(132162, 'frFR', 'Fareeya ! Vous avez survécu !', '', 26124),
(132163, 'frFR', '', 'Résistez à leur appel, Arkhaan !', 26124),
(132164, 'frFR', '', 'Non ! Ce que vous avez vu n’est qu’un mensonge !', 26124),
(132165, 'frFR', '', 'Il ne nous entend pas ! Nous devons mettre fin à ses souffrances.', 26124),
(132166, 'frFR', '', 'Nous le perdons !', 26124);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132167, 'frFR', '', 'Vous sentez ça ? Quelque chose nous retient…', 26124),
(132170, 'frFR', '', 'Arpenteur ?', 26124),
(132172, 'frFR', '', 'Pas aujourd’hui, monstre ! La Lumière va triompher !', 26124),
(132175, 'frFR', '', 'Vous savez bien que je refuse de mourir tant que la Légion n’est pas vaincue, grand exarque. Suivez-moi. Nous avons établi un périmètre sécurisé.', 26124),
(132176, 'frFR', 'Vous n’irez nulle part, « champion ». Le maître a des projets pour vous !', '', 26124),
(132202, 'frFR', '', 'Serviteurs ! À moi !', 26124),
(132204, 'frFR', '', 'Un effort vain, vermine !', 26124),
(132206, 'frFR', 'Je suis libre !', '', 26124),
(132207, 'frFR', 'Soyez purifiés, démons !', '', 26124),
(132208, 'frFR', 'Vous paierez pour vos crimes, infâmes démons !', '', 26124),
(132209, 'frFR', 'Vous ne souillerez bientôt plus ce monde !', '', 26124),
(132210, 'frFR', 'Les dévastateurs sont détruits. En avant toute !', '', 26124),
(132211, 'frFR', 'Qu’est-ce que c’était ?', '', 26124),
(132212, 'frFR', 'Montrez-vous !', '', 26124),
(132213, 'frFR', 'Un intrus ?', '', 26124),
(132214, 'frFR', 'Hmmm hahahaha.', '', 26124),
(132215, 'frFR', 'Qu’est-ce que c’est que ça ?', '', 26124),
(132216, 'frFR', '', 'Je vais vous trouver, intrus.', 26124),
(132217, 'frFR', '', 'Vous ne m’échapperez pas.', 26124),
(132218, 'frFR', '', 'Je vous vois.', 26124),
(132219, 'frFR', '', 'Ceci est notre royaume, créature de chair.', 26124),
(132220, 'frFR', '', 'Quelle arrogance.', 26124),
(132222, 'frFR', '', 'Comment osez-vous pénétrer dans notre royaume ?!', 26124),
(132223, 'frFR', '', 'Vous ne pouvez pas vous cacher dans ces ténèbres !', 26124),
(132224, 'frFR', '', 'Meurs, créature de chair !', 26124),
(132225, 'frFR', '', 'Que leur volonté soit faite !', 26124),
(132226, 'frFR', '', 'Ha ! Pathétique créature de chair.', 26124),
(132227, 'frFR', '', 'Vous pensiez pouvoir vous enfuir ?', 26124),
(132228, 'frFR', '', 'J’exécute leurs volontés.', 26124),
(132229, 'frFR', '', 'Votre chair vous trahit.', 26124),
(132230, 'frFR', '', 'Un camouflage ? Qu’avez-vous à dissimuler ?', 26124),
(132231, 'frFR', 'Je vais enfin pouvoir rentrer et préparer mon attaque. Vous pouvez rester ici… et mourir !', '', 26124),
(132232, 'frFR', 'Il reste 30 secondes !', '', 26124),
(132233, 'frFR', 'Il reste 10 secondes !', '', 26124),
(132234, 'frFR', '', 'Je vous couvre. Réessayez, tant que nous sommes en sécurité.', 26124),
(132238, 'frFR', '', 'Ce sera fait, grand inquisiteur !', 26124),
(132239, 'frFR', '', 'Chercheuses, couvrez le départ du grand inquisiteur. Je vais me charger de cette interruption !', 26124),
(132241, 'frFR', 'C’est MA journée, aujourd’hui ! J’suis un pirate, moi… Ouais, un vrai de vrai !

L’équipage d’l’effroi f’rait bien d’en prendre d’la graine !', '', 26124),
(132242, 'frFR', 'Z’avez organisé cette fête rien que pour moi, $pr ? … Vous devriez… boire un p’tit grog !', '', 26124),
(132244, 'frFR', '', 'La côte est dégagée. Essayez encore.', 26124),
(132245, 'frFR', '', 'Vous y êtes presque !', 26124),
(132246, 'frFR', '', 'Mais qu’est-ce que vous avez fait ?', 26124),
(132247, 'frFR', 'J’viens… pour fête… mais fêtes d’équipage de l’effroi pires que… FÊTES DES PANDASHAN !

Ha ha !', '', 26124),
(132248, 'frFR', '… et j’me contrefiche d’qui peut bien m’entendre !

J’espère que t’as pigé, De Mouza… De Miiiiizé… De Minusss !

Ha ha… Elle en a pris pour son grade…', '', 26124),
(132249, 'frFR', 'Si vous trouvez que CETTE fête ne prend pas l’eau de partout, attendez d’voir MA fête…

Vous aimez les poneys ?', '', 26124),
(132250, 'frFR', 'Le grog, le grog… J’adore le grog !
Le grog, le grog… C’est toujours en vogue !
Greg, Greg… Sers-moi m’en encore, Greg !
Sinon tu s’ras vite dég…

J’vous jure que j’viens d’improviser c’te chansonnette. On dirait pas, hein ?', '', 26124),
(132251, 'frFR', 'Ce crétin de Glousseplanche m’a envoyé… surveillance discrète… s’est jamais montré… J’ai une vie, moi aussi !', '', 26124),
(132252, 'frFR', 'Suffit de faire éclater un petit poney de rien du tout pour se faire virer d’la fête… Mais s’pas grave. J’m’en tape des poneys, moi…

Les poneys, c’est même pas des vrais pirates… Ils savent pas tirer au canon… Et ils ont même pas d’mains… Hééé…', '', 26124),
(132253, 'frFR', 'Où avez-vous trouvé ce poney gonflable ?', 'Où avez-vous trouvé ce poney gonflable ?', 26124),
(132255, 'frFR', 'Joyeux Jour des pirates ! Ça se fête, ventre-saint-gris !

Quand vous en aurez marre de la bringue saumâtre de l’équipage de l’effroi, mettez le cap vers le sud jusqu’à la plage… C’est là que les VRAIS pirates s’éclatent.

Vous y trouverez mes frères boucaniers de la Voile sanglante. Dites-leur que c’est l’vieux Moustaches qui vous envoie et peut-être qu’ils me laisseront revenir…', '', 26124),
(132256, 'frFR', 'ne se sent pas très bien…', '', 26124),
(132257, 'frFR', 'a l’estomac bien plein…', '', 26124),
(132258, 'frFR', 'a la peau du ventre bien tendue !', '', 26124),
(132268, 'frFR', 'Sautez dans la fosse quand vous êtes sous l’effet d’|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t |cFFFF0000|Hspell:240209|h[Âme instable]|h|r !', 'Sautez dans la fosse quand vous êtes sous l’effet d’|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t |cFFFF0000|Hspell:240209|h[Âme instable]|h|r !', 26124),
(132277, 'frFR', 'En surchargeant l’arme, nous attirerons les démons vers nous.', '', 26124),
(132278, 'frFR', 'Je vous suis.', 'Je vous suis.', 26124),
(132283, 'frFR', 'Bientôt, toute la Légion va s’abattre sur nous.', '', 26124),
(132284, 'frFR', 'Nous devons tenir notre position. Je ne peux que prier qu’il y ait des survivants dans l’armée de la Lumière.', '', 26124),
(132285, 'frFR', 'Elle résiste à mon sort. Ce n’est pas une simple arme de siège…', '', 26124),
(132286, 'frFR', 'Par la Lumière…', '', 26124),
(132295, 'frFR', 'Elle est vivante !', '', 26124),
(132298, 'frFR', 'Détournez son attention, Illidan. Nous ne sommes pas arrivés si loin pour échouer maintenant !', '', 26124),
(132299, 'frFR', 'Je vais faire bien plus que ça.', '', 26124),
(132300, 'frFR', 'La chute du Xénédar n’aura pas été vaine !', '', 26124),
(132301, 'frFR', 'Goûtez à dix mille ans de haine !', '', 26124),
(132302, 'frFR', 'Mon destin n’est pas de mourir de ta main, monstre. J’ai des comptes à régler avec ton maître.', '', 26124),
(132303, 'frFR', 'Tenez bon, $p. Le goliath faiblit !', '', 26124),
(132304, 'frFR', 'Capte la puissance des portails, Alleria ! Sers-t’en comme d’une arme !', '', 26124),
(132305, 'frFR', '', 'Si nous parvenons à capturer ce démon, je pourrai siphonner son énergie pour le maîtriser. Champions, je m’occupe de vous fournir les pièges, à charge pour vous de l’attraper.', 26124),
(132348, 'frFR', 'Hé, bas les pattes, c’est à nous, ça ! On l’a vu en premier !', '', 26124),
(132349, 'frFR', 'Vite, vite ! Que quelqu’un prévienne l’intendant !', '', 26124),
(132350, 'frFR', 'En voilà une trouvaille ! Bien, nous prenons le relais !', '', 26124),
(132352, 'frFR', 'Concentre-toi. Souviens-toi de ton entraînement.', '', 26124),
(132353, 'frFR', '', 'Arator ! Turalyon ?!', 26124),
(132354, 'frFR', 'Le Vide ne montre que des demi-vérités. Suis ton instinct.', '', 26124),
(132355, 'frFR', '', 'Je ne peux pas… je… Aaaargh !', 26124),
(132356, 'frFR', '', 'Je ne vous laisserai pas faire ! Vous n’avez aucun droit sur moi !', 26124),
(132357, 'frFR', '', 'Reculez, viles ténèbres.', 26124),
(132358, 'frFR', 'Mais bats-toi, enfin !', '', 26124),
(132359, 'frFR', 'N’oubliez pas de récupérer notre prix, créature de chair. Je vais m’occuper d’Alleria.', '', 26124),
(132360, 'frFR', 'Le cœur d’un demi-dieu. Ce n’est pas un simple trophée, Alleria.', '', 26124),
(132361, 'frFR', 'Prends-le, et tu n’en seras que plus près d’accomplir ton destin.', '', 26124),
(132362, 'frFR', '', 'Je comprends. Je vous remercie. Tous les deux.', 26124),
(132363, 'frFR', '', 'Ce froid…', 26124),
(132367, 'frFR', 'Ils se rapprochent. Préparez-vous, $p.', '', 26124),
(132368, 'frFR', '50 000 pièces d’or', '50 000 pièces d’or', 26124),
(132369, 'frFR', 'Ah, vous êtes en vie ! Une balise est en approche.', '', 26124),
(132370, 'frFR', 'Le peuple d’Hatuun m’a sauvé de la chute du Xénédar.', '', 26124),
(132371, 'frFR', 'Nombreux sont ceux qui n’ont pas eu ma chance. Ils défendent leur position près du site de l’impact, au péril de leur vie.', '', 26124),
(132372, 'frFR', 'Adieu pour l’instant.', '', 26124),
(132373, 'frFR', '', 'Salutations, $n. Vous ne vous souvenez sûrement pas de moi, nous avons fait connaissance la semaine prochaine. Voulez-vous retourner au Temple noir ?', 26124),
(132375, 'frFR', 'Envoyez-moi au Temple noir (raid des marcheurs du temps).', 'Envoyez-moi au Temple noir.', 26124),
(132378, 'frFR', 'Salutations, et bienvenue au Mythic Invitational !

Je peux vous téléporter dans le donjon de Legion de votre choix.

Assurez-vous de bien sélectionner le mode mythique avant de vous téléporter.', '', 26124),
(132379, 'frFR', 'Je suis d’accord. J’ai aperçu des esclaves de la Légion qui s’enfuyaient devant notre attaque.', '', 26124),
(132380, 'frFR', 'Ils pourraient se révéler de précieux alliés dans notre combat.', '', 26124),
(132381, 'frFR', 'Je veux me rendre à Karazhan (donjon).', 'Je veux me rendre à Karazhan (donjon).', 26124),
(132382, 'frFR', 'Vous présumez totalement de leur loyauté. Risquez votre vie si vous le voulez, moi, je vais préparer nos soldats à essuyer l’inévitable contre-attaque.', '', 26124),
(132383, 'frFR', 'Comme vous voudrez. Venez, $p, je sens leur présence non loin d’ici.', '', 26124),
(132384, 'frFR', 'Tous mes semblables n’ont pas quitté Argus quand Archimonde et Kil’jaeden ont scellé leur pacte avec le titan noir.', '', 26124),
(132385, 'frFR', 'Nombreux furent ceux qui rejoignirent la Légion de leur plein gré, succombant aux chimères de Sargeras, qui leur promettaient puissance et gloire.', '', 26124),
(132386, 'frFR', 'Ceux qui virent la vérité cherchèrent à fuir, mais se retrouvèrent piégés dans ce cauchemar. J’ignore comment ils ont pu survivre depuis.', '', 26124),
(132387, 'frFR', 'Ramenez les talbuks aux dresseurs krokuls, à l’orée de la forêt !', 'Ramenez les talbuks aux dresseurs krokuls, à l’orée de la forêt !', 26124),
(132388, 'frFR', 'Placez la balise sur ma position. Nous rentrons.', '', 26124),
(132389, 'frFR', 'Nos troupes vont maintenant sécuriser le Xénédar. Même si nous avons récupéré son précieux chargement, le vaisseau ne doit pas tomber entre les mains de la Légion.', '', 26124),
(132390, 'frFR', '', '<Insérer une séquence JdR où elle absorbe le cœur de Nhal’atoth.>', 26124),
(132409, 'frFR', '', 'La pire blessure dont nous ayons eu à souffrir, c’est notre peuple lui-même qui nous l’a infligée en nous trahissant de la sorte. Aujourd’hui encore, après tant d’années, elle n’est toujours pas refermée.$b$bCe genre de blessures doit faire l’objet d’une purification en profondeur. Il faut en extraire la putréfaction et la détruire avant que la véritable guérison ne puisse commencer.', 26124),
(132410, 'frFR', '', 'Quelqu’un a demandé un médecin ? Pas de chance, voilà la Légion qui débarque !', 26124),
(132411, 'frFR', '', 'Vous êtes mal en point ? Vous m’avez l’air en pleine forme. Un bon repas, et je parie que vous serez d’attaque en moins de deux.', 26124),
(132412, 'frFR', '', 'Ces traîtres n’ont aucune chance de nous vaincre, car la Lumière guide nos pas.', 26124),
(132413, 'frFR', 'Leur prochain tir nous décimera, à moins que nous frappions les premiers.', '', 26124),
(132414, 'frFR', 'Nous devons détruire l’arme tant qu’elle recharge ! Romuul, déployez une balise en bas !', '', 26124),
(132417, 'frFR', 'Balise déployée, prophète !', '', 26124),
(132418, 'frFR', '', 'Venez-vous pour nous offrir quelques instants de répit face à cette marée incessante ?', 26124),
(132419, 'frFR', 'Activation de la matrice de transport.', '', 26124),
(132420, 'frFR', 'Quand vous voulez, $p.', '', 26124),
(132421, 'frFR', '', 'Peu d’entre nous continuent à manier la véritable magie après avoir vu ce qui a tenté nos frères. J’exploiterai tous les avantages à ma disposition.', 26124),
(132422, 'frFR', '', 'C’est grâce à nos lames et nos sortilèges que nous résistons à nos ennemis. Tout est question d’équilibre, nous ne pouvons trop privilégier l’un ou l’autre.', 26124),
(132423, 'frFR', '', 'Bormos, que vous voyez là-bas, a un dicton tout à fait adapté à notre situation actuelle : « Donnez-moi une centaine de combattants sancteforge ou, à défaut, un millier d’unités régulières. »', 26124),
(132424, 'frFR', 'Ennemi détecté. Déploiement de l’arsenal.', '', 26124),
(132425, 'frFR', '', 'Nos frères se sont laissé aveugler par la convoitise et la soif de pouvoir. J’ai foi en la Lumière et j’ai tout le pouvoir nécessaire pour leur faire comprendre leurs erreurs.', 26124),
(132426, 'frFR', 'Combattants ennemis détectés. Niveau de menace minime.', '', 26124),
(132427, 'frFR', 'Cibles éliminées.', '', 26124),
(132428, 'frFR', 'Défaillance système critique…', '', 26124),
(132429, 'frFR', 'Cibles à exterminer acquises.', '', 26124),
(132430, 'frFR', 'Canon prêt pour l’annihilation.', '', 26124),
(132431, 'frFR', 'Systèmes d’armement amorcés, cible verrouillée.', '', 26124),
(132432, 'frFR', 'Pas de quartier.', '', 26124),
(132433, 'frFR', 'Résolution apocalyptique enclenchée.', '', 26124),
(132434, 'frFR', 'Systèmes ré-enclenchés, redirection de l’énergie. Systèmes d’armement amorcés.', '', 26124),
(132435, 'frFR', 'Un tir, un mort.', '', 26124),
(132436, 'frFR', 'Nous ne connaîtrons pas la paix tant que ces vils démons respireront.$b$bEt nous ne pardonnerons rien tant que les traîtres infidèles vivront.', '', 26124),
(132437, 'frFR', 'Je peux comprendre qu’une proie veuille prendre la fuite, mais tout ce qu’elle y gagne, c’est de mourir épuisée.', '', 26124),
(132438, 'frFR', 'Ils nous ont encore cernés. Ils n’apprendront donc jamais, ces imbéciles…', '', 26124),
(132439, 'frFR', '', 'Enlevez vos grolles, chopez-vous un grog et racontez-moi une blague !', 26124),
(132440, 'frFR', 'Ouais, racontez-moi une blague.', 'Ouais, racontez-moi une blague.', 26124),
(132441, 'frFR', 'Vos blagues sont les meilleures !', 'Vos blagues sont les meilleures !', 26124),
(132442, 'frFR', 'Vos blagues sont pourries !', 'Vos blagues sont pourries !', 26124),
(132443, 'frFR', 'La Lumière guide ma flèche. Les ténèbres ne sauraient échapper à sa glorieuse incandescence.', '', 26124),
(132445, 'frFR', '', 'Ah ouais ? Ben, t’es moche comme un pou borgne… et ta mère aussi !', 26124),
(132446, 'frFR', '', 'Ha ! J’aimerais bien vous voir faire mieux, clampin d’eau douce !', 26124),
(132447, 'frFR', '', 'Allez donc vous j’ter par-d’ssus bord, bougre d’buveur d’eau de fond d’cale.', 26124),
(132448, 'frFR', '', 'J’vais vous vider comme un poisson !', 26124),
(132449, 'frFR', '', 'Bouclez-la ou j’vous embroche, pauvre pirate à la petite semaine !', 26124),
(132451, 'frFR', '', 'Fermez votre clapet à grog frelaté et allez pioncer avec la poiscaille, fils de mangeur de biscuits !', 26124),
(132452, 'frFR', '', 'Allez vous faire couper les tifs par Joseph-Guy Yotin et laissez les vannes aux vieux loups de mer.', 26124),
(132454, 'frFR', '', 'Soyez maudits, vous et tous les cafards qui vous servent d’amis !', 26124),
(132455, 'frFR', '', 'Z’êtes bien aimable pour $gun vieux loup de mer:une vieille louve de mer;.', 26124),
(132456, 'frFR', '', 'J’vais vous étrip… Oh, vous avez aimé ? Merci. Personne ne m’encourage jamais.', 26124),
(132457, 'frFR', '', 'C’est du véritable humour de pirate, fruit d’innombrables pillages et voyages en mer.', 26124),
(132458, 'frFR', '', 'Ventre-saint-gris ! Coupez le grand bras de vergue !', 26124),
(132459, 'frFR', '', 'Pas de corne de brume ? Merci infiniment, l’$gami:amie;.', 26124),
(132460, 'frFR', '', 'Morbleu ! Alors, faut me payer une bonne gnôle !', 26124),
(132462, 'frFR', '', 'Merci, matelot. Les trésors ne se cachent pas toujours au fond d’un coffre.', 26124),
(132463, 'frFR', '', 'Très bien. Verrouillez vos écoutilles, matelots. Celle-là va vous arracher le gouvernail…', 26124),
(132464, 'frFR', '', 'Morbleu ! Qu’on m’apporte un grog !', 26124),
(132465, 'frFR', '', 'Je picolais avec un canonnier de l’équipage de l’effroi la semaine dernière à Baie-du-Butin…', 26124),
(132466, 'frFR', '', 'Après quelques verres, il m’a regardée dans le blanc des yeux et m’a demandé comment la Voile sanglante était devenue si célèbre…', 26124),
(132467, 'frFR', '', 'J’ai levé ma chope et je lui ai dit que c’était surtout grâce à nos ARRRtilleurs !', 26124),
(132468, 'frFR', 'Venez, montrons à Sargeras et consorts ce qui les attend.', '', 26124),
(132469, 'frFR', 'Tenez votre position ! Nous devons protéger le Vindicaar au péril de nos vies !', '', 26124),
(132470, 'frFR', 'Bonjour, $p ! Venez en apprendre plus sur les fils de la lune à la fête des séléniens de Reflet-de-Lune.', '', 26124),
(132471, 'frFR', 'La fête des séléniens approche ! Venez à Reflet-de-Lune dès le début des festivités pour tout savoir à leur sujet !', '', 26124),
(132472, 'frFR', 'La fête des séléniens va bientôt commencer ! Pensez à vous rendre à Reflet-de-Lune dès le début des festivités pour en savoir plus !', '', 26124),
(132473, 'frFR', 'Venez découvrir le mode de vie des séléniens à la fête de Reflet-de-Lune !', '', 26124),
(132474, 'frFR', '', 'Je me faisais percer les oreilles par Duncan « la belle gueule » sur le Fiers-à-Flot, hier…', 26124),
(132475, 'frFR', '', 'Vous le connaissez, c’est un perfectionniste. Ça lui a pris deux bonnes heures, et à la fin, quand je lui ai dit à quel point j’étais contente de son boulot…', 26124),
(132476, 'frFR', '', 'Il a piqué un phare avant de se descendre un canon !', 26124),
(132477, 'frFR', '', 'Vous savez que le capitaine Sabot-de-Sel a eu son premier vaisseau étonnamment vite, pas vrai ?', 26124),
(132478, 'frFR', '', 'Je lui ai demandé comment il avait réussi à soudoyer l’amiral pour arriver à ses fins et il m’a révélé son secret…', 26124),
(132479, 'frFR', '', 'Il a ramé comme un galérien !', 26124),
(132480, 'frFR', '', 'C’est une devinette…', 26124),
(132481, 'frFR', '', 'Qu’est-ce qui a six jambes, six mains et six yeux ?', 26124),
(132482, 'frFR', '', 'Six pirates !', 26124),
(132483, 'frFR', '', 'Vous connaissez tous ce cinglé de contre-amiral Glousseplanche, pas vrai ?', 26124),
(132484, 'frFR', '', 'Mais est-ce que vous savez qu’il a utilisé ses gadgets gnomes pour croiser un perroquet et un requin afin de se créer le compagnon de pirate ultime ?', 26124),
(132485, 'frFR', '', 'Il était plutôt satisfait du résultat… jusqu’à ce que sa bestiole lui bouffe une oreille !', 26124),
(132486, 'frFR', '', 'C’est quoi, le problème avec les coffres au trésor de nos jours ? Ils coûteux les yeux de la tête…', 26124),
(132487, 'frFR', '', 'Toutes ces dorures brillantes et ces serrures incrustées de gemmes… À croire qu’on tient à ce qu’on nous les pique !', 26124),
(132488, 'frFR', '', 'C’est à se demander si nos trésors sont dessus ou dedans.', 26124),
(132489, 'frFR', 'Vos parents sont encore en vie, Arator. J’en suis certain. Mais pour le moment, concentrons-nous sur le combat à venir.', '', 26124),
(132496, 'frFR', 'Nous sommes légion !', 'Nous sommes légion !', 26124),
(132497, 'frFR', 'J’incarne la fureur d’un millier de mondes à genoux.', 'J’incarne la fureur d’un millier de mondes à genoux.', 26124),
(132498, 'frFR', 'Vous n’avez vu qu’une infime partie de notre puissance.', 'Vous n’avez vu qu’une infime partie de notre puissance.', 26124),
(132499, 'frFR', 'Je serai loué pour votre disparition !', 'Je serai louée pour votre disparition !', 26124),
(132500, 'frFR', 'Azeroth tombera !', 'Azeroth tombera !', 26124),
(132501, 'frFR', 'Vous osez venir sur notre monde ?', 'Vous osez venir sur notre monde ?', 26124),
(132502, 'frFR', 'Inclinez-vous devant les armées du maître !', 'Inclinez-vous devant les armées du maître !', 26124),
(132503, 'frFR', 'Vous allez connaître la véritable souffrance !', 'Vous allez connaître la véritable souffrance !', 26124),
(132504, 'frFR', '', 'Nous sommes légion !', 26124),
(132505, 'frFR', '', 'J’incarne la fureur d’un millier de mondes à genoux.', 26124),
(132506, 'frFR', '', 'Vous n’avez vu qu’une infime partie de notre puissance.', 26124),
(132507, 'frFR', '', 'Je serai louée pour votre disparition !', 26124),
(132508, 'frFR', '', 'Azeroth tombera !', 26124),
(132509, 'frFR', '', 'Vous osez venir sur notre monde ?', 26124),
(132510, 'frFR', '', 'Inclinez-vous devant les armées du maître !', 26124),
(132511, 'frFR', '', 'Vous allez connaître la véritable souffrance !', 26124),
(132512, 'frFR', 'Vous brûlerez dans les flammes de Sargeras !', 'Vous brûlerez dans les flammes de Sargeras !', 26124),
(132513, 'frFR', 'Du carburant pour la corruption.', 'Du carburant pour la corruption.', 26124),
(132514, 'frFR', 'Personne ne peut arrêter notre croisade !', 'Personne ne peut arrêter notre croisade !', 26124),
(132515, 'frFR', 'Azeroth sera à nous.', 'Azeroth sera à nous.', 26124),
(132516, 'frFR', 'Dévoilez-moi votre âme.', 'Dévoilez-moi votre âme.', 26124),
(132517, 'frFR', 'Le chaos règne en maître.', 'Le chaos règne en maître.', 26124),
(132518, 'frFR', 'Tous s’inclineront devant le Destructeur.', 'Tous s’inclineront devant le Destructeur.', 26124),
(132519, 'frFR', 'Vous êtes perdus.', 'Vous êtes perdus.', 26124),
(132520, 'frFR', '', 'Vous brûlerez dans les flammes de Sargeras !', 26124),
(132521, 'frFR', '', 'Du carburant pour la corruption.', 26124),
(132522, 'frFR', '', 'Personne ne peut arrêter notre croisade !', 26124),
(132523, 'frFR', '', 'Azeroth sera à nous.', 26124),
(132524, 'frFR', '', 'Dévoilez-moi votre âme.', 26124),
(132525, 'frFR', '', 'Le chaos règne en maître.', 26124),
(132526, 'frFR', '', 'Tous se prosterneront devant le Destructeur.', 26124),
(132527, 'frFR', '', 'Vous êtes perdus.', 26124),
(132528, 'frFR', 'Prêtez-moi main-forte, $p. Nous terminerons ceci ensemble !', '', 26124),
(132529, 'frFR', 'Aardon’sha, kir kah’los !', '', 26124),
(132530, 'frFR', '', 'Il est écrit ici que leur chef se trouve sur un de ces disques flottant au-dessus de nous. Il est temps de s’occuper de lui !', 26124),
(132535, 'frFR', 'Nous vous rejoindrons près de l’arme, $p.', '', 26124),
(132538, 'frFR', 'Vous devez arrêter… le grand cauchemar…', '', 26124),
(132539, 'frFR', 'Cherchez la réponse… au bord de l’eau…', '', 26124),
(132540, 'frFR', 'Votre assaillant se trouve… dans la paume du dragon…', '', 26124),
(132542, 'frFR', 'Prévenez-moi quand vous voudrez commencer. Nous aurons sans doute de la compagnie d’ici peu.', '', 26124),
(132543, 'frFR', '', '<L’essence d’Eonar flotte devant vous. Si sa beauté et sa pureté restent palpables, vous percevez nettement sa tristesse mâtinée de terreur.>', 26124),
(132546, 'frFR', 'Nous vous défendrons, Lieuse-de-Vie.', 'Nous vous défendrons, Lieuse-de-Vie.', 26124),
(132551, 'frFR', 'Je suis prêt à me rendre à l’Arcatraz.', 'Je suis prête à me rendre à l’Arcatraz.', 26124),
(132552, 'frFR', 'Salutations.', '', 26124),
(132553, 'frFR', 'Sortez le grand jeu ! L’épreuve du style va bientôt commencer !', '', 26124),
(132554, 'frFR', 'Hé, $p. Il faut vraiment que vous fassiez un effort vestimentaire. L’épreuve du style va bientôt commencer !', '', 26124),
(132555, 'frFR', 'Allez voir le tisse-dimensions Tuviss ou n’importe quel autre transmogrifieur pour participer à l’épreuve du style !', '', 26124),
(132556, 'frFR', 'Vous pensez être à la pointe de la mode ? Allez voir le tisse-dimensions Tuviss ou tout autre transmogrifieur pour participer à l’épreuve du style !', '', 26124),
(132557, 'frFR', 'Au secours…', '', 26124),
(132558, 'frFR', 'Faites cesser ce tourment…', '', 26124),
(132559, 'frFR', 'L’ennemi… est… dans le rêve…', '', 26124),
(132561, 'frFR', 'Qu’est-ce que vous aviez dit, déjà ?', 'Qu’est-ce que vous aviez dit, déjà ?', 26124),
(132567, 'frFR', '', 'Il faut travailler vos pas de danse, $p ! On va organiser des soirées dansantes à Hurlevent et Orgrimmar.', 26124),
(132568, 'frFR', '', 'On va réserver les hôtels des ventes de Hurlevent et d’Orgrimmar pour faire la fête ! J’espère bien vous y voir !', 26124),
(132569, 'frFR', '', 'Allez, et que ça danse ! Nous avons réservé les hôtels des ventes de Hurlevent et d’Orgrimmar pour faire la fête !', 26124),
(132570, 'frFR', '', 'Venez avec votre bonne humeur aux hôtels des ventes de Hurlevent et d’Orgrimmar pour des soirées dansantes inoubliables !', 26124),
(132577, 'frFR', 'Quand vous voudrez.', 'Quand vous voudrez.', 26124),
(132578, 'frFR', '', 'Je crois que nous ferions bien de commencer notre enquête en nous adressant à un dragon de bronze.', 26124),
(132582, 'frFR', 'Le Kirin Tor va offrir une tournée des tavernes, et c’est pour bientôt ! Rendez-vous à l’Abracadabar dès le début des festivités pour vous rincer le gosier et vous remplir la panse !', '', 26124),
(132583, 'frFR', 'Je sais que ce sanctuaire est abandonné depuis des années, mais des squelettes boiteux ? Vraiment ? Père n’aurait jamais approuvé pareille ignominie.', '', 26124),
(132584, 'frFR', 'Moi ? Mais pourquoi tout le monde soupçonne toujours les dragons noirs ? Cela m’emplit de honte, Chronormu.$b$bNon, je ne suis au courant d’aucune attaque. Je visitais juste le Norfendre… par curiosité, dirons-nous. Mais j’ai été surpris de découvrir que notre sanctuaire draconique bien-aimé était infesté de squelettes. Alors, si vous cherchez quelqu’un qui pourrait en vouloir à un dragon, je vous conseille de regarder du côté de ces morts-vivants, et de quiconque les contrôle.', '', 26124),
(132585, 'frFR', '', 'Comment puis-je vous aider ?', 26124),
(132586, 'frFR', '', 'C’est peu de le dire. En général, on ne voit qu’une ou deux goules débarquer chaque jour, mais aujourd’hui, elles ont lancé une attaque d’une ampleur que nous n’avions plus connue depuis près de dix ans.', 26124),
(132587, 'frFR', '', 'Oui ? Que puis-je faire pour vous ?', 26124),
(132588, 'frFR', '', 'Oui. Les rêveurs sont agités depuis quelque temps. Nous ne savons plus où donner de la tête.', 26124),
(132589, 'frFR', 'Oui ? Que peut bien vouloir le Vol draconique de bronze ?', '', 26124),
(132590, 'frFR', 'Franchement, je n’en sais rien. Mais c’est possible. Les lignes telluriques ont toujours été capricieuses dans la région, mais elles se comportent vraiment bizarrement aujourd’hui. Quelque chose les perturbe.', '', 26124),
(132591, 'frFR', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie. Nous espérions que vous pourriez nous en apprendre davantage.', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie. Nous espérions que vous pourriez nous en apprendre davantage.', 26124),
(132592, 'frFR', 'Compris.', 'Compris.', 26124),
(132593, 'frFR', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie et nous avons appris que vous aviez maille à partir avec des Morts-vivants depuis quelque temps.', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie et nous avons appris que vous aviez maille à partir avec des Morts-vivants depuis quelque temps.', 26124),
(132594, 'frFR', 'Nous vous aiderons à défendre le sanctuaire draconique.', 'Nous vous aiderons à défendre le sanctuaire draconique.', 26124),
(132595, 'frFR', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie. Avez-vous remarqué quelque chose d’étrange dernièrement ?', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie. Avez-vous remarqué quelque chose d’étrange dernièrement ?', 26124),
(132596, 'frFR', 'Nous pouvons vous aider.', 'Nous pouvons vous aider.', 26124),
(132597, 'frFR', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie et nous avons entendu dire que vous avez des problèmes avec les lignes telluriques. Ces deux évènements pourraient-ils être liés ?', 'Nous tentons de découvrir qui s’apprête à attaquer Chromie et nous avons entendu dire que vous avez des problèmes avec les lignes telluriques. Ces deux évènements pourraient-ils être liés ?', 26124),
(132598, 'frFR', 'Nous pouvons vous aider.', 'Nous pouvons vous aider.', 26124),
(132610, 'frFR', 'La source de l’immortalité de Raalgar s’est tarie. Vous pouvez enfin le tuer et récupérer le cœur gangrené d’Argus.', '', 26124),
(132612, 'frFR', 'J’espère que vous avez soif, $p ! Allez voir Anebria Solvin à l’Abracadabar pour participer à la tournée des tavernes du Kirin Tor !', '', 26124),
(132618, 'frFR', 'La tournée des tavernes du Kirin Tor, c’est l’occasion rêvée de se rincer le gosier et de festoyer en joyeuse compagnie ! Rendez-vous à l’Abracadabar et adressez-vous à Anebria Solvin !', '', 26124),
(132630, 'frFR', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t Vous êtes la cible de |cFFF00000|Hspell:244536|h[Bombardement gangrené]|h|r !', '', 26124),
(132631, 'frFR', '|TInterface\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t %s alimente la |cFFF00000|Hspell:244152|h[Résolution apocalyptique]|h|r !', '', 26124),
(132632, 'frFR', '', 'Nous devons leur porter secours, Turalyon. J’irai en éclaireuse derrière les lignes ennemies pour faire diversion. Nous reviendrons bientôt, Arator.', 26124),
(132633, 'frFR', '', 'Et que se passera-t-il ? Elle m’a fait jeter en cellule pour avoir étudié le Vide contre sa volonté. Va-t-elle m’enfermer à nouveau ? Ou pire ?', 26124),
(132637, 'frFR', 'De quoi s’agit-il, Romuul ?', 'De quoi s’agit-il, Romuul ?', 26124),
(132638, 'frFR', 'Pour un vaisseau neuf, la liste des réparations du Vindicaar est sans fin. Comment puis-je vous aider ?', '', 26124),
(132639, 'frFR', 'Que se passera-t-il si la Légion trouve la pierre avant nous ?', 'Que se passera-t-il si la Légion trouve la pierre avant nous ?', 26124),
(132640, 'frFR', 'REUSE ME', '', 26124),
(132641, 'frFR', 'REUSE ME', '', 26124),
(132642, 'frFR', 'Pouvez-vous me dire où chercher ?', 'Pouvez-vous me dire où chercher ?', 26124),
(132644, 'frFR', 'Merci, Romuul.', 'Merci, Romuul.', 26124),
(132658, 'frFR', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|tLe capitaine Yathae Heurtelune vise une cible avec |cFFFF0000|Hspell:236304|h[Tir incorporel]|h|r !', 26124),
(132659, 'frFR', '', '|TInterface\\Icons\\ABILITY_DRUID_ECLIPSE.BLP:20|tLa prêtresse Pyroluna a lancé |cFFFF0000|Hspell:233263|h[Étreinte de l’éclipse]|h|r !', 26124),
(132660, 'frFR', '', '|TInterface\\Icons\\ABILITY_UPGRADEMOONGLAIVE.BLP:20|tLa chasseresse Kasparianne lance |cFFFF0000|Hspell:236480|h[Profusion de glaives]|h|r !', 26124),
(132664, 'frFR', 'Une armée de démons menace de nouveau le Vindicaar. Renvoyez leurs âmes fétides hanter les salles d’Antorus.', '', 26124),
(132665, 'frFR', 'Beau combat. Si la Légion parvenait à abattre le Vindicaar, Argus serait notre tombe.', '', 26124),
(132685, 'frFR', 'Beau travail. Velen et moi vous retrouverons à la Couronne de la destruction pour arrêter les antéens tant que nous le pouvons encore.', '', 26124),
(132686, 'frFR', 'Préparez-vous à embarquer à bord du Vindicaar. Raalgar sera bientôt prêt.', 'Préparez-vous à embarquer à bord du Vindicaar. Raalgar sera bientôt prêt.', 26124),
(132687, 'frFR', 'Oui, mon capitaine !', 'Oui, mon capitaine !', 26124),
(132689, 'frFR', 'J’y étais presque ! Vous n’êtes pas digne de m’arrêter, vermisseau !', '', 26124),
(132694, 'frFR', '', 'Et que se passera-t-il ? Elle m’a fait jeter en cellule pour avoir utilisé le pouvoir du Vide. Va-t-elle me mettre aux fers pour insubordination ? Ou pire encore ?', 26124),
(132695, 'frFR', 'Je détecte Xe’ra dans la pièce centrale. Louée soit la Lumière ! Nous n’arrivons pas trop tard.', '', 26124),
(132697, 'frFR', 'Xe’ra verra que tu as risqué ta vie pour la sauver. Cela restaurera sa confiance en toi, j’en suis certain !', '', 26124),
(132698, 'frFR', 'Venez. Aidez-moi à la guider jusqu’au Vindicaar. Ensuite, nous pourrons partir d’ici !', '', 26124),
(132699, 'frFR', 'Xe’ra ! Ne vous inquiétez pas, vous êtes en sécurité maintenant.', '', 26124),
(132700, 'frFR', '', 'Le pont supérieur du vaisseau est dans cette direction. Xe’ra aura beaucoup de choses à nous dire… à tous.', 26124),
(132701, 'frFR', '', 'Oh, mais je ne fais que commencer. Elle fera un magnifique trophée pour le Trône ardent !', 26124),
(132702, 'frFR', '', 'Non ! Ce trophée m’appartient ! C’est un cadeau pour notre grand maître !', 26124),
(132703, 'frFR', '', 'Vous finirez par perdre. Les sœurs y veill…', 26124),
(132704, 'frFR', 'Attention !', '', 26124),
(132705, 'frFR', 'Quoi qu’elle puisse bien être, cette chose n’était sans doute qu’une pièce de l’arsenal de Sargeras.', '', 26124),
(132708, 'frFR', 'Je vais supporter le gros de ses attaques aussi longtemps que je pourrai, mais vous devez le détruire tant que nous résistons encore !', '', 26124),
(132709, 'frFR', 'Ne perdons pas de temps. Battons-nous, ensemble.', '', 26124),
(132715, 'frFR', '', 'Archenon poros, prophète. L’armée de la Lumière se tient à vos côtés.', 26124),
(132716, 'frFR', 'Nous cherchons le cachet de l’Éveil. Archimonde l’a peut-être laissé dans le Conservatorium.', '', 26124),
(132717, 'frFR', '', 'Compris. J’ai la personne idéale pour ce travail : Y’mera.', 26124),
(132718, 'frFR', '', 'À vos ordres, capitaine.', 26124),
(132719, 'frFR', '', 'Enaara, assurez-vous que ces esprits restent tranquilles.', 26124),
(132720, 'frFR', 'Plus qu’une minute avant que les Sangliers noirs ne montent sur scène ! Rejoignez-nous vite au chaudron du Rock, à l’est de l’île.', '', 26124),
(132721, 'frFR', '', 'Les autres, sécurisez la zone.', 26124),
(132722, 'frFR', '|TInterface\\Icons\\WARRIOR_DISRUPTINGSHOUT.BLP:20|tDevlynn Styx se précipite pour déchaîner ses |cFFFF0000|Hspell:245150|h[Cris]|h|r contre le chevalier Dess Métal !', '|TInterface\\Icons\\WARRIOR_DISRUPTINGSHOUT.BLP:20|tDevlynn Styx se précipite pour déchaîner ses |cFFFF0000|Hspell:245150|h[Cris]|h|r contre le chevalier Dess Métal !', 26124),
(132723, 'frFR', '|TInterface\\Icons\\SPELL_DEATHKNIGHT_ARMYOFTHEDEAD.BLP:20|tLe chevalier Dess Métal invoque une |cFFFF0000|Hspell:245162|h[Armée des morts]|h|r pour attaquer Devlynn Styx !', '|TInterface\\Icons\\SPELL_DEATHKNIGHT_ARMYOFTHEDEAD.BLP:20|tLe chevalier Dess Métal invoque une |cFFFF0000|Hspell:245162|h[Armée des morts]|h|r pour attaquer Devlynn Styx !', 26124),
(132726, 'frFR', 'Voilà la dragonne ! Traqueurs gangrenés, occupez-vous d’elle !', '', 26124),
(132728, 'frFR', '', 'Hmm. Le Gardien de la porte est inactif.', 26124),
(132729, 'frFR', '', 'Grâce au pouvoir du sceau, nous pouvons gagner directement la chambre de l’Avatar.', 26124),
(132730, 'frFR', 'Se téléporter vers la chambre de l’Avatar.', 'Se téléporter vers la chambre de l’Avatar.', 26124),
(132731, 'frFR', 'Il faut arrêter la Légion !', '', 26124),
(132732, 'frFR', 'Retourner à la Brèche.', 'Retourner à la Brèche.', 26124),
(132738, 'frFR', '', 'Vous avez vu l’heure ! Il ne reste quasiment plus que dix minutes…', 26124),
(132739, 'frFR', '', 'Il ne reste que cinq minutes. Vous croyez que nous aurons fini à temps ?', 26124),
(132740, 'frFR', '', 'Plus qu’une minute. Ça risque d’être un peu juste, non ?', 26124),
(132741, 'frFR', '', 'Je sens qu’un trésor est à proximité.', 26124),
(132742, 'frFR', '', 'Vous le ressentez ? Il y a un trésor dans les parages.', 26124),
(132743, 'frFR', '', 'Halte !', 26124),
(132744, 'frFR', '', 'On ne bouge plus !', 26124),
(132745, 'frFR', 'En face, un golem au charisme magnétique. Gare à vous, cette brute va vous clanker la face !', '', 26124),
(132746, 'frFR', '', 'En face, un golem au charisme magnétique. Gare à vous, cette brute va vous clanker la face !', 26124),
(132747, 'frFR', 'La voie est libre. Feu !', '', 26124),
(132748, 'frFR', 'Par la Lumière, soyez purifiés !', '', 26124),
(132749, 'frFR', 'Contemplez la puissance du Vindicaar !', '', 26124),
(132750, 'frFR', 'Les dévastateurs de la Légion pilonnent nos troupes. Détruisez leurs barrières de protection qu’ils découvrent la vraie puissance du Vindicaar !', '', 26124),
(132751, 'frFR', 'Excellent travail. Le Vindicaar est sauvé, une fois de plus.', '', 26124),
(132793, 'frFR', 'Dès qu’il ne pourra plus tirer, l’antéen se retournera sûrement contre nous.', '', 26124),
(132798, 'frFR', 'Préparez-vous. Il se réveille !', '', 26124),
(132799, 'frFR', 'Nous ne supporterons pas une attaque de plus de ces créatures. Il faut en finir maintenant.', '', 26124),
(132800, 'frFR', 'Je vais le surcharger d’énergie avant qu’il puisse tirer. Laissez-moi juste quelques instants.', '', 26124),
(132801, 'frFR', 'Ça… marche !', '', 26124),
(132802, 'frFR', '', 'Je défendrai Argus jusqu’à mon dernier souffle !', 26124),
(132803, 'frFR', '', 'Les armées d’un millier de mondes se dresseront devant vous. Vous êtes condamnés !', 26124),
(132804, 'frFR', '', 'Vous me prenez pour une idiote ? Démons, avec moi !', 26124),
(132805, 'frFR', '', 'Je renaîtrai dans les flammes d’Argus ! Je n’arrêterai… jamais… de me battre.', 26124),
(132806, 'frFR', 'L’odeur de ces céréales ne vous semble-t-elle pas bizarre ?', 'L’odeur de ces céréales ne vous semble-t-elle pas bizarre ?', 26124),
(132807, 'frFR', 'Un peu, oui. Mais ce n’est pas mon problème.', 'Un peu, oui. Mais ce n’est pas mon problème.', 26124),
(132808, 'frFR', 'Tout doux, Poivre-et-sel. Qu’est-ce qui te prend ?', 'Tout doux, Poivre-et-sel. Qu’est-ce qui te prend ?', 26124),
(132809, 'frFR', '$n cherche un adversaire !', '$n cherche un adversaire !', 26124),
(132810, 'frFR', 'Ça en fait, des céréales, dites donc ! Les fermiers se sont vraiment surpassés cette semaine.', 'Ça en fait, des céréales, dites donc ! Les fermiers se sont vraiment surpassés cette semaine.', 26124),
(132811, 'frFR', 'On ferait bien de distribuer tout ça aux autres habitants. Les gens ont besoin de manger.', 'On ferait bien de distribuer tout ça aux autres habitants. Les gens ont besoin de manger.', 26124),
(132812, 'frFR', '', 'Mais qu’est-ce que c’était que ça ?', 26124),
(132813, 'frFR', '$n remporte le combat !', '$n remporte le combat !', 26124),
(132814, 'frFR', '', 'Les troupes de la Légion veulent s’emparer de mon essence pour leur maître !', 26124),
(132815, 'frFR', '', 'Vainquez-les avant qu’ils ne me trouvent, ou tout serait perdu.', 26124),
(132816, 'frFR', '', 'Ma résistance diminue. Si Sargeras devait l’emporter, les ténèbres engloutiraient toute vie.', 26124),
(132817, 'frFR', '', 'Mes dernières forces… disparaissent. Je ne pourrai pas… les arrêter…', 26124),
(132818, 'frFR', '', 'C’en est fini. Ma vie… liée à jamais… à Sargeras…', 26124),
(132822, 'frFR', '|TINTERFACE\\ICONS\\WARLOCK_CURSE_SHADOW_AURA.BLP:20|t Zedaat Lame du Vide commence à lancer |cFFFF0404|Hspell:246340|h[Éruption du Néant]|h|r ! Fuyez !', '|TINTERFACE\\ICONS\\WARLOCK_CURSE_SHADOW_AURA.BLP:20|t Zedaat Lame du Vide commence à lancer |cFFFF0404|Hspell:246340|h[Éruption du Néant]|h|r ! Fuyez !', 26124),
(132828, 'frFR', 'Utilisez cette clé pour traverser l’hôtel de ville. De là, vous pourrez rejoindre les rues secondaires de Stratholme.', '', 26124),
(132829, 'frFR', '|TINTERFACE\\ICONS\\INV_KNIFE_1H_FIRELANDSRAID_D_01.BLP:20|t Aggramar commence à exécuter une |cFFFF0404|Hspell:244688|h[Technique de Taeshalach]|h|r !', '|TINTERFACE\\ICONS\\INV_KNIFE_1H_FIRELANDSRAID_D_01.BLP:20|t Aggramar commence à exécuter une |cFFFF0404|Hspell:244688|h[Technique de Taeshalach]|h|r !', 26124),
(132850, 'frFR', 'Le volcan d’Argus est entré en éruption.', '', 26124),
(132851, 'frFR', 'Le pouvoir du sceau de la Gardienne se dissipe.', 'Le pouvoir du sceau de la Gardienne se dissipe.', 26124),
(132852, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_PAINSPIKE:20|tA’nutsu commence à lancer |cFFFF0404|Hspell:245164|h[Fragment de désespoir]|h|r !', '', 26124),
(132853, 'frFR', '|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t Zuraal le Zélateur est fixé sur vous !', '', 26124),
(132854, 'frFR', '|TInterface\\Icons\\spell_shadow_painspike:20|tVous subissez l’effet d’|cFFFF0000|Hspell:233983|h[Angoisse retentissante]|h|r !', '|TInterface\\Icons\\spell_shadow_painspike:20|tVous subissez l’effet d’|cFFFF0000|Hspell:233983|h[Angoisse retentissante]|h|r !', 26124),
(132855, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_ELEMENTALDEVASTATION:20|tArmageddon a percuté la plateforme, entraînant une |cFFFF0000|Hspell:240908|h[Déflagration d’armageddon]|h|r !', '|TInterface\\Icons\\SPELL_FIRE_ELEMENTALDEVASTATION:20|tArmageddon a percuté la plateforme, entraînant une |cFFFF0000|Hspell:|h[Déflagration d’armageddon]|h|r !', 26124),
(132856, 'frFR', '', 'Je sais qui vous allez affronter.$b$bArchimonde leur a octroyé à chacun un titre attestant de leurs vastes connaissances dans leurs domaines respectifs.$b$bMalheureusement, ils se sont tous ralliés à la Légion. Ceci est l’une des rares occasions de les voir tels qu’ils étaient autrefois.', 26124),
(132857, 'frFR', 'Parlez-moi du grand vizir Jarasum.', 'Parlez-moi du grand vizir Jarasum.', 26124),
(132858, 'frFR', 'Parlez-moi du grand Éveilleur Aargon.', 'Parlez-moi du grand Éveilleur Aargon.', 26124),
(132859, 'frFR', 'Parlez-moi de la grande consule Vélara.', 'Parlez-moi de la grande consule Vélara.', 26124),
(132860, 'frFR', '', 'Ah, le grand vizir.

En tant que bras droit de la grande consule, il supervisait le bon fonctionnement du conservatorium au quotidien.

Lorsqu’il fallait imposer la discipline, c’était souvent lui qui donnait de la voix. Il n’était guère apprécié, mais on ne lui manquait jamais de respect.

Je crois savoir qu’il a adopté le nom de Jaraxxus lorsqu’il s’est approprié la magie gangrenée de la Légion.

Au-delà de ça, j’ignore ce qu’il est devenu.', 26124),
(132861, 'frFR', 'Parlez-moi des autres.', 'Parlez-moi des autres.', 26124),
(132862, 'frFR', '', 'La grande consule Vélara n’obéissait qu’à Archimonde en personne.

Je me souviens d’elle comme d’une femme appliquée et discrète. Parallèlement à la guilde des Éveilleurs, elle a guidé le consulat dans sa quête des pouvoirs de la création.

Sous sa tutelle, nous avons approfondi notre capacité à invoquer les créatures des Arcanes. Les familiers qui rôdent par ici portent encore les marques de ses expériences. Elle est également en grande partie responsable du perfectionnement de la technologie des boucliers que nous utilisons aujourd’hui encore.

Par la suite, lorsqu’elle a rejoint la Légion, elle a adopté le nom de Velysra et est devenue grande maga.

Je vous souhaite de ne jamais avoir à la croiser, $n.', 26124),
(132863, 'frFR', '', 'Le grand Éveilleur Aargon. Par où commencer ?

Il a accédé à ce poste lorsque son prédécesseur, Thal’kiel, a été banni. C’est une longue histoire que je vous raconterai une prochaine fois, si vous ne la connaissez pas.

Inutile de préciser qu’il a toujours été du genre… opportuniste.

Sous sa tutelle, nous avons exploré les secrets du lien de l’âme. C’est à lui que nous devons les assemblages qui hantent ces rues. Et encore, ils ne représentent qu’une infime partie de ce dont les Éveilleurs étaient capables autrefois.

Sous le règne de la Légion, il a pris le nom d’Aargoss.

Quant à l’armée de la Lumière, elle l’appelait le Tranchâmes. Où que sévissent les moteurs d’âmes, Aargoss n’était jamais bien loin.', 26124),
(132864, 'frFR', 'Parlez, $gétranger:étrangère;.', '', 26124),
(132865, 'frFR', 'Je vous défie en duel.', 'Je vous défie en duel.', 26124),
(132866, 'frFR', 'Inclinez-vous lorsque vous vous adressez au grand Éveilleur.', '', 26124),
(132867, 'frFR', '', '<Vélara vous toise d’un air impassible.>

Oui ?', 26124),
(132868, 'frFR', 'Vous affrontez Jarasum, grand vizir du Conservatorium.', '', 26124),
(132869, 'frFR', '', 'Je ne vais pas retenir mes coups. Commençons.', 26124),
(132870, 'frFR', 'C’est perdu d’avance pour vous, mais je veux bien me prêter au jeu.', '', 26124),
(132871, 'frFR', 'Je suppose qu’on peut appeler ça une victoire.', '', 26124),
(132872, 'frFR', 'Hmpf. C’est donc terminé.', '', 26124),
(132873, 'frFR', '', 'Assez. Vous avez prouvé votre valeur.', 26124),
(132874, 'frFR', 'Munis du Cœur de la Lumière, nous allons pouvoir rendre sa gloire d’antan à Xe’ra.$b$bPlus vite ce sera fait, plus vite nous gagnerons en force pour affronter à la Légion.', '', 26124),
(132875, 'frFR', 'Commençons, Turalyon.', 'Commençons, Turalyon.', 26124),
(132892, 'frFR', 'La Légion a constitué des réserves de munitions qu’elle utilise contre nous. Réduisez ses effectifs et marquez ces réserves comme cibles pour les canons du Vindicaar. Ensuite… éloignez-vous vite !', '', 26124),
(132894, 'frFR', 'ph', '', 26124),
(132895, 'frFR', 'Les canons de la Légion se sont tus, grâce à vous.', '', 26124),
(132899, 'frFR', '', 'Suivez-moi !', 26124),
(132900, 'frFR', '', 'Neutralisez les entrées des renforts !', 26124),
(132901, 'frFR', '|TInterface\\ICONS\\ABILITY_MAGE_FIRESTARTER.BLP:20|t Vous êtes la cible de |cFFF00000|Hspell:244410|h[Décimation]|h|r !', '', 26124),
(132925, 'frFR', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t Un croiseur de la Légion se prépare à lancer une |cFFFF0000|Hspell:244627|h[Fusillade]|h|r !', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t Un croiseur de la Légion se prépare à lancer une |cFFFF0000|Hspell:244627|h[Fusillade]|h|r !', 26124),
(132929, 'frFR', 'Êtes-vous $gprêt:prête; à commencer l’épreuve de ténacité ?', '', 26124),
(132934, 'frFR', 'Je suis prêt.', 'Je suis prête.', 26124),
(132936, 'frFR', 'Ce défi est très simple. Entrez et avancez jusqu’à atteindre l’autre côté de la structure.', '', 26124),
(132946, 'frFR', 'Désolé, je n’ai pas tout suivi. Pourriez-vous répéter ce que vous venez de dire ?', 'Désolée, je n’ai pas tout suivi. Pourriez-vous répéter ce que vous venez de dire ?', 26124),
(132950, 'frFR', 'Tout est conçu pour vous tuer. Bonne chance.', '', 26124),
(132951, 'frFR', 'Je suis un peu perdu. Qu’est-ce que vous avez dit juste avant ?', 'Je suis un peu perdue. Qu’est-ce que vous avez dit juste avant ?', 26124),
(132953, 'frFR', 'Essayez de ne pas vous faire toucher par les rayons. J’imagine que c’est très douloureux.', '', 26124),
(132958, 'frFR', 'Je vous entends…', '', 26124),
(132959, 'frFR', 'Ah, vous voilà…', '', 26124),
(132960, 'frFR', 'Continuez à détourner l’attention des gardiens du sanctuaire Rubis. Je mènerai l’attaque de notre maître depuis le grand arbre lui-même.', '', 26124),
(132962, 'frFR', 'Attention aux escaliers.', '', 26124),
(132970, 'frFR', 'Si cela peut satisfaire votre curiosité, sachez que j’étais autrefois le gardien des clés du conservatorium, le responsable de tous ses verrous et portes.$b$bPour échapper aux ravages du temps, j’ai placé mon âme dans cet assemblage. Depuis, je veille de toute éternité sur les lieux.$b$bJe dois donc éternellement endurer les visites de lourdauds comme vous.', '', 26124),
(132971, 'frFR', 'J’en conviens, vous êtes soit très rapide, soit particulièrement opiniâtre. Mais est-ce suffisant pour prouver votre ténacité ?$b$b<Quoram émet un son semblable à un bourdonnement.>', '', 26124),
(132972, 'frFR', 'Je vous en prie.', 'Je vous en prie.', 26124),
(132973, 'frFR', 'Bien. Le défi est terminé. Mais uniquement parce que je n’ai plus d’endroit où vous mettre à l’épreuve.', '', 26124),
(132995, 'frFR', 'Imbéciles ! Nous allons vous balayer. Nous ne laisserons rien ni personne compromettre notre mission !', '', 26124),
(132996, 'frFR', 'Nous ne céderons pas ! Faites venir davantage de renforts depuis le Vide, qu’ils se chargent de ces intrus !', '', 26124),
(132997, 'frFR', 'Nous sommes débordés ! Rendez-vous utiles et faites cesser cette incursion !', '', 26124),
(132998, 'frFR', 'Il semble que cette intrusion nécessite un traitement plus personnalisé. Je vais m’occuper de vous moi-même !', '', 26124),
(133000, 'frFR', 'Votre aide est la bienvenue, Fareeya.', '', 26124),
(133010, 'frFR', 'Oui, maître. Il en sera fait ainsi au moment exact que vous avez choisi. Le dragon de bronze ne s’apercevra de rien. Il me suffira d’un seul tir depuis l’extérieur du sanctuaire draconique Obsidien.', '', 26124),
(133015, 'frFR', 'Oh, vous avez réussi. Merveilleux.', '', 26124),
(133016, 'frFR', 'Je présume que vous comptez sur moi pour vous renvoyer à l’entrée du conservatorium.', '', 26124),
(133017, 'frFR', 'L’épreuve est-elle terminée ?', 'L’épreuve est-elle terminée ?', 26124),
(133018, 'frFR', 'Votre intervention ne nous ralentira pas. Tous finiront par servir le Vide ou par y succomber.', '', 26124),
(133019, 'frFR', 'Vous allez pouvoir admirer par vous-mêmes les fruits de notre labeur. Place à Zuraal le Zélateur ! Le tout premier à s’être abandonné pleinement au Vide !', '', 26124),
(133020, 'frFR', '', 'Vous l’avez trouvé ! Tant de puissance… Je peux le sentir d’ici.', 26124),
(133021, 'frFR', '', 'Apportez-le-moi. Vite. Nous avons établi un périmètre de sécurité.', 26124),
(133022, 'frFR', 'Les nécrosombres… J’aurais juré que ces maudits sectateurs avaient été éradiqués il y a bien longtemps.

Quoi qu’il en soit, il n’est jamais trop tard pour finir le travail. Je peux vous conduire au caveau de Neltharion.', '', 26124),
(133027, 'frFR', 'Chromie est morte.', 'Chromie est morte.', 26124),
(133028, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue dans les ruines Délabrées !', '', 26124),
(133029, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue au portail du Néant inférieur !', '', 26124),
(133030, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue à la brèche du Vide supérieure !', '', 26124),
(133031, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue à la brèche du Vide inférieure !', '', 26124),
(133032, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue au surplomb Dévasté !', '', 26124),
(133033, 'frFR', '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|tUne déchirure du Vide est apparue dans la Fondation du temple !', '', 26124),
(133034, 'frFR', 'Chaque seconde compte. La Légion ne doit pas capturer le prophète.', '', 26124),
(133035, 'frFR', 'Il est peut-être déjà trop tard ! Ceci n’augure rien de bon. J’entends le chant rituel non loin.', '', 26124),
(133049, 'frFR', 'Dites-moi tout ce que vous savez à propos de la pierre.', 'Dites-moi tout ce que vous savez à propos de la pierre.', 26124),
(133050, 'frFR', 'Notre peuple sert à alimenter de vils rituels. Détruisez ces monstrueuses créations et aidez-nous à honorer la mémoire de nos morts.', '', 26124),
(133051, 'frFR', 'Ces démons capturent mon peuple pour le soumettre à d’effroyables rituels. Nous refusons de nous laisser traquer. Aidez-nous à combattre la Légion !', '', 26124),
(133052, 'frFR', 'À mesure que la Légion empiète sur le terrain de chasse des pantharas, les bêtes affamées gagnent en agressivité. Réduisez leur population avant qu’elles éradiquent nos troupeaux de talbuks.', '', 26124),
(133056, 'frFR', 'La console affiche le chiffre 2.', '', 26124),
(133057, 'frFR', 'La console affiche le chiffre 3.', '', 26124),
(133058, 'frFR', 'La console affiche le chiffre 4.', '', 26124),
(133059, 'frFR', 'La console affiche le chiffre 5.', '', 26124),
(133060, 'frFR', 'La console affiche le chiffre 6.', '', 26124),
(133061, 'frFR', 'La console affiche le chiffre 7.', '', 26124),
(133062, 'frFR', 'La console affiche le chiffre 8.', '', 26124),
(133063, 'frFR', 'La console affiche le chiffre 9.', '', 26124),
(133067, 'frFR', '<Relever le levier.>', '<Relever le levier.>', 26124),
(133068, 'frFR', '<Abaisser le levier.>', '<Abaisser le levier.>', 26124),
(133072, 'frFR', 'Ne vous inquiétez pas pour l’attaque du sanctuaire draconique Azur. Je me charge de régler son compte au vide gargantuesque.', '', 26124),
(133073, 'frFR', 'Ne vous inquiétez pas pour l’attaque du sanctuaire draconique Obsidien. Je me charge de régler son compte au seigneur de l’effroi.', '', 26124),
(133074, 'frFR', 'Ne vous inquiétez pas pour l’attaque du sanctuaire draconique Émeraude. Je me charge de régler son compte au Satyre.', '', 26124),
(133075, 'frFR', 'Ne vous inquiétez pas pour l’attaque du sanctuaire draconique Rubis. Je me charge de régler son compte à la liche.', '', 26124),
(133076, 'frFR', 'Je vois que vous vous êtes déjà $goccupé:occupée; des sanctuaires draconiques. Voilà pour vous, avec la bénédiction du Vol draconique de bronze.', '', 26124),
(133077, 'frFR', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|tS’approcher trop près de |cFFFF0000|Hspell:234621|h[Gueule vorace]|h|r déclenche |cFFFF0000|Hspell:232885|h[Dévorer tout entier]|h|r !', '', 26124),
(133078, 'frFR', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée principale.', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée principale.', 26124),
(133079, 'frFR', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée inférieure.', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée inférieure.', 26124),
(133080, 'frFR', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée du grand temple.', 'Un transport de troupes de la Légion se matérialise au-dessus de l’entrée du grand temple.', 26124),
(133081, 'frFR', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée principale.', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée principale.', 26124),
(133082, 'frFR', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée inférieure.', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée inférieure.', 26124),
(133083, 'frFR', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée du grand temple.', 'Un croiseur de la Légion se matérialise au-dessus de l’entrée du grand temple.', 26124),
(133086, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t', 26124),
(133087, 'frFR', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t', 26124),
(133088, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t', 26124),
(133089, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 26124),
(133090, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 26124),
(133091, 'frFR', '|TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 26124),
(133092, 'frFR', '|TInterface\\Icons\\INV_FelbatMount.blp:24|t', '|TInterface\\Icons\\INV_FelbatMount.blp:24|t', 26124),
(133093, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 26124),
(133095, 'frFR', 'Revivre les derniers instants de lucidité de ces vies troublées n’a rien de réjouissant. Mais c’est le seul moyen de leur rendre honneur. Merci de votre aide.', '', 26124),
(133096, 'frFR', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée principale.', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée principale.', 26124),
(133097, 'frFR', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée inférieure.', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée inférieure.', 26124),
(133098, 'frFR', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée du grand temple.', 'Un transport de troupes et un croiseur de la Légion se matérialisent au-dessus de l’entrée du grand temple.', 26124),
(133105, 'frFR', 'Je suis prêt. Allons vous sauver la vie !
|cFF0000FF(Lancer le scénario).|r', 'Je suis prête à partir. Allons vous sauver la vie !
|cFF0000FF(Lancer le scénario).|r', 26124),
(133106, 'frFR', 'Un démon ose mener une attaque contre le Vindicaar. Une mort rapide exposera à tous la folie de son maître.', '', 26124),
(133107, 'frFR', 'La Légion ne reculera devant rien pour détruire notre monde. mais elle ferait bien de se souvenir de cette défaite.', '', 26124),
(133109, 'frFR', 'La vierge funeste man’ari Talestra cherche à créer une armée de démons. Veillez à contrecarrer ses plans.', '', 26124),
(133110, 'frFR', 'Je rêverais de voir le sort qui lui sera réservé lorsqu’elle regagnera Antorus. Sargeras n’est pas du genre à prendre l’échec à la légère.', '', 26124),
(133116, 'frFR', '', 'Le Cercle cénarien ne restera pas sans rien faire quand les soldats de l’Alliance et de la Horde s’entretuent. Si je peux apporter un peu de réconfort à des soldats blessés, c’est suffisant pour moi.', 26124),
(133117, 'frFR', '<Vous tendez les documents du Cercle cénarien.>', '<Vous tendez les documents du Cercle cénarien.>', 26124),
(133118, 'frFR', '', 'Il… Il est dit ici que vous venez sur l’ordre du gardien Remulos en personne ! Très bien, quels sont vos ordres, $n ?', 26124),
(133119, 'frFR', 'Il faut que les druides détournent l’attention des canons à l’extérieur afin qu’un dragon de bronze puisse quitter Andorhal.', 'Il faut que les druides détournent l’attention des canons à l’extérieur afin qu’un dragon de bronze puisse quitter Andorhal.', 26124),
(133121, 'frFR', '', 'Chromie a besoin de notre aide ? Nous sommes là. Nous allons détourner l’attention des canons afin qu’elle puisse s’envoler en toute sécurité.', 26124),
(133135, 'frFR', 'Insertion de larve d’esprit', 'Insertion de larve d’esprit', 26124),
(133145, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 26124),
(133146, 'frFR', '|TInterface\\ICONS\\ABILITY_WARLOCK_BACKDRAFTGREEN.BLP:20|t Placez-vous dans les zones d’impact d’|cFFF00000|Hspell:244761|h[Annihilation]|h|r pour éviter les dégâts de raid !', '', 26124),
(133160, 'frFR', '', 'La Légion anéantira tous ceux qui s’opposent à nous !', 26124),
(133162, 'frFR', '', 'Est-ce le mieux que vous puissiez faire ? Hah. Pathétique.', 26124),
(133163, 'frFR', '', 'J’ai considérablement ralenti le temps afin que nous puissions nous préparer sans perdre un instant.$b$bPrévenez-moi que vous voudrez y aller !', 26124),
(133164, 'frFR', '', 'Votre combat s’arrête ici.', 26124),
(133165, 'frFR', '', 'Contemplez le destin de ceux qui s’opposent à nous.', 26124),
(133166, 'frFR', '', 'Tous les mondes sur notre route sont tombés. Le vôtre est le prochain.', 26124),
(133167, 'frFR', '', 'Contemplez la puissance capable de détruire des mondes !', 26124),
(133168, 'frFR', '', 'Abattez-les !', 26124),
(133169, 'frFR', '', 'Ne laissez aucun survivant !', 26124),
(133170, 'frFR', '', 'Déchirez leur chair !', 26124),
(133171, 'frFR', '', 'Admirez Xoroth, un monde à la chaleur infernale rempli d’os calcinés !', 26124),
(133172, 'frFR', '', 'Contemplez Rancora, avec ses bassins purulents et sa mort grouillante !', 26124),
(133173, 'frFR', '', 'Nathreza… Ce monde autrefois source de magie et de connaissances n’est plus qu’une terre corrompue à laquelle nul n’échappe.', 26124),
(133174, 'frFR', '', 'Les portails… doivent… tenir…', 26124),
(133175, 'frFR', '', 'Ce… n’est… pas possible…', 26124),
(133176, 'frFR', '', 'Votre monde tombera…', 26124),
(133177, 'frFR', '', 'Que cela vous serve de leçon !', 26124),
(133178, 'frFR', '', 'Plus d’os pour ma pile.', 26124),
(133179, 'frFR', '', 'Si facilement brisés.', 26124),
(133180, 'frFR', '', 'C’était vraiment ce qu’Azeroth a de mieux à offrir ?', 26124),
(133181, 'frFR', '', 'Azeroth tombera, tout comme vous êtes tombés.', 26124),
(133182, 'frFR', '', 'La Légion a dévasté des milliers de mondes. Le vôtre n’y échappera pas.', 26124),
(133183, 'frFR', '', 'Votre résistance touche à sa fin !', 26124),
(133184, 'frFR', '', 'Je commande les troupes de la Légion à travers tout le cosmos !', 26124),
(133185, 'frFR', '', 'Nos troupes sont infinies !', 26124),
(133186, 'frFR', '', 'Le courroux de la Légion va vous submerger !', 26124),
(133187, 'frFR', '<Une fissure dans le sol, à peine assez large pour s’y glisser. Il fait trop sombre pour y voir quoi que ce soit, mais elle est manifestement très profonde.>', '', 26124),
(133188, 'frFR', '<Se glisser dans la fissure.>', '<Se glisser dans la fissure.>', 26124),
(133189, 'frFR', 'AVERTISSEMENT : vous êtes sur le point de tomber dans une fissure sombre. Vous ne pourrez peut-être pas en ressortir par le même chemin. Voulez-vous continuer ?', '', 26124),
(133190, 'frFR', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\spell_shadow_summonfelhunter.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 26124),
(133191, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 26124),
(133192, 'frFR', '', 'Malgré nos efforts, le Vide continue de s’infiltrer par les fissures. Trouvez l’armée de la Lumière et tirez parti de sa bénédiction pour repousser les ténèbres une fois encore.', 26124),
(133193, 'frFR', '', 'Peut-être n’arriverons-nous pas à leur rendre leur santé mentale, mais au moins nous en empêcherons d’autres de succomber.', 26124);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133194, 'frFR', '', '<Enaara vous remet un cristal serti dans une monture d’or.>$b$bBannissez les ténèbres, $n, et que triomphe la Lumière !', 26124),
(133195, 'frFR', '<Accepter le cristal.>', '<Accepter le cristal.>', 26124),
(133196, 'frFR', '', 'Cet endroit est maudit. Offrons un peu de Lumière à ces âmes en peine.', 26124),
(133202, 'frFR', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t Une braise de Taeshalach entre en surcharge et provoque une |cFFFF0404|Hspell:244912|h[Éruption flamboyante]|h|r !', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t Une braise de Taeshalach entre en surcharge et provoque une |cFFFF0404|Hspell:244912|h[Éruption flamboyante]|h|r !', 26124),
(133203, 'frFR', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 26124),
(133205, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 26124),
(133206, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 26124),
(133208, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 26124),
(133209, 'frFR', 'Des gangroptères commencent à fondre sur la plateforme d’Eonar !', 'Des gangroptères commencent à fondre sur la plateforme d’Eonar !', 26124),
(133210, 'frFR', 'La faille s’effondre sur elle-même, héros ! Dépêchez-vous avant que l’entrée ne se referme à jamais !', '', 26124),
(133215, 'frFR', 'AL’KSH SYR IIR AWAN ? IILTH SYTHN AGEV.', 'AL’KSH SYR IIR AWAN ? IILTH SYTHN AGEV.', 26124),
(133216, 'frFR', '<Souvenir de l’attaque de Kil’Jaeden sur Dalaran>', '<Souvenir de l’attaque de Kil’Jaeden sur Dalaran>', 26124),
(133217, 'frFR', '<Souvenir de l’ouverture de la tombe de Sargeras>', '<Souvenir de l’ouverture de la tombe de Sargeras>', 26124),
(133218, 'frFR', '<Souvenir d’Anduin récupérant Shalamayne>', '<Souvenir d’Anduin récupérant Shalamayne>', 26124),
(133219, 'frFR', '<Souvenir de la défaite de Kil’Jaeden>', '<Souvenir de la défaite de Kil’Jaeden>', 26124),
(133220, 'frFR', '', 'Ensemble, nous veillerons à ce que la Légion disparaisse à jamais.', 26124),
(133221, 'frFR', '', 'La Légion sévit en Azeroth depuis trop longtemps. Il est temps d’y mettre un terme.', 26124),
(133222, 'frFR', 'Le prophète Velen sera ravi de voir que vous avez répondu à son appel. Les Draeneï attendent ce jour depuis longtemps.', '', 26124),
(133225, 'frFR', '', 'Impressionnant. La Légion ne s’attendra pas à une attaque de cette ampleur.', 26124),
(133226, 'frFR', 'Suintentraille manger le sale dragon !', '', 26124),
(133227, 'frFR', '', 'La mort vient pour toi, petit dragon…', 26124),
(133228, 'frFR', 'Abandonne et meurs, wyrm !', '', 26124),
(133229, 'frFR', 'Le dragon arrive ! Tuez le dragon !', '', 26124),
(133230, 'frFR', 'Étrange. Que faites-VOUS ici ?', '', 26124),
(133231, 'frFR', 'Ton heure est venue, dragonnet. Plus jamais tu ne marcheras dans le temps.', '', 26124),
(133232, 'frFR', 'Sens les doigts de la mort s’enrouler autour de ton cou écailleux, petit dragon.', '', 26124),
(133233, 'frFR', 'Tu ne manipuleras plus jamais les voies temporelles, dragon !', '', 26124),
(133234, 'frFR', 'Ouvrez les portails ! Détruisez le dragon de bronze ! Ne le laissez pas s’enfuir !', '', 26124),
(133235, 'frFR', '', 'Petite maligne. Je t’ai capturée une fois et je le referai !', 26124),
(133236, 'frFR', 'Détruisons ce dragonnet ! Au nom de l’Alliance !', 'Détruisons ce dragonnet ! Au nom de l’Alliance !', 26124),
(133237, 'frFR', 'Détruisons ce dragonnet ! Pour la Horde !', 'Détruisons ce dragonnet ! Pour la Horde !', 26124),
(133238, 'frFR', '|TInterface\\Icons\\ABILITY_ROGUE_SHADOWSTEP:20|tSaprish s’apprête à vous attaquer avec |cFFFF0000|Hspell:247246|h[Ruées ombreuses]|h|r !', '|TInterface\\Icons\\ABILITY_ROGUE_SHADOWSTEP:20|tSaprish s’apprête à vous attaquer avec |cFFFF0000|Hspell:247246|h[Ruées ombreuses]|h|r !', 26124),
(133241, 'frFR', 'Vos esprits sont si facilement obscurcis !', '', 26124),
(133242, 'frFR', 'La Lumière ne vous sauvera pas…', '', 26124),
(133243, 'frFR', '', 'Approchez-vous davantage, héros, que je puisse voir la chair se détacher de vos os !', 26124),
(133244, 'frFR', '', 'Oh, déguster… votre… chair liquéfiée…', 26124),
(133245, 'frFR', 'Vos cendres seront dispersées dans tout le cosmos !', '', 26124),
(133246, 'frFR', 'Mes braises ne s’éteindront jamais…', '', 26124),
(133255, 'frFR', 'Si jamais nous ne revenons pas, c’est Lothraxion qui prendra le commandement. Restez sur vos gardes, Fareeya.', '', 26124),
(133256, 'frFR', '', 'Nous avons déjà connu pire. Je défendrai la position.', 26124),
(133257, 'frFR', 'Nous ferons de notre mieux.', '', 26124),
(133268, 'frFR', 'La Légion a ouvert des portails pour envahir l’Arcatraz. Refermez-les… avant de vous laisser déborder.', '', 26124),
(133280, 'frFR', 'Imprégnation', 'Imprégnation', 26124),
(133285, 'frFR', 'Les runes gravées sur cette urne indiquent qu’elle contient une partie de la dépouille d’un puissant lieur d’esprit mogu. La plupart des inscriptions sont en réalité des mises en garde.', '', 26124),
(133286, 'frFR', '<Consommer les cendres.>', '<Consommer les cendres.>', 26124),
(133287, 'frFR', 'AVERTISSEMENT : vous êtes sur le point de consommer les cendres d’un ensorceleur maléfique. Les conséquences d’un tel acte sont imprévisibles. Voulez-vous VRAIMENT continuer ?', '', 26124),
(133288, 'frFR', '', 'Vous avez fait de l’exercice, j’espère ? Le Grand Prix de Gnomeregan va bientôt commencer !', 26124),
(133289, 'frFR', '', 'N’oubliez pas de vous hydrater et de vous reposer pour le Grand Prix de Gnomeregan ! Il commencera très bientôt à la Nouvelle-Brikabrok !', 26124),
(133290, 'frFR', '', 'Le Grand Prix de Gnomeregan a lieu en ce moment même à la Nouvelle-Brikabrok ! Vous pensez que vous pourrez battre votre record personnel ?!', 26124),
(133291, 'frFR', '', 'Le Grand Prix de Gnomeregan a lieu en ce moment même à la Nouvelle-Brikabrok !', 26124),
(133292, 'frFR', '', 'L’Alliance est en train de célébrer le Grand Prix de Gnomeregan à la Nouvelle-Brikabrok !', 26124),
(133293, 'frFR', '', 'Le Grand Prix de Gnomeregan de l’Alliance se tiendra à la Nouvelle-Brikabrok très bientôt !', 26124),
(133296, 'frFR', 'J’ai perdu l’antidote. Vous l’avez récupéré ?', 'J’ai perdu l’antidote. Vous l’avez récupéré ?', 26124),
(133299, 'frFR', 'L’ennemi cherche à refermer notre faille ! Aux armes !', 'L’ennemi cherche à refermer notre faille ! Aux armes !', 26124),
(133307, 'frFR', 'Je suis rétabli.', '', 26124),
(133308, 'frFR', '', 'Oh non… je connais cette voix.', 26124),
(133309, 'frFR', 'Exilée Y’mera. Pourquoi êtes-vous revenue ?', '', 26124),
(133313, 'frFR', 'Commençons.', '', 26124),
(133320, 'frFR', '', 'Nous devons…', 26124),
(133322, 'frFR', 'Expliquez votre présence ou quittez ces lieux immédiatement.', '', 26124),
(133323, 'frFR', 'Je cherche le cachet de l’Éveil.', 'Je cherche le cachet de l’Éveil.', 26124),
(133324, 'frFR', 'Mes robots et moi, on va nettoyer Gnomeregan, ça oui !

Enfin, la technologie n’est pas tout à fait au point. J’arrive à leur faire absorber les vapeurs toxiques, mais ils en rejettent encore plus.

Et ensuite, tout devient vert et brumeux. C’est plutôt joli, je dois dire, et ça m’aide à me concentrer sur mon boulot.

Bref, qu’est-ce que je peux faire pour vous aujourd’hui, $gami:amie; trogg ?

<Bert incline la tête en fixant du regard l’espace vide, juste à votre gauche.>', '', 26124),
(133326, 'frFR', 'Justice environnementale !', '', 26124),
(133327, 'frFR', 'Le robot de Bert bat les brutes !', '', 26124),
(133328, 'frFR', 'Il manque un point-virgule dans le code !', '', 26124),
(133330, 'frFR', 'Robots de Bert battus !', '', 26124),
(133331, 'frFR', 'Alimentation principale activée !', '', 26124),
(133332, 'frFR', 'Vérification du code réussie !', '', 26124),
(133334, 'frFR', '', 'Je sens le pouvoir crépiter dans l’air. Il est toujours palpable après tout ce temps.', 26124),
(133335, 'frFR', '', 'Bien. Mettons-nous en route alors.', 26124),
(133347, 'frFR', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t Maîtresse Alluradel commence à lancer |cFFFF0404|Hspell:247551|h[Charme captivant]|h|r. Détournez vite le regard !', '|TINTERFACE\\ICONS\\SPELL_FIRE_LAVASPAWN.BLP:20|t Maîtresse Alluradel commence à lancer |cFFFF0404|Hspell:247551|h[Charme captivant]|h|r. Détournez vite le regard !', 26124),
(133352, 'frFR', 'Je crains de ne pas pouvoir l’autoriser, $n.', '', 26124),
(133358, 'frFR', 'Lah’zaruun, ma loyale servante. Reste ici et tue ces imbéciles. J’ai à faire.', '', 26124),
(133362, 'frFR', '', 'Je ne peux pas entrer dans le Prétoire. Mais vous le saviez déjà, n’est-ce pas ?', 26124),
(133363, 'frFR', 'Possible.', '', 26124),
(133366, 'frFR', '', 'J’ai foi en vous, $n. Je ne serai pas loin quand vous en aurez fini.', 26124),
(133367, 'frFR', '', 'Cet assemblage devrait détenir des informations pouvant nous aider à localiser le cachet de l’Éveil. Nous devons l’activer.', 26124),
(133373, 'frFR', 'Je dois avouer que ces épreuves m’amusent follement… Ce n’est que moi ?', '', 26124),
(133375, 'frFR', 'Tant se dressent devant moi et tant échouent.', '', 26124),
(133376, 'frFR', 'Vous vous croyez suffisamment intelligents pour être arrivés jusqu’ici, mais la fin est déjà écrite.', '', 26124),
(133377, 'frFR', 'Votre ténacité n’est rien face à ma volonté. Je vous briserai.', '', 26124),
(133378, 'frFR', 'Ha ! Un hommage digne de mes enseignements au Conservatorium.', '', 26124),
(133381, 'frFR', '', 'Champions ! Par ici !', 26124),
(133382, 'frFR', 'Encore un monde profané par la Légion. Détruisez ses armées et condamnez cette faille avant que les démons ne débarquent sur Argus !', '', 26124),
(133383, 'frFR', 'Chaque faille refermée nous fait gagner un peu de temps pour progresser. La Lumière vous accompagne, $gchampion:championne;.', '', 26124),
(133384, 'frFR', 'La flotte de la Légion être en train de se rassembler. Perturbez ses préparatifs et condamnez la faille avant qu’elle n’atteigne Argus !', '', 26124),
(133385, 'frFR', 'L’afflux de renforts en provenance de ce monde a été endigué… Du moins, pour l’instant.', '', 26124),
(133386, 'frFR', 'Mortels, j’ai galvaudé des millénaires à me battre pour vous éviter la corruption. Jusqu’à ce qu’enfin, la vérité s’offre à mes yeux.', '', 26124),
(133388, 'frFR', 'La cruauté de la Légion n’épargne personne, pas même les siens. Détruisez cette abomination et condamnez la faille qui relie nos mondes.', '', 26124),
(133390, 'frFR', 'Toutes les failles ont été condamnées, mais elles finiront par se rouvrir tôt ou tard !', '', 26124),
(133391, 'frFR', 'La corruption, c’est vous. Nous sauverons l’univers en effaçant toute trace de votre existence.', '', 26124),
(133394, 'frFR', 'Vous allez brûler !', '', 26124),
(133397, 'frFR', 'Vous obtiendrez cet objet dans une prochaine série de quêtes. Pour l’instant, il suffit de vous pencher pour le ramasser !', '', 26124),
(133398, 'frFR', 'Ramasser une pierre de faille déchargée.', 'Ramasser une pierre de faille déchargée.', 26124),
(133399, 'frFR', '|TINTERFACE\\ICONS\\INV_STONE_05.BLP:20|t Votre pierre de faille déchargée est désormais une |cFFFF0000|Hitem:151702|h[pierre de faille chargée]|h|r !', '|TINTERFACE\\ICONS\\INV_STONE_05.BLP:20|t Votre pierre de faille déchargée est désormais une |cFFFF0000|Hitem:151702|h[pierre de faille chargée]|h|r !', 26124),
(133408, 'frFR', 'Meurs, fragile créature !', '', 26124),
(133414, 'frFR', 'Si pitoyable.', '', 26124),
(133416, 'frFR', 'Vous n’aviez aucune chance. Rien ne peut arrêter notre croisade !', '', 26124),
(133417, 'frFR', 'Il est peut-être trop tard pour l’arrêter…', '', 26124),
(133418, 'frFR', 'Nul ne peut s’opposer à Taeshalach !', '', 26124),
(133419, 'frFR', 'Brûlez !', '', 26124),
(133420, 'frFR', '', 'J’espérais que ça fonctionnerait. Les lumières sont allumées, mais personne ne répond.', 26124),
(133422, 'frFR', 'Que les flammes vous engloutissent !', '', 26124),
(133424, 'frFR', 'Vous mourrez tous sur mon passage !', '', 26124),
(133425, 'frFR', 'Affrontez-moi et mourez !', '', 26124),
(133426, 'frFR', 'Vous n’en réchapperez pas !', '', 26124),
(133427, 'frFR', 'Que les flammes vous dévorent !', '', 26124),
(133431, 'frFR', 'Les flammes consumeront la chair sur vos os !', '', 26124),
(133433, 'frFR', 'La puissance de Taeshalach se déchaîne !', '', 26124),
(133434, 'frFR', 'La puissance de Taeshalach vous consumera !', '', 26124),
(133435, 'frFR', 'Vous avez peut-être résisté aux flammes, mais vous ne tiendrez pas face à ma fureur.', '', 26124),
(133436, 'frFR', 'Votre peu de talent ne suffira pas pour vous sauver.', '', 26124),
(133440, 'frFR', '', 'Assez ! Votre intrusion s’achève ici, mortels !', 26124),
(133442, 'frFR', 'Le temps est écoulé.', 'Le temps est écoulé.', 26124),
(133451, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelReaver.blp:24|t', 26124),
(133452, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONFELGUARD.BLP:24|t |TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Achievement_Boss_HellFire_Socrethar.blp:24|t', 26124),
(133453, 'frFR', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\SPELL_WARLOCK_SUMMONWRATHGUARD.BLP:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 26124),
(133454, 'frFR', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', '|TInterface\\Icons\\Achievement_Boss_HellFire_FelLord.blp:24|t |TInterface\\Icons\\Ability_FelArakkoa_EyeofTerrok.blp:24|t', 26124),
(133482, 'frFR', '', '|TInterface\\Icons\\INV_MISC_AMMO_ARROW_03:20|t%s cible les ennemis avec |cFFFF0000|Hspell:230139|h[Tir de l’hydre]|h|r !', 26124),
(133483, 'frFR', 'Maintenant, nos êtres chers peuvent enfin trouver le repos.', '', 26124),
(133484, 'frFR', 'Grâce à vous, les âmes et les vies de mes semblables sont en sécurité.', '', 26124),
(133485, 'frFR', 'Ces montures nous sont essentielles pour livrer combat aux démons. Merci de les avoir protégées.', '', 26124),
(133486, 'frFR', 'Vous utilisez désormais du |TInterface\\ICONS\\Achievement_ChallengeMode_Auchindoun_Hourglass.blp:32|t [Temps volé] !', 'Vous utilisez désormais du |TInterface\\ICONS\\Achievement_ChallengeMode_Auchindoun_Hourglass.blp:32|t [Temps volé] !', 26124),
(133508, 'frFR', '', 'Je vais avoir besoin de votre aide. Bousculez-le un peu, s’il vous plaît.', 26124),
(133517, 'frFR', 'Nous ne sommes pas en sécurité ici !', '', 26124),
(133518, 'frFR', 'Les ténèbres recouvrent La Lumière de leur linceul.', '', 26124),
(133519, 'frFR', 'Merci infiniment. Je saurai trouver le chemin.', '', 26124),
(133520, 'frFR', 'Faites vite avant que les abîmes ne vous engloutissent !', '', 26124),
(133521, 'frFR', 'Nous devons partir avant qu’il ne soit trop tard !', '', 26124),
(133522, 'frFR', 'Notre combat n’est pas encore terminé !', '', 26124),
(133523, 'frFR', 'Je… je dois aller retrouver les miens immédiatement.', '', 26124),
(133524, 'frFR', 'Le Conservatorium ne met pas ses ressources à la disposition de personnes de votre… statut.', '', 26124),
(133525, 'frFR', '', 'De tous ceux qui pouvaient devenir Gardien de la porte… $n, peut-être devriez-vous mener la discussion.', 26124),
(133528, 'frFR', 'Le Cachet est le plus grand honneur du Conservatorium. Seuls les élus d’Archimonde peuvent prétendre à cette consécration.', '', 26124),
(133529, 'frFR', 'Je suis dans l’obligation de vous informer que le maître a créé des épreuves à cette fin spécifique.', '', 26124),
(133531, 'frFR', 'Je suis également contraint d’autoriser les non-initiés à participer.', '', 26124),
(133533, 'frFR', '', 'Entre Quoram et moi… c’est une longue histoire.$b$bDisons simplement que nous ne nous sommes pas quittés en très bons termes, au conservatorium.', 26124),
(133535, 'frFR', '', '<Y’mera manipule le cachet avec précaution.>$b$bTenir une telle relique dans mes mains me donne un sentiment de vulnérabilité.', 26124),
(133541, 'frFR', 'Vous, Y’mera, ne participerez pas. Mais je ne vous refuserai pas la chance de voir $n échouer.', '', 26124),
(133542, 'frFR', '', 'Comme c’est généreux de votre part.', 26124),
(133549, 'frFR', '', 'Je ne pourrai pas vous aider directement, mais je possède des informations qui pourraient vous être utiles.', 26124),
(133577, 'frFR', 'Je me présente, Al’Abas le Magnifique. Pardonnez mon humeur massacrante, mais je supporte mal ce clapier à Murlocs. Dites-moi, auriez-vous l’amabilité de prêter l’oreille à mon histoire ?', '', 26124),
(133583, 'frFR', 'Merci infiniment, $n.', '', 26124),
(133584, 'frFR', 'Puisse la Lumière nous guider !', '', 26124),
(133585, 'frFR', 'Vous avez contribué à assurer l’avenir de notre peuple.', '', 26124),
(133586, 'frFR', 'Allez en paix.', '', 26124),
(133587, 'frFR', 'Nous devons faire front commun.', '', 26124),
(133588, 'frFR', 'Acheon Kor.', '', 26124),
(133589, 'frFR', 'Golad niton acalah.', '', 26124),
(133590, 'frFR', 'Krona ki cristorr !', '', 26124),
(133592, 'frFR', '', 'Nous faisons tout notre possible pour tenir la position. Allez retrouver Y’mera et reprenez l’avantage !', 26124),
(133593, 'frFR', '', 'La Lumière triomphe toujours.', 26124),
(133594, 'frFR', '', 'Nous allons gagner cette guerre.', 26124),
(133595, 'frFR', '', 'Faites votre rapport.', 26124),
(133596, 'frFR', '', 'Salutations.', 26124),
(133597, 'frFR', '', 'Soyez sur vos gardes.', 26124),
(133598, 'frFR', '', 'Nous vaincrons la Légion.', 26124),
(133599, 'frFR', '', 'Archenon poros.', 26124),
(133600, 'frFR', '', 'Vous ! Vous n’êtes pas un démon. Venez ici et aidez-nous en en tuant quelques-uns !', 26124),
(133601, 'frFR', '', 'Avancez jusqu’aux batteries et abattez ces chauves-souris maintenant ! Nous comptons sur vous !', 26124),
(133602, 'frFR', '', 'Avec le bon état d’esprit, n’importe quel objet peut devenir une arme.', 26124),
(133603, 'frFR', '', 'Ma lame et mes sorts sont prêts à servir la Lumière.', 26124),
(133604, 'frFR', '', 'Nous libérerons notre foyer.', 26124),
(133611, 'frFR', 'Que faites-vous ici ?', 'Que faites-vous ici ?', 26124),
(133612, 'frFR', 'Vous n’avez rien à faire ici !', 'Vous n’avez rien à faire ici !', 26124),
(133613, 'frFR', 'Vous ne savez rien de ma souffrance !', 'Vous ne savez rien de ma souffrance !', 26124),
(133614, 'frFR', 'Ce lieu appartient aux miens ! Allez-vous-en !', 'Ce lieu appartient aux miens ! Allez-vous-en !', 26124),
(133615, 'frFR', 'N’aurons-nous donc jamais la paix ?', 'N’aurons-nous donc jamais la paix ?', 26124),
(133616, 'frFR', 'Je ne vous laisserai pas me torturer !', 'Je ne vous laisserai pas me torturer !', 26124),
(133617, 'frFR', 'Quand cela prendra-t-il fin ?', 'Quand cela prendra-t-il fin ?', 26124),
(133618, 'frFR', 'Si seulement j’avais… fui…', 'Si seulement j’avais… fui…', 26124),
(133619, 'frFR', 'Nous n’avions aucune échappatoire.', 'Nous n’avions aucune échappatoire.', 26124),
(133620, 'frFR', 'Velen… pourquoi ?', 'Velen… pourquoi ?', 26124),
(133621, 'frFR', 'Les ténèbres… J’avais espoir… que la Lumière…', 'Les ténèbres… J’avais espoir…', 26124),
(133622, 'frFR', 'Je n’en peux plus.', 'Je n’en peux plus.', 26124),
(133623, 'frFR', 'Je vais demander à nos troupes d’établir un avant-poste à l’extérieur du bastion de la Légion pendant que vous parlez à Magni.', '', 26124),
(133624, 'frFR', 'This is the song that never ends. It just goes on and on, my friend. Some people started singing, not knowing what it was, and now they\'re still singing it. No reason... just because!', '', 26124),
(133625, 'frFR', 'Je suis prêt. Réessayons !', 'Je suis prête. Réessayons !', 26124),
(133626, 'frFR', 'Prête quand vous voudrez !', 'Prête quand vous voudrez !', 26124),
(133627, 'frFR', 'Vous ferez la fierté d’Argus. Prenez votre récompense.', '', 26124),
(133628, 'frFR', 'Les murmures de la pierre apaisent le cœur de mon peuple. Il est étonnant que vous les entendiez aussi.', '', 26124),
(133629, 'frFR', 'Quand l’esprit d’Azeroth me parle, c’est comme une chanson. C’est très beau, mais le message n’est pas vraiment clair.', '', 26124),
(133630, 'frFR', 'L’âme d’Argus n’est pas comme ça. Elle est tourmentée… brisée. Faites attention, ou sa souffrance vous submergera !', '', 26124),
(133631, 'frFR', 'Il… Il veut nous montrer quelque chose…', '', 26124),
(133634, 'frFR', 'Vous allez payer cher vos exactions.', '', 26124),
(133635, 'frFR', 'Nous frappons à la faveur des ombres.', '', 26124),
(133636, 'frFR', 'Pour les nôtres !', '', 26124),
(133637, 'frFR', 'Pour les morts !', '', 26124),
(133639, 'frFR', 'Acalah pek ecta !', '', 26124),
(133640, 'frFR', 'Krypta !', '', 26124),
(133641, 'frFR', 'Pheta vi acahachi !', '', 26124),
(133642, 'frFR', 'Au combat !', '', 26124),
(133647, 'frFR', 'Krakaa cui-di-cui', '', 26124),
(133649, 'frFR', 'Courou cui-cui', '', 26124),
(133650, 'frFR', 'Kraa cui-cui', '', 26124),
(133651, 'frFR', 'Krakalaa', '', 26124),
(133652, 'frFR', 'Observation', 'Observation', 26124),
(133653, 'frFR', '', 'C’est bien ce que je pensais.', 26124),
(133654, 'frFR', 'Misérable morpion. Votre arrogance a causé votre perte !', '', 26124),
(133655, 'frFR', 'Vous n’êtes pas digne.', '', 26124),
(133671, 'frFR', 'Nos troupes ont établi un avant-poste à la citadelle, grand exarque.', '', 26124),
(133673, 'frFR', 'Bien. Il est temps que nous prenions notre destin en main.', '', 26124),
(133677, 'frFR', 'Téléportation', 'Téléportation', 26124),
(133733, 'frFR', '<Cœur gangrené d’Argus>', '<Cœur gangrené d’Argus>', 26124),
(133734, 'frFR', '<Déclencheur du jugement de la Lumière>', '<Déclencheur du jugement de la Lumière>', 26124),
(133735, 'frFR', '', 'J’ai deux mots à vous dire, maître chasseur.', 26124),
(133736, 'frFR', '', 'Vereesa m’a dit que vous l’avez accompagnée pour la mission à Niskara. Que vous avez risqué votre vie pour me sauver et que vous l’avez empêchée de tomber dans le piège de l’inquisiteur.', 26124),
(133737, 'frFR', '', 'De toute évidence, vous maniez Thas’dorah avec adresse et subtilité. Vous honorez cet arc et la mémoire de ceux qui l’ont utilisé avant vous.', 26124),
(133738, 'frFR', '', 'Il viendra peut-être un jour où j’aurais à nouveau besoin de l’arme de ma famille. Mais je dois suivre une voie différente, du moins pour le moment.', 26124),
(133739, 'frFR', '', 'Portez fièrement Thas’dorah. Vous avez prouvé que vous en êtes digne.', 26124),
(133740, 'frFR', '', 'Impossible ! Je refuse de croire qu’elle dirige la Horde à présent. Pas après tout ce que cette dernière a fait subir à notre peuple pendant la guerre.', 26124),
(133743, 'frFR', '', 'Ce n’est pas tout. Je… Je ne sais pas comment te parler du reste. Ni même si c’est le bon moment pour…', 26124),
(133744, 'frFR', '', 'Je dois savoir, Vereesa. Qu’est-il advenu de notre sœur ?', 26124),
(133746, 'frFR', '', 'Laisse-moi un instant. Je vais essayer de t’expliquer au mieux…', 26124),
(133747, 'frFR', 'Un autre démon vous attend. Trouvez-le et mettez un terme à son existence.', '', 26124),
(133748, 'frFR', 'L’un après l’autre, nous leur ferons comprendre la folie de leur croisade.', '', 26124),
(133749, 'frFR', 'Un démon terrorise nos alliés dans les fosses. Mettez fin à cette menace au plus vite.', '', 26124),
(133750, 'frFR', 'Encore un adversaire réduit en cendres.', '', 26124),
(133751, 'frFR', 'Un autre laquais de la Légion vient nous défier. Coupez court à ses ambitions insensées.', '', 26124),
(133753, 'frFR', 'La Légion ne cédera pas. Mais nous non plus.', '', 26124),
(133761, 'frFR', '', 'Sois patient, Arator. Cela prendra peut-être du temps, mais ta famille sera à nouveau réunie. J’en suis certaine.', 26124),
(133762, 'frFR', 'Mes éclaireurs ont trouvé le cadavre d’Aggonar. Nous avons une dette envers vous, grand exarque. Et envers vous également.', '', 26124),
(133767, 'frFR', '', 'L’un des maîtres de la Légion est finalement tombé, mais la guerre est loin d’être finie.

Était-ce là le plan de Sargeras depuis le début ? Le dénouement qu’il escomptait ? Ou est-ce le fait d’un autre… qui a déjà trahi ce monde par le passé.

<Maiev plisse les yeux tandis qu’elle regarde le ciel.>

Je garderai l’œil ouvert… et me tiendrai prête.', 26124),
(133770, 'frFR', 'On dirait que vous avez besoin d’une bonne leçon sur la souffrance. Je vais m’en charger.', '', 26124),
(133771, 'frFR', '', 'Voici un engagement auquel vous ne pourrez pas échapper.', 26124),
(133772, 'frFR', 'Vos lignes de front ne pourront résister à mon attaque !', '', 26124),
(133773, 'frFR', '', 'C’était ça, votre plan ?', 26124),
(133774, 'frFR', 'Vous vous attendiez à quoi ?', '', 26124),
(133776, 'frFR', 'Vous n’avez pas votre place sur mon champ de bataille.', '', 26124),
(133777, 'frFR', 'Le drake a purgé pour vous le sanctuaire draconique Azur !', 'Le drake a purgé pour vous le sanctuaire draconique Azur !', 26124),
(133778, 'frFR', 'Le drake a purgé pour vous le sanctuaire draconique Obsidien !', 'Le drake a purgé pour vous le sanctuaire draconique Obsidien !', 26124),
(133779, 'frFR', 'Le drake a purgé pour vous le sanctuaire draconique Émeraude !', 'Le drake a purgé pour vous le sanctuaire draconique Émeraude !', 26124),
(133780, 'frFR', 'Le drake a purgé pour vous le sanctuaire draconique Rubis !', 'Le drake a purgé pour vous le sanctuaire draconique Rubis !', 26124),
(133781, 'frFR', 'Le drake vous a accordé une puissante bénédiction !', 'Le drake vous a accordé une puissante bénédiction !', 26124),
(133782, 'frFR', 'Je cherchais à atteindre des hauteurs afin de repérer un passage pour Velen lorsque la Légion nous est tombée dessus.$b$bJ’ai assuré ses arrières pendant qu’il battait en retraite, mais j’ai été séparé des autres.$b$bVous avez du nouveau ?', '', 26124),
(133783, 'frFR', '<Transmettre les ordres de Fareeya.>', '<Transmettre les ordres de Fareeya.>', 26124),
(133787, 'frFR', 'Pas de pitié !', '', 26124),
(133789, 'frFR', 'Pitoyable.', '', 26124),
(133791, 'frFR', '', 'Vos flancs étaient à découvert.', 26124),
(133792, 'frFR', 'Mon nom restera gravé dans les mémoires !', '', 26124),
(133795, 'frFR', 'Inconcevable !', '', 26124),
(133796, 'frFR', '', 'Comment ai-je pu être vaincue…', 26124),
(133797, 'frFR', 'Je suis le cube de sagesse.', '', 26124),
(133800, 'frFR', 'Plus vite ! Le maître ne tolère pas la paresse.', 'Plus vite ! Le maître ne tolère pas la paresse.', 26124),
(133807, 'frFR', 'Baraat le Long-Tireur vous salue.', '', 26124),
(133808, 'frFR', 'Quelle sagesse détiens-tu, ô cube ?', 'Quelle sagesse détiens-tu, ô cube ?', 26124),
(133809, 'frFR', '<Le redresseur de torts respire bruyamment, sa masse et son bouclier dégoulinant d’ichor.>$b$bQu’y a-t-il ?', '', 26124),
(133810, 'frFR', 'Je suis dépositaire du savoir des intemporels.', '', 26124),
(133811, 'frFR', 'Quel est votre but ?', 'Quel est votre but ?', 26124),
(133812, 'frFR', 'Je suis capable d’accorder le premier signe.', '', 26124),
(133813, 'frFR', 'Que désirez-vous ?', 'Que désirez-vous ?', 26124),
(133814, 'frFR', 'Le grand redresseur de torts Sorvos grogne son assentiment.', '', 26124),
(133815, 'frFR', 'Mes créateurs sont à la recherche d’un héritier des plus cocasse.', '', 26124),
(133816, 'frFR', 'Ces spores décupleront vos forces, avortons ! Remettez-vous au travail ou je vous tue de mes mains !', '', 26124),
(133817, 'frFR', '<Le cube se reconfigure en un éclair.>

Veuillez placer votre bras sous le cube.', '', 26124),
(133818, 'frFR', '<Passer le bras sous le cube.>', '<Passer le bras sous le cube.>', 26124),
(133821, 'frFR', 'Un pierre étrange se trouve face à vous. Étrange, car elle est percée d’un trou lumineux en son centre.

Le trou dans la pierre est environ à hauteur de votre bras.', '', 26124),
(133822, 'frFR', '<Passer le bras dans le trou.>', '<Passer le bras dans le trou.>', 26124),
(133823, 'frFR', 'Votre bras a l’air tout petit dans ce trou, dommage qu’il ne se passe rien d’autre.', '', 26124),
(133824, 'frFR', 'Votre bras est déjà mieux proportionné par rapport au trou, mais il ne remplit pas tout à fait l’espace.', '', 26124),
(133825, 'frFR', 'Ma mère va sans doute bientôt demander des nouvelles de Sylvanas. Que vas-tu lui dire ?', '', 26124),
(133826, 'frFR', '', 'Je sais bien qu’il nous faudra avoir cette conversation, mais je redoute tant ce moment. Comment expliquer à Alleria ce qu’est devenue notre sœur ? La vérité lui brisera le cœur.', 26124),
(133836, 'frFR', 'Vous pensez pouvoir détruire mes machines avec ces armes pathétiques ?', '', 26124),
(133837, 'frFR', 'Je vais vous renvoyer… en pièces détachées !', '', 26124),
(133838, 'frFR', 'Vous avez des défauts de construction.', '', 26124),
(133839, 'frFR', 'Maintenant, je suis… en pièces détachées.', '', 26124),
(133840, 'frFR', 'Vos têtes décoreront ma salle des trophées.', '', 26124),
(133841, 'frFR', 'Je suis payé double si vous criez.', '', 26124),
(133842, 'frFR', 'kra', '', 26124),
(133843, 'frFR', 'kuika', '', 26124),
(133844, 'frFR', 'claaa', '', 26124),
(133845, 'frFR', 'tchi', '', 26124),
(133846, 'frFR', 'Extraction', 'Extraction', 26124),
(133847, 'frFR', 'cui-cui', '', 26124),
(133848, 'frFR', 'a', '', 26124),
(133849, 'frFR', 'courou', '', 26124),
(133850, 'frFR', 'cuila', '', 26124),
(133851, 'frFR', 'do', '', 26124),
(133852, 'frFR', 'cou', '', 26124),
(133853, 'frFR', 'ca', '', 26124),
(133854, 'frFR', 'cou', '', 26124),
(133855, 'frFR', 'claquou', '', 26124),
(133856, 'frFR', 'pa', '', 26124),
(133857, 'frFR', 'kraii', '', 26124),
(133858, 'frFR', 'krakui', '', 26124),
(133859, 'frFR', 'boc', '', 26124),
(133860, 'frFR', 'klak', '', 26124),
(133861, 'frFR', 'Je vais devoir recoller les morceaux pour collecter ma prime.', '', 26124),
(133862, 'frFR', '<Telaamon baisse sa lame et vous regarde d’un air interrogateur.>', '', 26124),
(133863, 'frFR', 'Le maître-lame Telaamon vous salue sèchement d’un hochement de tête.', '', 26124),
(133864, 'frFR', 'Je regrette… d’avoir accepté… ce contrat…', '', 26124),
(133866, 'frFR', 'Du calme. Ce n’est que le vent qui souffle.', '', 26124),
(133867, 'frFR', 'Ne bouge pas, mon petit. Nous sommes en sécurité ici.', '', 26124),
(133868, 'frFR', 'Plus un geste ! Ces vents qui jouent avec nos sens perturbent les créatures sauvages.', '', 26124),
(133869, 'frFR', 'Ne bouge pas. Le village dissimule notre présence. Nous n’avons rien à craindre, ici.', '', 26124),
(133870, 'frFR', 'Du calme, mon jeune ami ! Ne bouge pas !', '', 26124),
(133871, 'frFR', 'Je me suis diversifié, mec. J’ai rentré tout plein de nouveaux trucs. Y a des affaires à faire.', '', 26124),
(133873, 'frFR', 'Approchez, que je partage ma souffrance avec vous !', '', 26124),
(133874, 'frFR', 'Si facilement brisés !', '', 26124),
(133875, 'frFR', 'Mieux vaut mourir ici, où elle n’a aucun pouvoir sur vous.', '', 26124),
(133876, 'frFR', 'La mort… nous emporte… tous.', '', 26124),
(133877, 'frFR', '', 'Je suis le frisson glacé qui court le long de votre dos.', 26124),
(133878, 'frFR', '', 'J’ai hâte d’entendre votre chair grésiller.', 26124),
(133879, 'frFR', '', 'Vous ne pouvez pas échapper aux ombres.', 26124),
(133880, 'frFR', '', 'Vos corps seront figés dans une agonie éternelle.', 26124),
(133881, 'frFR', '', 'Calcinés et noircis.', 26124),
(133882, 'frFR', '', 'Aucune lumière ne peut percer mes ombres.', 26124),
(133884, 'frFR', 'Le vaisseau de Kil’jaeden. Bien que détruit, il ne cesse de nous nuire. Débarrassons les lieux de ce fléau.', '', 26124),
(133885, 'frFR', 'Dommage que la terrible empreinte de Kil’jaeden ne puisse être effacée aussi facilement que vous avez purifié ces terres.', '', 26124),
(133886, 'frFR', 'La Légion appareille un dévastateur afin qu’il attaque le Xénédar. Emparez-vous-en !', '', 26124),
(133887, 'frFR', 'Joli tir ! Maintenant que ce maudit vaisseau est hors service, nous pouvons concentrer nos efforts sur d’autres fronts.', '', 26124),
(133888, 'frFR', '', 'Vos membres feront un magnifique trophée.', 26124),
(133889, 'frFR', '', 'Un nouveau corps pour les flammes !', 26124),
(133890, 'frFR', '', 'Vous aviez raison de craindre les ténèbres.', 26124),
(133891, 'frFR', 'Pardonne-moi, mon fils.', '', 26124),
(133892, 'frFR', 'Velen ?', '', 26124),
(133894, 'frFR', '', 'Si froid…', 26124),
(133895, 'frFR', '', 'Je perçois une grande détresse émanant de l’intérieur. L’ura…', 26124),
(133896, 'frFR', 'Oui, le Naaru. Nous devons trouver le moyen d’entrer. Sers-toi des compétences que je t’ai apprises pour ouvrir la porte, Alleria.', '', 26124),
(133897, 'frFR', 'Êtes-vous blessé ?', '', 26124),
(133898, 'frFR', '', 'Compris. Champions, une fois la porte ouverte, frayez-nous un chemin jusque L’ura. Nous serons juste derrière vous.', 26124),
(133900, 'frFR', 'Je n’ai rien.', '', 26124),
(133901, 'frFR', 'Vous arrivez à point nommé. Nous devons trouver le cimier de la Connaissance avant que Talgath le mette hors de notre portée.', '', 26124),
(133902, 'frFR', '', 'Je ne m’éteindrai jamais…', 26124),
(133903, 'frFR', '', 'Je sombre dans l’oubli…', 26124),
(133905, 'frFR', 'Alors il est ici. C’est ce que je craignais.', '', 26124),
(133906, 'frFR', 'Mort ! Mort et souffrance !', '', 26124),
(133907, 'frFR', 'Une vie anéantie !', '', 26124),
(133908, 'frFR', 'Toute vie prend fin.', '', 26124),
(133909, 'frFR', 'Nous allons escorter Velen jusqu’au cimier.', '', 26124),
(133910, 'frFR', 'Mon tourment… prend fin…', '', 26124),
(133914, 'frFR', 'Montrez-nous le chemin, prophète.', '', 26124),
(133920, 'frFR', 'La voie est libre. La mère de la Lumière nous attend.$b$bDépêchons-nous, plus aucun obstacle ne se dresse entre elle et la Légion.', '', 26124),
(133921, 'frFR', 'Bien que les ennemis nous cernent de toute part, c’est un plaisir de retrouver mes soldats.', '', 26124),
(133922, 'frFR', 'Si vous couvrez nos retraites, nous réussirons peut-être.', '', 26124),
(133927, 'frFR', '', 'La voie est libre ! Dépêchez-vous, héros !', 26124),
(133930, 'frFR', 'La Lumière nous accompagne.', '', 26124),
(133931, 'frFR', 'Nous avons essuyé de lourdes pertes… Il va falloir regarnir nos rangs.', '', 26124),
(133932, 'frFR', 'Nous gagnerons ce combat.', '', 26124),
(133937, 'frFR', 'Je n’ai pas fui l’Arcatraz pour mourir de votre main !', '', 26124),
(133940, 'frFR', 'Vous avez volé mon pouvoir ! Argus ne me parle plus !', '', 26124),
(133948, 'frFR', 'Le cœur gangrené se nourrit des énergies d’Argus. Bientôt, vous ne pourrez plus m’arrêter !', '', 26124),
(133949, 'frFR', 'Vous arrivez trop tard ! Ma puissance augmente… Bientôt, vous tomberez sous mes coups !', '', 26124),
(133954, 'frFR', 'Que venons-nous faire à Stratholme ?', 'Que venons-nous faire à Stratholme ?', 26124),
(133955, 'frFR', 'Que faisons-nous à Andorhal ?', 'Que faisons-nous à Andorhal ?', 26124),
(133956, 'frFR', 'Pourquoi sommes-nous au mont Hyjal ?', 'Pourquoi sommes-nous au mont Hyjal ?', 26124),
(133957, 'frFR', 'Que venons-nous faire au Puits d’éternité ?', 'Que venons-nous faire au Puits d’éternité ?', 26124),
(133967, 'frFR', 'Oui ! Ils fuient vers la terrasse ! Ils sont exactement où on voulait les amener.', '', 26124),
(133972, 'frFR', 'Siphonne l’énergie du portail ! La faiblesse du Naaru deviendra ta force !', '', 26124),
(133973, 'frFR', 'Absorbe son ombre, Alleria ! Fais comme je t’ai appris !', '', 26124),
(133976, 'frFR', '', 'Héros, le Naaru est affaibli !', 26124),
(133977, 'frFR', '', 'À l’attaque, champions ! Le Naaru est temporairement affaibli !', 26124),
(133978, 'frFR', '', 'Vite, héros ! Le Naaru est étourdi, mais ça ne durera pas !', 26124),
(134004, 'frFR', 'Même en plein bourbier, rien ne saurait masquer la pestilence de la Légion. Étripez-les !', '', 26124),
(134005, 'frFR', 'Les démons se sont inoculé des spores pour dissimuler leurs attaques. Montrez-leur qu’on n’échappe pas si facilement à la mort !', '', 26124),
(134006, 'frFR', 'Leur commandant approche ! Faites-lui regretter d’avoir profané ce monde.', '', 26124),
(134008, 'frFR', 'C’en est fini de la Légion sur ces terres. Pour l’heure, notre guerre continue sur Argus.', '', 26124),
(134019, 'frFR', 'S’ils s’échappent, on entendra vos hurlements de souffrance dans tout Antorus !', '', 26124),
(134020, 'frFR', 'Laissez-moi passer. Je vais m’en occuper en personne.', '', 26124),
(134024, 'frFR', 'Le maître-lame Telaamon vous salue.', '', 26124),
(134025, 'frFR', 'Le grand redresseur de torts Sorvos vous salue d’un hochement de tête.', '', 26124),
(134026, 'frFR', '<Le regard impassible de Velen est rivé sur la statue devant lui.>', '', 26124),
(134027, 'frFR', 'Permettez-moi de vous montrer ce que j’ai fait. Alors peut-être pourrai-je enfin faire la paix avec moi-même.', '', 26124),
(134028, 'frFR', 'Montrez-moi.', 'Montrez-moi.', 26124),
(134029, 'frFR', 'IGC : Sargeras apparaît devant le triumvirat', 'IGC : Sargeras apparaît devant le triumvirat', 26124),
(134030, 'frFR', 'Il est là.', '', 26124),
(134031, 'frFR', 'Rester sur vos positions est très inhabituel de votre part, Velen.', '', 26124),
(134032, 'frFR', 'Un changement bienvenu, c’est certain.', '', 26124),
(134033, 'frFR', 'Après tout ce qu’il m’a fait endurer… Après tout ce que mon peuple a subi… L’heure de vérité a enfin sonné.$b$b<Velen resserre sa prise sur son bâton.>$b$bDès que vous serez $gprêt:prête;, nous mettrons un terme à tout ceci, vous et moi.', '', 26124),
(134034, 'frFR', 'Je suis prêt.', 'Je suis prête.', 26124),
(134039, 'frFR', 'La traque est terminée ! Vous êtes à moi, prophète !', '', 26124),
(134040, 'frFR', 'Nous sommes avec vous, Velen.', '', 26124),
(134041, 'frFR', 'Pheta thones gamera. Puisse la Lumière éclairer notre chemin.', '', 26124),
(134044, 'frFR', 'Oh, comme Kil’jaeden a souffert à cause de vous ! Savez-vous à quel point votre départ l’a blessé ?', '', 26124),
(134045, 'frFR', 'J’ai aussi perdu mon frère bien-aimé ce jour-là.', '', 26124),
(134046, 'frFR', 'Vous ne l’avez pas perdu. Vous avez tout abandonné, tout ! Votre peuple, votre planète… même votre famille !', '', 26124),
(134047, 'frFR', 'Je n’ai pas oublié votre trahison !', '', 26124),
(134050, 'frFR', 'J’espérais vous donner une bonne raison de rester. Vous êtes vraiment sans cœur, pour laisser derrière vous femme et enfant.', '', 26124),
(134051, 'frFR', 'Silence ! Comment osez-vous parler d’eux !', '', 26124),
(134052, 'frFR', 'J’ai touché une corde sensible, n’est-ce pas ?', '', 26124),
(134053, 'frFR', 'Sheet-sah, vous vous cachez derrière vos alliés… comme d’habitude.', '', 26124),
(134054, 'frFR', 'Nous finirons ça une autre f…', '', 26124),
(134055, 'frFR', 'Non. Nous allons en finir maintenant.', '', 26124),
(134056, 'frFR', 'Je vois. Bon voyage, Talgath.', '', 26124),
(134057, 'frFR', 'AAAaaahhh !', '', 26124),
(134058, 'frFR', 'Der’ek… manul…', '', 26124),
(134071, 'frFR', 'Vous avez devant vous les vestiges de nos souvenirs passés, des échos de ce qu’était notre peuple avant la venue du Titan noir.$B$BLorsque l’un des nôtres échappe à l’emprise de la Légion, il nous revient parfois avec une relique de nos anciennes coutumes.$b$bCes objets symbolisent tout ce que nous avons perdu… et ils nous rappellent chaque jour ce pour quoi nous nous battons.', '', 26124),
(134080, 'frFR', 'Vous ne me tuerez pas si facilement ! Le cœur gangrené me protégera !', '', 26124),
(134081, 'frFR', 'Vous pensez avoir gagné ? Je suis immortel !', '', 26124),
(134082, 'frFR', 'Nombreux sont ceux qui ont tenté de me tuer. Tous sont morts, et je vis toujours !', '', 26124),
(134083, 'frFR', 'Cela n’était pas censé arriver ! Je devais vivre éternellement !', '', 26124),
(134097, 'frFR', 'Des fissures d’azérite commencent à entrer en éruption !', '', 26124),
(134102, 'frFR', '|TInterface\\ICONS\\SPELL_FIRE_TWILIGHTNOVA:20|tLe vice-roi Nezhar commence à lancer |cFFFF0000|Hspell:248736|h[Crépuscule éternel]|h|r !', '', 26124),
(134103, 'frFR', '', 'What news, hero? I sense that darkness has descended upon the bluff.', 26124),
(134104, 'frFR', 'Les Dieux très anciens ont jeté leur dévolu sur l’esprit d’un de mes alliés. Peut-on le sauver ?', 'Les Dieux très anciens ont jeté leur dévolu sur l’esprit d’un de mes alliés. Peut-on le sauver ?', 26124),
(134105, 'frFR', '', 'Parfois, il faut s’aventurer dans le monde des rêves pour découvrir la vérité.', 26124),
(134106, 'frFR', '', 'I wish I could offer better news. In my experience, once the Old Gods take hold, hope is all but lost.', 26124),
(134107, 'frFR', 'The spirits are restless. A shadow looms over this place. The very earth feels... wrong.', '', 26124),
(134108, 'frFR', 'Seules de puissantes protections sauraient tenir en respect les Dieux très anciens.

Un lieu équipé pour résister à la magie du Vide pourrait s’avérer utile.', '', 26124),
(134113, 'frFR', '$n a trouvé de l’azérite !', '', 26124),
(134114, 'frFR', '$n a trouvé de l’azérite !', '', 26124),
(134117, 'frFR', 'C’est la fin pour vous. S’il vous reste la moindre trace de bonté, vous nous aiderez à trouver le cimier de la Connaissance.', '', 26124),
(134118, 'frFR', '', 'I sense you bring ill news.', 26124),
(134119, 'frFR', 'Hah ! Vous arrivez beaucoup trop tard. Rien ni personne ne quittera ce temple. Pas même la Lumière.', '', 26124),
(134120, 'frFR', 'INTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t Vous avez été la cible de |cFFFF0000|Hspell:240209|h[Fragmentation spontanée]|h|r !', 'INTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t Vous avez été la cible de |cFFFF0000|Hspell:240209|h[Fragmentation spontanée]|h|r !', 26124),
(134121, 'frFR', '|TINTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t Vous êtes la cible de |cFFFF0000|Hspell:239153|h[Fragmentation spontanée]|h|r !', '|TINTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t Vous êtes la cible de |cFFFF0000|Hspell:239153|h[Fragmentation spontanée]|h|r !', 26124),
(134122, 'frFR', '', 'If the Light is with you, then you have a chance to save your friend.$b$bBut do not tarry. Unless the Old Gods\' influence is countered quickly, his mind will be lost to madness.', 26124),
(134124, 'frFR', '', 'Une autre attaque ! Restez sur vos gardes !', 26124),
(134126, 'frFR', '', 'La Lumière va incinérer vos âmes !', 26124),
(134127, 'frFR', '', 'Avec moi, nobles guerriers !', 26124),
(134128, 'frFR', '', 'Mon glaive va vous trancher en deux.', 26124),
(134129, 'frFR', '', 'J’ai trop sacrifié pour me permettre d’échouer !', 26124),
(134130, 'frFR', '', 'Vais-je vous tuer avec ma magie ou mon épée ?', 26124),
(134131, 'frFR', '', 'Nous vous détruirons, quoi qu’il nous en coûte !', 26124),
(134133, 'frFR', '', 'Arkonos vi acahachi !', 26124),
(134134, 'frFR', '', 'Vous ne trouverez pas le salut, traîtres !', 26124),
(134135, 'frFR', '', 'Par la Lumière, soyez purifiés.', 26124),
(134136, 'frFR', '', 'Vous êtes au-delà de toute rédemption !', 26124),
(134137, 'frFR', '', 'Âmes maudites ! Votre défaite sera rapide.', 26124),
(134138, 'frFR', '', 'Amenez-moi les blessés. Je vais soigner leurs plaies et les débarrasser de cette saleté d’une simple prière !', 26124),
(134139, 'frFR', '', 'Pheta thones gamera.', 26124),
(134140, 'frFR', '', 'Si vous pouvez marcher, vous pouvez vous battre.', 26124),
(134141, 'frFR', '', 'Vous pourrez vous reposer quand ils seront tous morts ! Continuez à vous battre !', 26124),
(134142, 'frFR', '', 'Des blessures ? Bah ! Vous tenez toujours debout. Continuez à vous battre, nous parlerons plus tard.', 26124),
(134143, 'frFR', '', 'Avez-vous besoin d’aide pour exterminer nos ennemis ?', 26124),
(134144, 'frFR', '', 'Restez à l’affût de tout ce qui pourrait être utile.', 26124),
(134145, 'frFR', '', 'Dioniss aca.', 26124),
(134146, 'frFR', '', 'La Légion ne reculera devant rien. Faites attention à vous.', 26124),
(134147, 'frFR', '', 'Faites attention à vous et tuez de nombreux démons.', 26124),
(134148, 'frFR', '', 'Chaque démon que vous tuez en est un de moins à affronter.', 26124),
(134153, 'frFR', '', 'J’adoooore tuer des démons !', 26124),
(134154, 'frFR', 'La perte du Xénédar est une véritable tragédie, mais ce vaisseau n’est pas si mal. Il nous reste peut-être une chance de vaincre la Légion.', '', 26124),
(134160, 'frFR', '', 'Pourquoi les gens sont-ils choqués par le sang ? On en a tous besoin pour vivre. Sauf les traîtres. C’est pourquoi il faut verser le leur.', 26124),
(134165, 'frFR', 'Ça fait toujours plaisir de croiser $gun autre:une autre:c; $c dans nos rangs. Toute l’aide que nous pourrons obtenir est bonne à prendre.', '', 26124),
(134166, 'frFR', '', 'J’ai entendu les rumeurs, vous savez. On dit que je suis assoiffée de sang et que ma conduite est indigne d’une prêtresse.', 26124),
(134167, 'frFR', 'Ouvrez l’œil au cas où vous tomberiez sur des herbes incrustées de corruption. C’est là que l’on trouve l’astralée.', '', 26124),
(134168, 'frFR', 'J’ai identifié un point d’extraction sûr, au nord-ouest de votre position actuelle.', '', 26124),
(134169, 'frFR', 'Un téléporteur y est activé.', '', 26124),
(134170, 'frFR', 'Venez. Je préfère ne pas trop m’attarder ici.', '', 26124),
(134171, 'frFR', 'Les dernières paroles de Talgath… « Pas même la Lumière ». Qu’a-t-il voulu dire ?', '', 26124),
(134173, 'frFR', 'Je ne fais qu’un avec la Lumière. La Lumière est avec moi.', '', 26124),
(134174, 'frFR', '', 'Les créatures gangrenées qui hantent ces terres désolées produisent les peaux les plus pestilentielles qu’il m’ait été donné de renifler.$b$bAvec un peu de chance, nous finirons par quitter cet endroit maudit pour nous installer quelque part où la faune sent meilleur.', 26124),
(134175, 'frFR', 'Ouvrez-vous à la sérénité.', '', 26124),
(134176, 'frFR', '', 'Salutations, $n. Comment se présente la bataille contre la Légion ?', 26124),
(134177, 'frFR', 'Nourrissez la flamme, combattez les ténèbres.', '', 26124),
(134178, 'frFR', 'Suivez votre voie avec confiance.', '', 26124),
(134179, 'frFR', 'Dioniss aca.', '', 26124),
(134180, 'frFR', 'Quand la défaite est impossible, la victoire devient inévitable.', '', 26124),
(134181, 'frFR', 'Vous ne faites pas le poids face à ma lame.', '', 26124),
(134182, 'frFR', 'Soumettez-vous ou vous serez brisés.', '', 26124),
(134183, 'frFR', 'Votre défaite est certaine.', '', 26124),
(134184, 'frFR', 'Deux talbuks s’affrontant à coups de cornes.', '', 26124),
(134185, 'frFR', 'L’aube se lève.', '', 26124),
(134187, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMEBREATH.BLP:20|tKin’garoth a renforcé |cFFFF0000|Hspell:246840|h[Dévastateur]|h|r !', '', 26124),
(134188, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_FLAMETOUNGE.BLP:20|tKin’garoth a renforcé |cFFFF0000|Hspell:248475|h[Frappe réverbérante]|h|r !', '', 26124),
(134189, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMERING.BLP:20|tKin’garoth a renforcé |cFFFF0000|Hspell:246779|h[Bombe diabolique]|h|r !', '', 26124),
(134190, 'frFR', '', 'Hum… l’un de nos gagnants semble avoir quitté les lieux. Tant pis !', 26124),
(134191, 'frFR', 'Placement', 'Placement', 26124),
(134192, 'frFR', 'Le Vide dévore les faibles !', '', 26124),
(134193, 'frFR', 'Pitoyable !', '', 26124),
(134194, 'frFR', 'Quelle… force.', '', 26124),
(134195, 'frFR', 'Enfin… la clarté. Le Vide… était faible.', '', 26124),
(134196, 'frFR', 'Ténèbres, donnez-moi la force !', '', 26124),
(134197, 'frFR', 'Je vous annihilerai !', '', 26124),
(134198, 'frFR', 'Le Vide m’appelle !', '', 26124),
(134199, 'frFR', 'Je vais précipiter votre crépuscule !', '', 26124),
(134200, 'frFR', 'Non ! Les ténèbres… m’étaient promises…', '', 26124),
(134201, 'frFR', 'Ma mort… n’empêchera rien. Le Vide… submergera tout.', '', 26124),
(134202, 'frFR', 'Votre vie s’achève maintenant !', '', 26124),
(134203, 'frFR', 'Contemplez l’abysse et sombrez dans le désespoir !', '', 26124),
(134204, 'frFR', 'Votre lumière se meurt.', '', 26124),
(134205, 'frFR', 'Les ténèbres vous absorbent !', '', 26124),
(134206, 'frFR', 'Nos efforts ne seront pas interrompus !', '', 26124),
(134207, 'frFR', 'Mes bêtes ont faim.', '', 26124),
(134210, 'frFR', 'Une simple… erreur tactique…', '', 26124),
(134212, 'frFR', 'Ce n’est pas… ce que j’avais prévu.', '', 26124),
(134213, 'frFR', 'Je frappe vite et fort !', '', 26124),
(134214, 'frFR', 'J’aurai toujours un coup d’avance !', '', 26124),
(134215, 'frFR', 'De la chair fraîche pour vous, mes petits.', '', 26124),
(134216, 'frFR', 'Il est si facile de vous vaincre.', '', 26124),
(134217, 'frFR', 'Disparaissez dans le Vide !', '', 26124),
(134218, 'frFR', 'Je vais vous bannir dans les ténèbres !', '', 26124),
(134220, 'frFR', 'Il n’y a pas assez de participants.', '', 26124),
(134221, 'frFR', '', 'Chaque jour pendant un millier d’années, j’ai pensé à ce que je voulais lui dire. Mais aujourd’hui… les mots me manquent.', 26124),
(134222, 'frFR', 'Je sais, mon amour. Je ressens la même chose. Mais dès que nous verrons notre fils, nos cœurs parleront pour nous.', '', 26124),
(134238, 'frFR', '', 'Je ne vous laisserai pas me torturer !', 26124),
(134239, 'frFR', '', 'N’aurons-nous donc jamais la paix ?', 26124),
(134240, 'frFR', '', 'Ce lieu appartient aux miens ! Allez-vous-en !', 26124),
(134241, 'frFR', '', 'Vous ne savez rien de ma souffrance !', 26124),
(134242, 'frFR', '', 'Vous n’avez rien à faire ici !', 26124),
(134244, 'frFR', 'Soumettez-vous à Sargeras !', 'Soumettez-vous à Sargeras !', 26124),
(134245, 'frFR', 'C’est ça ! Fuyez ! Fuyez !', 'C’est ça ! Fuyez ! Fuyez !', 26124),
(134246, 'frFR', 'Rejoignez les abîmes, espèces de lâches !', 'Rejoignez les abîmes, espèces de lâches !', 26124),
(134247, 'frFR', 'Vous allez payer pour votre stupidité !', 'Vous allez payer pour votre stupidité !', 26124),
(134248, 'frFR', 'C’est le dernier cadeau que vous refuserez !', 'C’est le dernier cadeau que vous refuserez !', 26124),
(134249, 'frFR', 'Nul ne s’oppose à Sargeras !', 'Nul ne s’oppose à Sargeras !', 26124),
(134250, 'frFR', '', 'Je n’en peux plus.', 26124),
(134251, 'frFR', '', 'Les ténèbres… J’avais espoir…', 26124),
(134253, 'frFR', '', 'Velen… pourquoi ?', 26124),
(134254, 'frFR', '', 'Nous n’avions aucune échappatoire.', 26124);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134255, 'frFR', '', 'Si seulement j’avais… fui…', 26124),
(134256, 'frFR', '', 'Quand cela prendra-t-il fin ?', 26124),
(134257, 'frFR', 'Fuyez… tant que vous le pouvez.', 'Fuyez… tant que vous le pouvez.', 26124),
(134258, 'frFR', 'Les érédars… sont tout-puissants…', 'Les érédars… sont tout-puissants…', 26124),
(134259, 'frFR', 'Pourquoi… fait-il si sombre ?', 'Pourquoi… fait-il si sombre ?', 26124),
(134260, 'frFR', 'Argus… s’élèvera…', 'Argus… s’élèvera…', 26124),
(134261, 'frFR', 'Vous n’avez nulle part où aller.', 'Vous n’avez nulle part où aller.', 26124),
(134262, 'frFR', 'Vous… ne vous échapperez… jamais…', 'Vous… ne vous échapperez… jamais…', 26124),
(134280, 'frFR', 'J’ai beaucoup réfléchi à notre situation. Dans l’état actuel des choses, nous serons détruits si nous assiégeons Antorus.', '', 26124),
(134281, 'frFR', 'Il reste un espoir. Un trésor qui pourrait nous donner l’avantage dont nous avons besoin.', '', 26124),
(134282, 'frFR', 'Nous l’avons appelée la couronne du triumvirat.', '', 26124),
(134283, 'frFR', 'Il y a une éternité, mes frères et moi avons confectionné une relique qui devait apporter prospérité à tous.', '', 26124),
(134284, 'frFR', 'La balise vibre d’énergie.', '', 26124),
(134285, 'frFR', 'Regagner l’entrée.', 'Regagner l’entrée.', 26124),
(134286, 'frFR', 'Je possède encore un tiers de cette relique. Je l’ai toujours avec moi. C’est l’Œil de prophétie.', '', 26124),
(134301, 'frFR', 'Krona ki cristorr !', '', 26124),
(134302, 'frFR', 'La Lumière vous souhaite la bienvenue.', '', 26124),
(134303, 'frFR', 'L’armée de la Lumière est prête.', '', 26124),
(134304, 'frFR', 'Ma foi est mon bouclier.', '', 26124),
(134305, 'frFR', 'Nous faisons front ensemble.', '', 26124),
(134306, 'frFR', 'Allez dans la Lumière.', '', 26124),
(134307, 'frFR', 'Dioniss aca.', '', 26124),
(134308, 'frFR', 'Nous n’allons pas reculer maintenant.', '', 26124),
(134311, 'frFR', 'Que la Lumière nous guide.', '', 26124),
(134312, 'frFR', 'Nous nous battons pour notre foyer… nos familles.', '', 26124),
(134313, 'frFR', 'Je suis resté trop longtemps loin de chez moi. Loin de mon fils.', '', 26124),
(134314, 'frFR', 'Lutter pied à pied contre la Légion. Savourer chaque victoire, déplorer chaque amère défaite.', '', 26124),
(134315, 'frFR', 'Mais pour Azeroth, et ceux qui nous sont chers, tout cela en valait la peine.', '', 26124),
(134316, 'frFR', '', 'Gardez les yeux sur la cible.', 26124),
(134317, 'frFR', '', 'Nous faisons notre devoir pour protéger ceux que nous aimons.', 26124),
(134318, 'frFR', '', 'Visez juste.', 26124),
(134319, 'frFR', '', 'Adieu.', 26124),
(134320, 'frFR', '', 'Les ombres peuvent être nos alliées… si nous parvenons à les contrôler.', 26124),
(134321, 'frFR', '', 'Salutations.', 26124),
(134322, 'frFR', '', 'Nous suivons tous une voie différente. Choisissez la vôtre.', 26124),
(134323, 'frFR', '', 'Votre cadavre fera un splendide trophée pour le maître !', 26124),
(134324, 'frFR', '', 'Votre Lumière ne vous sauvera pas. Pas ici !', 26124),
(134325, 'frFR', '', 'Quelles sont les nouvelles ?', 26124),
(134326, 'frFR', '', 'Utilisez toutes les armes à votre disposition.', 26124),
(134327, 'frFR', '', 'C’est un bon jour pour chasser.', 26124),
(134331, 'frFR', 'Fascinant. Tout simplement fascinant.', '', 26124),
(134332, 'frFR', 'Partez.', '', 26124),
(134333, 'frFR', 'Je représente… une alternative.', '', 26124),
(134335, 'frFR', 'Tout est une question de perspective.', '', 26124),
(134336, 'frFR', 'La chair est faible. Mais la puissance perdure.', '', 26124),
(134337, 'frFR', '', 'Vous osez poser le pied sur son monde ? Vous allez mourir !', 26124),
(134338, 'frFR', 'Ne me faites pas perdre mon temps.', '', 26124),
(134342, 'frFR', '', 'Je suis occupée, $R. Que voulez-vous ?', 26124),
(134343, 'frFR', 'J’ai votre cargaison de gangreschiste.', 'J’ai votre cargaison de gangreschiste.', 26124),
(134344, 'frFR', '', 'Il était temps. Nous sommes à court depuis un moment déjà.$b$bDites à Vridiel d’ordonner à ses messagers d’accélérer la manœuvre.', 26124),
(134345, 'frFR', 'Comment allez-vous, $n ? Je peux faire quelque chose pour vous ?', '', 26124),
(134346, 'frFR', 'Vous arrivez juste à temps, $n. Nous venions d’épuiser nos dernières réserves et nous craignions que la pénurie ne s’éternise. Merci !', '', 26124),
(134347, 'frFR', 'Arkhaan écoute.', '', 26124),
(134348, 'frFR', 'Ah ! Oh. Oui ?', '', 26124),
(134349, 'frFR', 'Vous voulez parler ?', '', 26124),
(134350, 'frFR', 'Les étrangers, ça parle étrangement.', '', 26124),
(134351, 'frFR', 'Chut… Vous avez entendu ?', '', 26124),
(134352, 'frFR', 'N’écoutez pas les murmures.', '', 26124),
(134353, 'frFR', 'On attend de moi que je vous salue. Bonjour.', '', 26124),
(134354, 'frFR', 'Vous voulez quoi ?', '', 26124),
(134355, 'frFR', 'J’ai ordre de servir.', '', 26124),
(134356, 'frFR', 'Mes protocoles m’imposent de vous saluer.', '', 26124),
(134357, 'frFR', 'Je n’y ai pris aucun plaisir.', '', 26124),
(134358, 'frFR', 'Les règles sont les règles.', '', 26124),
(134359, 'frFR', '', 'J’ai brisé d’innombrables mortels. Quelles sont vos chances de survie, d’après vous ?', 26124),
(134360, 'frFR', '', 'Ma vie pour la Légion !', 26124),
(134361, 'frFR', '', 'Vous… n’échapperez pas… à votre destin…', 26124),
(134362, 'frFR', '', 'Cette souffrance n’est rien…', 26124),
(134363, 'frFR', '', 'Nous ne tolérerons aucune résistance !', 26124),
(134364, 'frFR', '', 'Vous ne comprenez pas ? C’est la seule solution. Laissez-moi vous expliquer !', 26124),
(134365, 'frFR', '', 'Rien ne peut arrêter le maître !', 26124),
(134366, 'frFR', '', 'Un être obstiné… je vois.', 26124),
(134367, 'frFR', '', 'Vous refusez de voir… la vérité !', 26124),
(134368, 'frFR', 'Tremblez face à la véritable puissance de la Légion !', '', 26124),
(134369, 'frFR', 'Votre monde là-haut dans le ciel… est condamné !', '', 26124),
(134370, 'frFR', 'Argus sera votre tombe, à tous.', '', 26124),
(134371, 'frFR', 'La véritable puissance gangrenée coule dans mes veines !', '', 26124),
(134372, 'frFR', 'Vous avez été stupide de venir ici !', '', 26124),
(134373, 'frFR', 'Votre pitoyable résistance s’arrête ici !', '', 26124),
(134374, 'frFR', 'Non… Pas après tous ces sacrifices…', '', 26124),
(134375, 'frFR', 'Impossible ! Pas ici !', '', 26124),
(134376, 'frFR', 'Ma vie pour Argus !', '', 26124),
(134377, 'frFR', 'Non ! Notre… destinée…', '', 26124),
(134378, 'frFR', 'Est-ce que c’était… la vision qu’il a eue ?', '', 26124),
(134379, 'frFR', 'Je l’ai informé de mon intention de quitter Argus et lui ai demandé de chercher ma famille avant de me rejoindre. Au lieu de cela, il est allé retrouver Kil’jaeden.', '', 26124),
(134380, 'frFR', 'La suite, vous la connaissez.', '', 26124),
(134381, 'frFR', 'Vous… misérable…', '', 26124),
(134382, 'frFR', 'Mon peuple ne saura jamais à quel point je l’ai pleuré… quels ont été mes regrets.', '', 26124),
(134383, 'frFR', 'En voyant disparaître Argus à l’horizon, j’ai supplié les Naaru de faire demi-tour.', '', 26124),
(134384, 'frFR', '« Telle n’est pas votre voie », m’avaient-ils dit. Est-ce cela qu’ils avaient en tête ?', '', 26124),
(134385, 'frFR', 'Archimonde méprisait les limitations du cachet. Sans le reste de la couronne, sa puissance était réduite. Et la puissance était tout ce qu’il désirait.', '', 26124),
(134386, 'frFR', 'Ce mépris est ce qui nous a permis de récupérer le cachet. S’il avait su sa valeur à nos yeux, il l’aurait très certainement détruit.', '', 26124),
(134387, 'frFR', 'Je me demande ce qu’il espérait prouver avec ses épreuves. Le cachet lui-même était-il un test ?', '', 26124),
(134388, 'frFR', 'Nous pourrons bientôt débloquer tout le potentiel du Vindicaar. Il ne nous manque que le cimier de la Connaissance pour que la couronne soit à nouveau entière.', '', 26124),
(134389, 'frFR', 'Dépêchez-vous, mes amis. Une présence sombre et redoutable se réveille… et ce n’est pas Talgath.', '', 26124),
(134390, 'frFR', 'Sans valeur. Le cimier seul ne sert à rien.', '', 26124),
(134391, 'frFR', 'Cette relique est obsolète. Jetez-la dans le temple avec le Naaru. Qu’ils y pourrissent ensemble.', '', 26124),
(134392, 'frFR', 'Au moins nous savons où elle se trouve.', '', 26124),
(134393, 'frFR', 'Elle est cachée au siège du Triumvirat, alors. Je ne sens que ténèbres à l’intérieur.', '', 26124),
(134396, 'frFR', 'Nous n’avons pas le temps de célébrer notre victoire contre Talgath. Le chant sombre de L’ura résonne dans mon esprit.', '', 26124),
(134399, 'frFR', 'Vous avez affronté des périls rivalisant avec tout ce que la Légion a pu concevoir. Je vous en prie, faites-moi l’honneur de placer le cimier.', '', 26124),
(134400, 'frFR', 'La couronne est à nouveau complète !', '', 26124),
(134401, 'frFR', 'Maintenant, nous allons nous attaquer directement au Trône ardent. Préparez-vous. Antorus nous attend !', '', 26124),
(134402, 'frFR', 'Faites de beaux rêves.', '', 26124),
(134403, 'frFR', 'À terre !', '', 26124),
(134404, 'frFR', 'Je m’occuperai de vous plus tard.', '', 26124),
(134405, 'frFR', 'Continuez comme ça, si vous le pouvez.', '', 26124),
(134406, 'frFR', 'C’est l’heure du carnage !', '', 26124),
(134407, 'frFR', 'Il va falloir être plus rapide que ça, mortels !', '', 26124),
(134408, 'frFR', 'Pour collecter la prime, pas besoin d’un corps intact. Quelques morceaux suffisent.', '', 26124),
(134409, 'frFR', 'Essayez de ne pas abîmer vos parties identifiables.', '', 26124),
(134411, 'frFR', 'J’ai hâte que nous quittions enfin ces terres brisées. Cela leur permettra peut-être de trouver le repos.', '', 26124),
(134412, 'frFR', 'J’ai besoin d’un type de cristal très spécifique pour maintenir actives les défenses du Vindicaar. Les assemblages qui subsistent ici reposent sur une technologie similaire. Emparez-vous de leurs noyaux. Par tous les moyens.', '', 26124),
(134413, 'frFR', 'Ces assemblages ont durement souffert des outrages du temps, n’est-ce pas ? Il semble que rien ne soit vraiment à l’abri de l’obsolescence.', '', 26124),
(134415, 'frFR', 'Les assemblages activés constitueront d’excellentes diversions. Je vous remercie !', '', 26124),
(134417, 'frFR', 'Voilà qui devrait les occuper. Du moins, pour le moment.', '', 26124),
(134418, 'frFR', '', 'Les créatures extraordinaires qui peuplent ces lieux constituent des prises de choix pour tout bon chasseur, mais l’Ombre-Garde a entrepris de les renforcer encore davantage grâce au Vide. Arrêtez les Éthériens et libérez ces bêtes.', 26124),
(134419, 'frFR', '', 'J’espère que nous parviendrons à les apaiser, malgré tout ce qu’elles ont enduré. Ce fut un beau travail, mais notre combat contre l’Ombre-Garde n’est pas terminé.', 26124),
(134420, 'frFR', 'Mes frères sont aussi travailleurs qu’intelligents. Je crains qu’il ne faille de nouveau nettoyer le site d’incursion. Vous savez quoi faire.', '', 26124),
(134421, 'frFR', 'C’est amusant qu’ils continuent de vous sous-estimer, vous ne trouvez pas ?', '', 26124),
(134424, 'frFR', 'Étrange… les esprits se sont rassemblés pour écouter le discours de Kil’jaeden, mais quelque chose ne va pas. Je perçois une présence démoniaque. Trouvez-la, avant qu’elle déclenche son attaque.', '', 26124),
(134425, 'frFR', 'Une tactique des plus inhabituelles. On ne peut pas laisser la Légion manipuler ces esprits sans défense pour arriver à ses fins.', '', 26124),
(134426, 'frFR', '', 'Cet endroit regorge de ténèbres, lesquelles forment parfois des cristaux de Vide pur. C’est une ressource précieuse pour l’Ombre-Garde. Nous devons nous en emparer avant elle.', 26124),
(134427, 'frFR', '', 'Une arme de moins à leur arsenal. Peut-être parviendrai-je à trouver une utilité à ces cristaux.', 26124),
(134428, 'frFR', 'J’ai apporté une légère modification à l’épreuve précédente. Si vous vous sentez de taille, c’est l’occasion idéale de prouver de nouveau votre ingéniosité.', '', 26124),
(134429, 'frFR', 'Hm. J’étais convaincu que vous échoueriez, cette fois. Mais, puisque le règlement l’exige, je n’ai d’autre choix que reconnaître votre succès. Félicitations.', '', 26124),
(134430, 'frFR', '', 'Les pantharas se nourrissent des esprits du Conservatorium. Apportez-moi des échantillons de leurs écailles. Je pourrais peut-être en extraire de quoi concocter un répulsif.', 26124),
(134431, 'frFR', '', 'Fascinant ! Leurs écailles sont couvertes de particules sensibles au mana. Je suis certaine que cette découverte nous sera utile.', 26124),
(134432, 'frFR', 'Vous êtes en retard pour vos cours de rattrapage. Rendez-vous dans la salle de l’Érudition pour y passer un examen.', '', 26124),
(134433, 'frFR', 'Je ne vous retirerai pas votre diplôme. Pour le moment.', '', 26124),
(134434, 'frFR', '', 'De nombreuses questions demeurent quant aux esprits qui hantent ces lieux. Pourquoi restent-ils ? Pourquoi rejettent-ils notre présence ? Peut-être l’étude de leur essence nous fournira-t-elle des réponses.', 26124),
(134435, 'frFR', '', 'Merci de m’offrir cette occasion d’apprendre de mes prédécesseurs. Vous nous avez fourni une aide précieuse.', 26124),
(134436, 'frFR', 'Mes frères ont entrepris de hâter le déclin de cette zone. Interrompez leurs activités. Ou ne le faites pas. Le Vide finira de toute façon par réclamer son dû.', '', 26124),
(134437, 'frFR', 'Vous connaissez le dicton : chat échaudé…', '', 26124),
(134440, 'frFR', 'Vous ne vous échapperez pas.', '', 26124),
(134441, 'frFR', 'On dirait que je vais devoir faire appel à l’artillerie lourde.', '', 26124),
(134443, 'frFR', '<Voile des échos arcaniques>', '<Voile des échos arcaniques>', 26124),
(134444, 'frFR', '<Balise de téléportation du Vindicaar>', '<Balise de téléportation du Vindicaar>', 26124),
(134445, 'frFR', '<Champion sancteforge>', '<Champion sancteforge>', 26124),
(134446, 'frFR', '<Exossature sancteforge>', '<Exossature sancteforge>', 26124),
(134452, 'frFR', 'Qu’en est-il des autres capitaines ? Je prie pour qu’ils soient également sains et saufs.', '', 26124),
(134454, 'frFR', '', 'Ne vous inquiétez pas, grand exarque. Enaara et Sorvos ont pris position dans notre campement principal. Les autres sont dispersés, mais je suis certaine qu’ils sont en vie.', 26124),
(134455, 'frFR', 'Feu sur ma position !', '', 26124),
(134456, 'frFR', 'Bombardez cette zone !', '', 26124),
(134457, 'frFR', 'Plus vous résistez, plus la prime augmente !', '', 26124),
(134458, 'frFR', 'Le Jugement de la Lumière… C’est magnifique. Il devrait être opérationnel d’ici peu !', '', 26124),
(134459, 'frFR', 'Vous ne vaudrez bientôt plus grand-chose.', '', 26124),
(134461, 'frFR', 'Vous ne vous en sortirez pas vivants !', '', 26124),
(134462, 'frFR', 'Je vais vous couper en deux et encaisser la prime deux fois !', '', 26124),
(134466, 'frFR', '', 'Vos cris résonneront jusqu’à Antorus !', 26124),
(134467, 'frFR', '', 'Contemplez la puissance du Trône ardent !', 26124),
(134468, 'frFR', '', 'Une erreur fatale.', 26124),
(134469, 'frFR', '', 'Vous pensez pouvoir nous vaincre ? Ici ? Ha !', 26124),
(134470, 'frFR', '', 'Je vais vous faire rôtir !', 26124),
(134472, 'frFR', '', 'Antorus vous salue !', 26124),
(134473, 'frFR', '', 'Vous avez l’air tellement vulnérables, à trembler ainsi dans les ténèbres.', 26124),
(134477, 'frFR', 'Vous avez réussi ! Venez, montons à bord du Xénédar et allons secourir Xe’ra !', '', 26124),
(134478, 'frFR', '', 'Goûtez à ma caresse glacée avant d’être complètement gelés.', 26124),
(134479, 'frFR', '', 'Je renaîtrai… encore et encore…', 26124),
(134480, 'frFR', '', 'Je ne suis qu’une… parmi tant d’autres…', 26124),
(134481, 'frFR', '', 'Antorus, je reviens…', 26124),
(134482, 'frFR', '', 'Par le feu d’Argus je renaîtrai.', 26124),
(134483, 'frFR', '', 'Cela ne change rien.', 26124),
(134484, 'frFR', 'Fuyez… tant que vous le pouvez.', 'Fuyez… tant que vous le pouvez.', 26124),
(134485, 'frFR', 'Les érédars… sont tout-puissants…', 'Les érédars… sont tout-puissants…', 26124),
(134486, 'frFR', 'Pourquoi… fait-il si sombre ?', 'Pourquoi… fait-il si sombre ?', 26124),
(134487, 'frFR', 'Argus… s’élèvera…', 'Argus… s’élèvera…', 26124),
(134488, 'frFR', 'Vous n’avez nulle part où aller.', 'Vous n’avez nulle part où aller.', 26124),
(134489, 'frFR', 'Vous… ne vous échapperez… jamais…', 'Vous… ne vous échapperez… jamais…', 26124),
(134491, 'frFR', 'Fuyez… tant que vous le pouvez.', '', 26124),
(134493, 'frFR', 'Les érédars… sont tout-puissants…', '', 26124),
(134494, 'frFR', 'Pourquoi… fait-il si sombre ?', '', 26124),
(134495, 'frFR', 'Argus… s’élèvera…', '', 26124),
(134496, 'frFR', 'Vous n’avez nulle part où aller.', '', 26124),
(134497, 'frFR', 'Vous… ne vous échapperez… jamais…', '', 26124),
(134498, 'frFR', 'Soumettez-vous à Sargeras !', '', 26124),
(134499, 'frFR', 'C’est ça ! Fuyez ! Fuyez !', '', 26124),
(134500, 'frFR', 'Rejoignez les abîmes, espèces de lâches !', '', 26124),
(134501, 'frFR', 'Vous allez payer pour votre stupidité !', '', 26124),
(134502, 'frFR', 'La volonté de Khaz’goroth est corrompue. Il ne peut pas contrôler sa flamme !', '', 26124),
(134503, 'frFR', 'C’est le dernier cadeau que vous refuserez !', '', 26124),
(134504, 'frFR', 'Nul ne s’oppose à Sargeras !', '', 26124),
(134505, 'frFR', 'Vous allez payer pour votre stupidité !', 'Vous allez payer pour votre stupidité !', 26124),
(134506, 'frFR', 'Rejoignez les abîmes, espèces de lâches !', 'Rejoignez les abîmes, espèces de lâches !', 26124),
(134507, 'frFR', 'C’est ça ! Fuyez ! Fuyez !', 'C’est ça ! Fuyez ! Fuyez !', 26124),
(134508, 'frFR', 'Soumettez-vous à Sargeras !', 'Soumettez-vous à Sargeras !', 26124),
(134509, 'frFR', 'Nul ne s’oppose à Sargeras !', 'Nul ne s’oppose à Sargeras !', 26124),
(134510, 'frFR', 'C’est le dernier cadeau que vous refuserez !', 'C’est le dernier cadeau que vous refuserez !', 26124),
(134511, 'frFR', 'Je ne vous laisserai pas me torturer !', '', 26124),
(134512, 'frFR', 'N’aurons-nous donc jamais la paix ?', '', 26124),
(134513, 'frFR', 'Ce lieu appartient aux miens ! Allez-vous-en !', '', 26124),
(134514, 'frFR', 'Vous ne savez rien de ma souffrance !', '', 26124),
(134515, 'frFR', 'Vous n’avez rien à faire ici !', '', 26124),
(134516, 'frFR', 'Que faites-vous ici ?', '', 26124),
(134517, 'frFR', 'Que faites-vous ici ?', 'Que faites-vous ici ?', 26124),
(134518, 'frFR', 'Vous n’avez rien à faire ici !', 'Vous n’avez rien à faire ici !', 26124),
(134519, 'frFR', 'Vous ne savez rien de ma souffrance !', 'Vous ne savez rien de ma souffrance !', 26124),
(134520, 'frFR', 'Ce lieu appartient aux miens ! Allez-vous-en !', 'Ce lieu appartient aux miens ! Allez-vous-en !', 26124),
(134521, 'frFR', 'N’aurons-nous donc jamais la paix ?', 'Nous n’aurons donc jamais la paix ?', 26124),
