(142392, 'frFR', '', 'Archenon poros.', 26124),
(142393, 'frFR', '', 'C’est à nous qu’il revient de forger le destin.', 26124),
(142394, 'frFR', '', 'Ensemble, nous sommes invincibles.', 26124),
(142395, 'frFR', '', 'Nous ne faisons qu’un avec la Lumière.', 26124),
(142396, 'frFR', '', 'Ne baissez jamais votre garde.', 26124),
(142397, 'frFR', '', 'Dioniss aca.', 26124),
(142398, 'frFR', '', 'La Lumière nous guidera sur le chemin de la victoire.', 26124),
(142399, 'frFR', '', 'Nos ennemis n’ont aucune conviction.', 26124),
