(142781, 'frFR', '', 'Si un portail conduisant vers le néant infini s’ouvrait soudainement sous vos pieds et vous engloutissait, ce ne serait que pure coïncidence. Après tout, personne n’est à l’abri d’un accident.', 26124),
(142782, 'frFR', '', 'Je me suis fait transformer par une puissance cosmique qui rend complètement dingue et vous me trouvez « suspecte ». On peut savoir ce qui vous fait penser ça ?', 26124),
(142783, 'frFR', '', 'Que voulez-vous ?', 26124),
(142785, 'frFR', '', 'Je propose des fournitures rares en provenance de régions lointaines.', 26124),
(142786, 'frFR', '', 'Chaque chose vaut le prix qu’on veut bien y mettre.', 26124),
(142787, 'frFR', '', 'J’espère que votre achat vous donnera satisfaction.', 26124),
(142788, 'frFR', '', 'Merci de votre visite.', 26124),
(142789, 'frFR', '', 'Revenez me voir.', 26124),
(142791, 'frFR', 'Revenez me voir.', '', 26124),
(142792, 'frFR', 'Merci de votre visite.', '', 26124),
(142793, 'frFR', 'J’espère que votre achat vous donnera satisfaction.', '', 26124),
(142794, 'frFR', 'Chaque chose vaut le prix qu’on veut bien y mettre.', '', 26124),
(142795, 'frFR', 'Je propose des fournitures rares en provenance de régions lointaines.', '', 26124),
(142796, 'frFR', 'Que voulez-vous ?', '', 26124),
(142797, 'frFR', 'Je me suis fait transformer par une puissance cosmique qui rend complètement dingue et vous me trouvez « suspect ». On peut savoir ce qui vous fait penser ça ?', '', 26124),
(142798, 'frFR', 'Si un portail conduisant vers le néant infini s’ouvrait soudainement sous vos pieds et vous engloutissait, ce ne serait que pure coïncidence. Après tout, personne n’est à l’abri d’un accident.', '', 26124),
(142799, 'frFR', '« Pour le puits de Soleil » ? Allons, il est temps de passer à autre chose.', '', 26124),
(142800, 'frFR', 'Votre insolence me laisse de marbre.', '', 26124),
(142801, 'frFR', 'Les possibilités qu’offre le Vide sont infinies.', '', 26124),
(142803, 'frFR', 'Le pouvoir doit être exercé et non redouté.', '', 26124),
(142804, 'frFR', 'Gardez toujours le contrôle.', '', 26124),
(142805, 'frFR', 'Les murmures ne me contrôlent pas.', '', 26124);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142806, 'frFR', 'C’est à nous qu’il revient de choisir notre destin.', '', 26124),
(142807, 'frFR', 'Les ténèbres recèlent un grand pouvoir.', '', 26124),
(142808, 'frFR', 'Shorel’aran.', '', 26124),
(142809, 'frFR', 'De nouvelles portes se sont ouvertes.', '', 26124),
(142810, 'frFR', 'Salutations.', '', 26124),
(142811, 'frFR', 'L’univers est empli de mystères.', '', 26124),
(142812, 'frFR', 'Rien n’est jamais acquis.', '', 26124),
(142813, 'frFR', 'Nous combattons pour l’avenir.', '', 26124),
(142814, 'frFR', 'Suivez votre propre voie.', '', 26124),
(142815, 'frFR', 'Bal’a dash, malanore.', '', 26124),
(142820, 'frFR', '', 'Bal’a dash, malanore.', 26124),
(142821, 'frFR', '', 'Chacun doit suivre sa propre voie.', 26124),
(142822, 'frFR', '', 'Nous sommes un nouvel avenir.', 26124),
(142823, 'frFR', '', 'Aucune vérité n’est absolue.', 26124),
(142824, 'frFR', '', 'L’univers recèle encore tant de mystères.', 26124),
(142825, 'frFR', '', 'De nouvelles possibilités s’offrent à nous.', 26124),
(142826, 'frFR', '', 'À la différence du passé, l’avenir n’est pas écrit ; il peut être modifié.', 26124),
(142827, 'frFR', '', 'Shorel’aran.', 26124),
(142828, 'frFR', '', 'Les nôtres ne craignent pas les ténèbres.', 26124),
(142829, 'frFR', '', 'Il n’existe jamais qu’une seule vérité.', 26124),
(142830, 'frFR', '', 'Les murmures ne nous contrôlent pas.', 26124),
(142831, 'frFR', '', 'Chaque impulsion doit rester sous contrôle.', 26124),
(142832, 'frFR', '', 'Ne craignez pas le pouvoir. Prenez-le.', 26124),
(142833, 'frFR', '', 'Considérez toutes les possibilités.', 26124),
(142834, 'frFR', '', 'Votre insolence me laisse de marbre.', 26124),
(142835, 'frFR', '', '« Pour le puits de Soleil » ? Allons, il est temps de passer à autre chose.', 26124),
(142836, 'frFR', '', 'Si un portail conduisant vers le néant infini s’ouvrait soudainement sous vos pieds et vous engloutissait, ce ne serait que pure coïncidence. Après tout, personne n’est à l’abri d’un accident.', 26124),
(142837, 'frFR', '', 'Je me suis fait transformer par une puissance cosmique qui rend complètement dingue et vous me trouvez « suspecte ». On peut savoir ce qui vous fait penser ça ?', 26124),
(142838, 'frFR', '', 'Que voulez-vous ?', 26124),
(142839, 'frFR', '', 'Je vends des marchandises provenant de lointains royaumes.', 26124),
(142840, 'frFR', '', 'Tout s’achète, pourvu qu’on y mette le prix.', 26124),
(142841, 'frFR', '', 'En espérant que votre achat vous apporte satisfaction.', 26124),
(142842, 'frFR', '', 'Merci de votre visite.', 26124),
(142843, 'frFR', '', 'N’hésitez pas à revenir.', 26124),
(142844, 'frFR', 'N’hésitez pas à revenir.', '', 26124),
(142845, 'frFR', 'Merci de votre visite.', '', 26124),
(142846, 'frFR', 'En espérant que votre achat vous apporte satisfaction.', '', 26124),
(142847, 'frFR', 'Tout s’achète, pourvu qu’on y mette le prix.', '', 26124),
(142848, 'frFR', 'Je vends des marchandises provenant de lointains royaumes.', '', 26124),
(142849, 'frFR', 'Que voulez-vous ?', '', 26124),
(142850, 'frFR', 'Je me suis fait transformer par une puissance cosmique qui rend complètement dingue et vous me trouvez « suspect ». On peut savoir ce qui vous fait penser ça ?', '', 26124),
(142851, 'frFR', 'Si un portail conduisant vers le néant infini s’ouvrait soudainement sous vos pieds et vous engloutissait, ce ne serait que pure coïncidence. Après tout, personne n’est à l’abri d’un accident.', '', 26124),
(142852, 'frFR', '« Pour le puits de Soleil » ? Allons, il est temps de passer à autre chose.', '', 26124),
(142853, 'frFR', 'Votre insolence me laisse de marbre.', '', 26124),
(142854, 'frFR', 'Considérez toutes les possibilités.', '', 26124),
(142855, 'frFR', 'Ne craignez pas le pouvoir. Prenez-le.', '', 26124),
(142856, 'frFR', 'Chaque impulsion doit rester sous contrôle.', '', 26124),
(142857, 'frFR', 'Les murmures ne nous contrôlent pas.', '', 26124),
(142858, 'frFR', 'Il n’existe jamais qu’une seule vérité.', '', 26124),
(142859, 'frFR', 'Les nôtres ne craignent pas les ténèbres.', '', 26124),
(142860, 'frFR', 'Shorel’aran.', '', 26124),
(142861, 'frFR', 'À la différence du passé, l’avenir n’est pas écrit ; il peut être modifié.', '', 26124),
(142862, 'frFR', 'De nouvelles possibilités s’offrent à nous.', '', 26124),
(142863, 'frFR', 'L’univers recèle encore tant de mystères.', '', 26124),
(142864, 'frFR', 'Aucune vérité n’est absolue.', '', 26124),
(142865, 'frFR', 'Nous sommes un nouvel avenir.', '', 26124),
(142866, 'frFR', 'Chacun doit suivre sa propre voie.', '', 26124),
(142867, 'frFR', 'Bal’a dash, malanore.', '', 26124),
(142872, 'frFR', 'Une faille menace de s’ouvrir. Si cela devait se produire, nous pourrions perdre le Puits de soleil.', '', 26124),
(142873, 'frFR', '', 'Je peux refermer la faille, mais il me faut de l’aide.', 26124),
(142874, 'frFR', '', 'Dites-nous quoi faire et nous vous prêterons main-forte.', 26124),
(142875, 'frFR', 'Le portail est ouvert. Oui… cela devrait satisfaire nos besoins.', '', 26124),
(142876, 'frFR', '', 'Maintenant ! Concentrez votre puissance avec moi !', 26124),
(142877, 'frFR', 'Vous ne faites que retarder l’inévitable ! J’obtiendrai ce que je désire.', '', 26124),
(142878, 'frFR', 'Le Puits de soleil est en sécurité. Votre aide nous a été très précieuse, Thalyssra. Tout comme la vôtre, héraut.', '', 26124),
(142879, 'frFR', 'Gardes ! Saisissez-vous de cette saboteuse !', '', 26124),
(142880, 'frFR', '', 'Je ne permettrai pas qu’on me fasse prisonnière sur mes propres terres.', 26124),
(142881, 'frFR', 'Assez ! Je vous somme de partir, Alleria. Accident ou non, votre présence constitue une menace pour Quel’Thalas. Retournez à Hurlevent. Vous n’êtes plus la bienvenue à Lune-d’Argent.', '', 26124),
(142882, 'frFR', '', 'Comme vous le voudrez, seigneur régent. Pour le moment…', 26124),
(142883, 'frFR', 'Je regrette que vous ayez dû assister à cet échange, Thalyssra. Je n’avais pas prévu que votre visite se déroule de la sorte.', '', 26124),
(142884, 'frFR', '', 'Bien au contraire. Cette altercation me montre à quel point vous êtes dévoué à votre peuple. La Horde vous a permis de rester fidèle à vos valeurs, ce qui est très important pour nous.', 26124),
(142885, 'frFR', '', 'Nos alliés nous rendent plus forts… mais nous n’avons pas oublié qui nous sommes.', 26124),
(142886, 'frFR', '', 'Suramar sera toujours notre foyer. Mais certains, parmi les miens, aimeraient explorer le monde et regagner leur place en Azeroth. Pour cela, nous avons besoin d’alliés.', 26124),
(142887, 'frFR', 'La Horde vous les offre, Première arcaniste. Rejoignez-nous. Les portes de Lune-d’Argent vous sont grand ouvertes.', '', 26124),
(142888, 'frFR', '', 'Au nom des Sacrenuit, j’accepte votre proposition. À compter de ce jour, Suramar se battra pour la Horde.', 26124),
(142889, 'frFR', 'Parfait ! Dame Liadrin, veuillez retourner à Orgrimmar et annoncer l’heureuse nouvelle à notre chef de guerre.', '', 26124),
(142890, 'frFR', '', 'Avec plaisir, seigneur régent. Je vous retrouverai à Lune-d’Argent, camarade.', 26124),
(142910, 'frFR', '', 'Alleria se crispe.', 26124),
(142986, 'frFR', 'Bonne chance, $p. En ce qui me concerne, je m’en vais mettre mes talents à l’épreuve à Orneval. Pour la Horde !', '', 26124),
(142999, 'frFR', 'Il est bon de voir un visage familier en ces heures sombres.', '', 26124),
(143000, 'frFR', 'Depuis notre retour d’Argus, les cris d’Azeroth m’accablent. Sa souffrance est immense…', '', 26124),
(143001, 'frFR', 'Je ne sais pas comment y remédier. Je crois que personne ne le sait. Mais nous devons persévérer.', '', 26124),
(143002, 'frFR', 'L’heure est grave, $p. Si nous ne trouvons pas un moyen de soigner Azeroth… plus rien n’aura d’importance.', '', 26124),
(143003, 'frFR', 'Champions, vous avez combattu ensemble et libéré Azeroth de la Légion.', '', 26124),
(143004, 'frFR', 'Les tensions s’intensifient, oui… mais je vous demande de mettre vos différends de côté une fois encore.', '', 26124),
(143005, 'frFR', 'Rejoignez Silithus… tant qu’il nous reste un monde à défendre !', '', 26124),
(143006, 'frFR', 'L’épée de Sargeras empoisonne l’essence vitale de notre planète.', '', 26124),
(143007, 'frFR', 'Seules les armes que vous portez sont capables de contenir un tel pouvoir.', '', 26124),
(143008, 'frFR', 'Unissez-vous et brandissez-les… Extirpez la corruption de la lame du Titan noir !', '', 26124),
(143009, 'frFR', 'Tous ensemble, champions ! Pour Azeroth !', '', 26124),
(143010, 'frFR', 'Vous avez réussi ! L’épée de Sargeras est neutralisée. Azeroth est loin d’être guérie… mais nous avons gagné un temps précieux.', '', 26124),
(143011, 'frFR', 'Cette énergie qui parcourt votre arme… je n’avais jamais vu rien de tel ! Mais souvenez-vous-en, le pouvoir a toujours un coût.', '', 26124),
(143012, 'frFR', 'De nombreux combats vous attendent, mais quoi qu’il arrive… n’oubliez jamais votre devoir envers Azeroth !', '', 26124),
(143013, 'frFR', 'Tu es nerveuse… Tu le caches bien… mais je te connais.', '', 26124),
(143014, 'frFR', '', 'Mieux que quiconque, mon amour.', 26124),
(143015, 'frFR', 'Rien ne t’oblige à partir. À aller la voir.', '', 26124),
(143016, 'frFR', 'Chacune de vous suit son propre chemin. Si la Lumière veut qu’ils se croisent, il en sera ainsi. Inutile de forcer le destin.', '', 26124),
(143017, 'frFR', '', 'Il est temps, Turalyon. Je dois revoir la terre qui m’a vue naître… et entendre de la bouche de Sylvanas les raisons qui l’ont conduite à endosser le rôle de chef de guerre.', 26124),
(143018, 'frFR', 'Ces statues à notre mémoire sont troublantes.', '', 26124),
(143019, 'frFR', '', 'C’est vrai. Parfois, j’ai l’impression d’avoir déjà perdu deux fois la vie. La première, quand nous avons été portés disparus sur Draenor. La deuxième, quand les ténèbres du Naaru corrompu m’ont envahie.', 26124),
(143020, 'frFR', '', 'Peut-être la mort est-elle le véritable héritage des Coursevent.', 26124),
(143078, 'frFR', 'Come, friend $p.', '', 26124),
(143124, 'frFR', '', 'Chef de guerre Sylvanas Coursevent, je vous présente la Première arcaniste Thalyssra de Suramar.', 26124),
(143144, 'frFR', '', 'C’est un honneur, chef de guerre. J’ai combattu aux côtés de dame Liadrin et du seigneur régent. Leur courage fait honneur à votre Horde.', 26124),
(143145, 'frFR', '', 'En effet, Première arcaniste.', 26124),
(143146, 'frFR', '', 'La Horde incarne une puissance irrépressible, une détermination sans faille et une identité forte. Des traits que nous, Shal’dorei, tenons en haute estime.', 26124),
(143147, 'frFR', '', 'L’heure est venue pour les Sacrenuit de trouver des alliés parmi les royaumes d’Azeroth. Si vous acceptez notre allégeance, nous serons honorés de rejoindre vos rangs.', 26124),
(143148, 'frFR', '', 'Pendant des millénaires, Suramar a combattu seule. Vous embrassez aujourd’hui une cause plus grande. J’accepte votre serment d’allégeance, Thalyssra.', 26124),
(143149, 'frFR', '', 'Suramar combattra pour la Horde !', 26124),
(143150, 'frFR', '', 'Pour la Horde !', 26124),
(143151, 'frFR', '', 'Pour la Horde !', 26124),
(143172, 'frFR', '', 'Haut roi Wrynn, nous avons retrouvé les exilés sin’dorei. Tout comme moi, le Vide les a changés, mais leur cœur et leur esprit restent intacts.', 26124),
(143173, 'frFR', '', 'Je serai leur guide et leur apprendrai à dominer les murmures des ténèbres. En retour, ils combattront les ennemis de l’Alliance.', 26124),
(143175, 'frFR', 'Les Elfes du Vide devront peut-être gagner la confiance de certains des nôtres. Toutefois, tant qu’ils observent nos préceptes, ils sont les bienvenus dans l’Alliance.', '', 26124),
(143176, 'frFR', 'Vous nous avez rendu un fier service aujourd’hui. Dame Coursevent, $p, je vous remercie.', '', 26124),
(143178, 'frFR', '', 'C’est un honneur de vous servir une fois encore, haut roi. Pour l’Alliance !', 26124),
(143179, 'frFR', 'Pour l’Alliance !', '', 26124),
(143203, 'frFR', '', 'Certains essaieront de vous convaincre que seule la Lumière peut nous apporter le salut et venir à bout des ennemis d’Azeroth.', 26124),
(143204, 'frFR', '', 'Mais nous envisageons des alternatives, explorons d’autres voies… Nous voyons les infinies possibilités qui s’offrent à nous.', 26124),
(143205, 'frFR', 'Certains douteront de vous. D’autres remettront en question votre détermination, votre capacité à manier un pouvoir qui a causé la perte des plus faibles.', '', 26124),
(143206, 'frFR', '', 'Servez-vous des leçons que je vous ai enseignées pour garder le contrôle. Devenez une arme de l’Alliance… même si vous devez marcher sur le fil du rasoir.', 26124),
(143228, 'frFR', '', 'Au cours de vos périples sur Azeroth, vous avez appris à maîtriser ces forces qui ne vous laissent aucun répit.', 26124),
(143234, 'frFR', '', 'Vous êtes désormais une arme redoutable au service de l’Alliance, $p. Regagnez la faille du Vide et nous célébrerons votre réussite comme il se doit.', 26124),
(143236, 'frFR', '', 'Beaucoup doutaient que les Ren’dorei soient capables de contrôler les pouvoirs du Vide sans y succomber. Vous êtes la preuve que nos détracteurs avaient tort.', 26124),
(143241, 'frFR', '', 'Que cette armure vous rappelle ce que vous avez accompli, $p. Acceptez-la avec toute ma gratitude.', 26124),
(143270, 'frFR', '', 'Vous faites partie des premiers Shal’dorei à avoir exploré les étendues d’Azeroth. Il est temps pour vous de rentrer à la maison.', 26124),
(143271, 'frFR', '', 'Revenez à Suramar. Grâce à vous, notre peuple a retrouvé sa place dans ce monde, et nous tenons à vous remercier.', 26124),
(143273, 'frFR', '', 'Vous avez prouvé à la Horde et à tous les peuples d’Azeroth que les Sacrenuit disposent de la volonté et du courage nécessaires pour défendre notre monde.', 26124),
(143275, 'frFR', '', 'Je suis fière de vous remettre les traditionnels atours de Suramar. Portez-les en l’honneur de notre passé… et de l’avenir que nous allons façonner avec nos alliés.', 26124),
(143276, 'frFR', '', 'Quand notre cité a connu ses heures les plus sombres, les héros d’Azeroth ont repoussé la Légion à nos côtés. Certains à contrecœur…', 26124),
(143277, 'frFR', '', 'Mais les Sin’dorei, les Elfes de sang, ont fait preuve de respect et de compréhension à notre égard. Ils nous ont donné la preuve que nos valeurs étaient partagées par d’autres en Azeroth.', 26124),
(143284, 'frFR', '', 'Que les étoiles vous guident, $p. Je pense rejoindre les contreforts de Hautebrande. J’ai eu vent d’affaires étranges dans la région.', 26124),
(143287, 'frFR', 'Nous avons beaucoup de points communs avec les Taurens de Haut-Roc. Ils feront d’excellents alliés le moment venu.', '', 26124),
(143288, 'frFR', '', 'C’est maintenant à nous de montrer que nous pouvons apporter force et honneur à la Horde.', 26124),
(143289, 'frFR', 'Que savez-vous des Taurens de Haut-Roc ?', 'Que savez-vous des Taurens de Haut-Roc ?', 26124),
(143290, 'frFR', '', 'Je suis ravie de vous voir, $n. Nous devons convaincre le chef de guerre de rallier les Sacrenuit à notre cause.', 26124),
(143291, 'frFR', 'Que savez-vous des Sacrenuit ?', 'Que savez-vous des Sacrenuit ?', 26124),
(143292, 'frFR', '', 'Quand vous sillonnerez les routes d’Azeroth, racontez l’histoire des fiers Sacrenuit… Faites savoir que nous sommes enfin sortis de notre isolement.', 26124),
(143293, 'frFR', '', 'Rendez-vous à Orgrimmar. Rejoignez nos alliés et construisez un nouvel avenir à leurs côtés.', 26124),
(143328, 'frFR', '', 'Jusqu’alors, je ne connaissais Hurlevent que dans les histoires. Je vais enfin pouvoir arpenter les rues et découvrir les merveilles qu’elles recèlent. Que les ténèbres vous guident, $n.', 26124),
(143468, 'frFR', '', 'Salutations, dame Liadrin, $p. C’est un plaisir de vous revoir et de vous accueillir à Suramar en des circonstances plus favorables.', 26124),
(143469, 'frFR', '', 'Je suis heureuse de voir votre cité enfin libre, Première arcaniste.', 26124),
(143470, 'frFR', '', 'Nous avons d’ailleurs une dette envers vous. Vous avez joué un rôle décisif.', 26124),
(143471, 'frFR', '', 'Ce fut pour la Horde un honneur de combattre la Légion ardente à vos côtés, madame.', 26124),
(143472, 'frFR', '', 'Je dois avouer avoir émis des doutes au sujet de la Horde, convaincue que nos intérêts divergeaient.', 26124),
(143473, 'frFR', '', 'Je pensais que nos frères de Kalimdor seraient des alliés naturels. Mais leur arrogance et leur méfiance m’ont rapidement détrompée.', 26124),
(143474, 'frFR', '', 'Arcaniste Thalyssra, je me rappelle la conduite de votre ordre lors de la guerre des Anciens. Qui nous dit que vous ne deviendrez pas une nouvelle Élisande, ou une nouvelle Azshara ?', 26124),
(143475, 'frFR', '', 'Nous ne comptons pas devenir esclaves du Puits de la nuit. Nous voulons seulement chasser la Légion de Suramar et mettre fin à la tyrannie d’Élisande.', 26124),
(143476, 'frFR', '', 'Les Kaldorei combattront pour vaincre la Légion et détruire le Puits de la nuit. Ensuite… nous verrons où nous guidera la sagesse d’Élune.', 26124),
(143477, 'frFR', '', 'Il semblerait que la « sagesse d’Élune » ait altéré le lien qui nous unissait autrefois. Qu’il en soit ainsi.', 26124),
(143478, 'frFR', '', 'Tyrande et son peuple plein d’orgueil méprisent les Sin’dorei. Ils oublient qu’ils dormaient dans des tanières et se cachaient dans les arbres à l’époque où les miens se battaient déjà pour sauver le monde.', 26124),
(143479, 'frFR', '', 'L’Alliance est trop fermée… trop hermétique. Et mon peuple refuse d’endurer davantage d’inertie.', 26124),
(143480, 'frFR', '', 'C’est pourquoi je suis ravie de votre invitation à Lune-d’Argent. J’aimerais savoir s’il y a une place pour les Sacrenuit dans votre Horde.', 26124),
(143481, 'frFR', '', 'Je suis persuadée que le seigneur régent sera ravi de répondre à cette question. Êtes-vous prête à partir ?', 26124),
(143482, 'frFR', '', 'Ce serait un honneur, dame Liadrin. Oculeth dispose des coordonnées de votre capitale. Je m’en vais chercher Silgryn et Valtrois, puis je vous retrouverai à Lune-d’Argent.', 26124),
(143485, 'frFR', 'Vaisseau de la Horde en approche ! J’aurais dû me douter que ces ordures nous suivraient jusqu’ici. Tous à vos postes de combat !', '', 26124),
(143488, 'frFR', 'Héros ! On vous envoie du ravitaillement. Ne laissez pas la Horde mettre ses sales pattes dessus !', '', 26124),
(143493, 'frFR', 'Ravitaillement en approche ! Récupérez-le, champions !', '', 26124),
(143494, 'frFR', 'Excellent travail, champions ! Le roi Wrynn sera ravi de cette victoire. Pour l’Alliance !', '', 26124),
(143495, 'frFR', 'Bon sang ! Cette fois, la Horde a pris le dessus. Mais je jure sur le Repos du lion que la victoire sera nôtre !', '', 26124),
(143496, 'frFR', 'Vous m’avez l’air robustes. Hmm… On aurait bien besoin d’un voleur ou deux, mais… Non, vous ferez l’affaire !', '', 26124),
(143497, 'frFR', 'Ouvrez le feu et abattez ces soigneurs !', '', 26124),
(143498, 'frFR', 'Ces vauriens de la Horde se croient malins. Donnez-leur une bonne leçon !', '', 26124),
(143499, 'frFR', 'Battez-vous pour le roi ! Battez-vous pour l’Alliance !', '', 26124),
(143500, 'frFR', 'Renvoyez-les chez eux ! Cette île est à nous !', '', 26124),
(143501, 'frFR', 'Champions de la Horde ! Nous avons trouvé des gisements d’azérite sur une île perdue au large de la côte de Féralas. Emparez-vous-en. Ordre de la Dame noire !', '', 26124),
(143503, 'frFR', 'Vaisseau de l’Alliance en approche ! Ces rats sont sur nos talons. Ils l’auront cherché… Rejoignez vos postes de combat !', '', 26124),
(143504, 'frFR', 'Laissez-moi vous regarder. Arg… pitoyable ! Pourquoi n’avez-vous pas de forestiers-sombres ? Tant pis, il faudra se contenter de vous.', '', 26124),
(143506, 'frFR', 'Ravitaillement en approche. Il vaudrait mieux pour vous que l’Alliance ne le récupère pas !', '', 26124),
(143507, 'frFR', 'Récupérez ce ravitaillement si vous en avez besoin. Mais ne perdez pas de vue l’objectif de la reine banshee !', '', 26124),
(143509, 'frFR', 'Ha ! Voilà de l’azérite que l’Alliance n’aura pas ! Bien joué !', '', 26124),
(143513, 'frFR', 'Tirez ! Je ne veux plus voir un seul de ces lâches en vie !', '', 26124),
(143514, 'frFR', 'L’Alliance appelle ça des soldats ? Lamentable ! Ils sont à peine capables de donner un coup d’épée !', '', 26124),
(143515, 'frFR', 'Abattez-les ! Ne décevez pas notre chef de guerre !', '', 26124),
(143516, 'frFR', 'Ça sent… le Worgen, non ? Impossible d’en être certain avec la puanteur de ces hypocrites moralisateurs de l’Alliance.', '', 26124),
(143517, 'frFR', 'Ça n’avait rien d’une victoire élégante, mais au moins vous avez remis ces chiens de l’Alliance à leur place. Pour la Horde !', '', 26124),
(143518, 'frFR', 'Vous avez… perdu ? Contre eux ? Vous devriez avoir honte ! Allez tout de suite à Fossoyeuse pour une remise à niveau, puisqu’il vous manque même les bases !', '', 26124),
(143583, 'frFR', 'Bienvenue, $p. Je suis le roi Anduin Wrynn. Comme vous venez de rejoindre l’Alliance, je tenais à vous saluer personnellement.', '', 26124),
(143584, 'frFR', 'Les Sancteforge sont certes de nouveaux alliés, mais je connais bien les Draeneï. Je suis certain que vous incarnerez les valeurs de dévouement et de courage de l’armée de la Lumière.', '', 26124),
(143585, 'frFR', 'Notre monde vit des heures sombres. Dans les jours qui s’annoncent, vous devrez faire face à bien des défis… affronter nombre d’ennemis. Mais sachez que face aux ténèbres, l’Alliance sera toujours à vos côtés.', '', 26124),
(143586, 'frFR', 'Je suivrai votre parcours avec intérêt. Quelque chose me dit que nous nous reverrons bientôt.', '', 26124),
(143587, 'frFR', 'Bon voyage, $p. Bien que vous marchiez à travers les ombres, vous êtes une flamme d’espoir pour nous tous.', '', 26124),
(143589, 'frFR', 'Les Elfes du Vide sont certes de récents alliés, mais Alleria Coursevent est l’une de nos plus grandes héroïnes. Sous sa tutelle, les pouvoirs que vous détenez serviront notre cause.', '', 26124),
(143590, 'frFR', 'Bon voyage, $p. Que la Lumière soit toujours avec vous.', '', 26124),
(143591, 'frFR', '', 'Ah, $p, vous voilà enfin. Il paraît que vous avez du potentiel. Espérons que les rumeurs disent vrai.', 26124),
(143592, 'frFR', '', 'Les Taurens de Haut-Roc sont reconnus pour leur force et leur courage. De telles qualités nous seront indispensables prochainement.', 26124),
(143593, 'frFR', '', 'La Horde compte de nombreux adversaires. Certains nous appellent des ennemis… d’autres des parias. Mais nous puisons notre force dans l’union… et dans l’adversité.', 26124),
(143594, 'frFR', '', 'Sachez que je surveillerai attentivement vos progrès. En tant que chef de guerre, j’attends beaucoup de vous… et je récompense toujours mes loyaux serviteurs.', 26124),
(143595, 'frFR', '', 'Trêve de civilités. Vous devez à présent faire vos preuves. Où que vos aventures vous mènent, n’oubliez pas que vous combattez… pour la Horde !', 26124),
(143596, 'frFR', '', 'Les Sacrenuit sont sages et puissants. Votre savoir incommensurable sera pour nous un grand atout.', 26124),
(143598, 'frFR', '$p, le haut roi Wrynn souhaite que je m’entretienne avec vous à Hurlevent.', '', 26124),
(143599, 'frFR', 'Nous avons mis la main sur des informations… sensibles, que Sa Majesté juge important de partager avec vous.', '', 26124),
(143600, 'frFR', 'Retrouvez-moi au Repos du lion. Inutile de préciser que les détails de cette rencontre restent entre nous.', '', 26124),
(143601, 'frFR', '$p ! La Dame noire exige que nous nous entretenions à Orgrimmar.', '', 26124),
(143602, 'frFR', 'Des informations cruciales pour les intérêts de la Horde nous sont parvenues. Il est essentiel que nous gardions une longueur d’avance sur nos rivaux.', '', 26124),
(143603, 'frFR', 'Retrouvez-moi à l’extérieur du fort Grommash. Mais pas un mot de tout ça… ou les conséquences seront immédiates et lourdes.', '', 26124),
(143604, 'frFR', 'Vous avez vu la dévastation de Silithus de vos propres yeux, $p. Vous connaissez les enjeux.', '', 26124),
(143605, 'frFR', 'La Horde ne reculera devant rien pour accaparer le sang d’Azeroth. Mais je crains que la guerre contre la Légion ait trop affaibli nos rangs pour que nous puissions parer leurs attaques.', '', 26124),
(143606, 'frFR', 'Il est temps pour l’Alliance de rallier de nouveaux membres à sa cause. Nous avons établi une ambassade à Hurlevent pour conduire ces efforts. Retrouvez-moi là-bas.', '', 26124),
(143607, 'frFR', '', 'Vous avez été témoin de nos opérations en Silithus, $p. Et comme vous avez pu le constater, l’Alliance se démène pour saper nos efforts.', 26124),
(143608, 'frFR', '', 'L’altruisme dont a fait preuve le commandement de la Horde pendant la guerre contre la Légion a affaibli nos rangs. Nos ennemis se réjouissent à l’idée de voler ce qui nous appartient. Nous ne les laisserons pas faire.', 26124),
(143609, 'frFR', '', 'J’ai autorisé la construction d’une ambassade à Orgrimmar. Grâce à elle, nous gagnerons d’autres appuis à notre cause. Rejoignez-moi là-bas immédiatement.', 26124),
(143610, 'frFR', 'Mon arrogance a bien failli causer notre perte. J’ai joué avec des pouvoirs qui me dépassaient. Alleria, si vous acceptez de nous entraîner, nous rallierons votre cause.', '', 26124),
(143611, 'frFR', '', 'Je ressens les pouvoirs dont vous disposez. Ils sont… considérables. Vous seriez des alliés de poids pour l’Alliance.', 26124),
(143612, 'frFR', 'Il y a longtemps que Lune-d’Argent nous a tourné le dos. Nous avons changé… et devons suivre une nouvelle voie. À partir d’aujourd’hui, l’Alliance peut compter sur notre loyauté.', '', 26124),
(143613, 'frFR', '', 'En retour, je jure de vous aider à surmonter les épreuves qui vous attendent. Nous devons informer le haut roi Wrynn. Je reviendrai ensuite me charger de votre entraînement.', 26124),
(143614, 'frFR', 'Nous adapter à notre nouvelle forme demandera un certain temps. Nous attendrons votre retour avec impatience, dame Coursevent. Quant à vous, $p… merci infiniment.', '', 26124),
(143615, 'frFR', 'Ensemble, nous leur prouverons qu’ils ont tort.', '', 26124),
(143616, 'frFR', '', 'Ces bois ont fait le bonheur des trois sœurs que nous étions. Les voir de la sorte… emplit mon cœur de tristesse.', 26124),
(143617, 'frFR', '', '<Landing from jump: Total 3>', 26124),
(143620, 'frFR', '<Landing from jump: Total 3>', '', 26124),
(143621, 'frFR', '<Distressed cry: Total 3>', '', 26124),
(143622, 'frFR', '', '<Landing from jump: Total 3>', 26124),
(143623, 'frFR', '<Landing from jump: Total 3>', '', 26124),
(143624, 'frFR', 'Nos expériences se déroulent sans accroc. Je suis persuadé que nous sommes sur le point de faire une découverte magistrale… malgré les protestations de Rommath.', '', 26124),
(143625, 'frFR', 'Le grand magistère Rommath doit comprendre que ce pouvoir est primordial pour la défense de Lune-d’Argent. Plus jamais les Sin’dorei ne tomberont aux griffes de l’ennemi !', '', 26124),
(143626, 'frFR', 'Malheureusement, nos recherches ont débouché sur une impasse. Le savoir que renferme le domaine d’Andilien devrait toutefois nous permettre de rebondir.', '', 26124),
(143627, 'frFR', '', '<Landing from jump: Total 3>', 26124),
(143628, 'frFR', '', 'On dirait que nous avons trouvé des notes.', 26124),
(143629, 'frFR', '<Landing from jump: Total 3>', '', 26124),
(143630, 'frFR', 'Nous ne sommes pas les premiers à avoir tenté de maîtriser le Vide. J’ai trouvé des carnets qui appartenaient à un individu dont le nom même est maudit… Dar’Khan Drathir.', '', 26124),
(143631, 'frFR', 'C’est la trahison de Dar’Khan qui a permis à Arthas de corrompre le puits de Soleil… et qui a conduit notre royaume à la ruine. Pour la première fois, je comprends pourquoi Rommath s’oppose à nos recherches.', '', 26124),
(143632, 'frFR', 'Quoi qu’il en soit, je reste convaincu que nous pouvons faire bon usage de ce savoir. Dar’Khan a principalement conduit ses recherches à la flèche d’Aubétoile. C’est là que nous devons aller.', '', 26124),
(143633, 'frFR', '', 'Venez. Nous devons nous rendre à la flèche d’Aubétoile.', 26124),
(143634, 'frFR', '<Landing from jump: Total 3>', '', 26124),
(143635, 'frFR', 'La quête de puissance de Dar’Khan l’a conduit à rechercher les fragments d’un monde ancien à la lisière même du Vide.', '', 26124),
(143636, 'frFR', 'D’après ses notes, ce lieu se trouvait au cœur d’une faille déchirant la trame de la réalité. Il ne l’a jamais trouvé… mais moi j’ai réussi ! La voie s’ouvrira bientôt à nous !', '', 26124),
(143637, 'frFR', 'Dar’Khan pensait qu’il y trouverait un objet ancien d’une puissance indescriptible. Peut-être s’agit-il de l’outil qui nous permettra d’avoir le contrôle face aux ténèbres.', '', 26124),
(143638, 'frFR', '', '<Landing from jump: Total 3>', 26124),
(143639, 'frFR', '', 'Si j’en crois ces notes, je devrais pouvoir rouvrir le passage vers le monde que mentionnait Dar’Khan… Voyons voir.', 26124),
(143640, 'frFR', '', 'Là-bas. Ce doit être Umbric.', 26124),
(143641, 'frFR', '', 'Magistère Umbric ! Je suis Alleria Coursevent.', 26124),
(143642, 'frFR', 'Alleria Coursevent ? C’est… C’est un honneur inespéré !', '', 26124),
(143643, 'frFR', 'Les nouvelles d’Argus nous sont parvenues jusqu’ici. Et comme vous pouvez l’imaginer, votre échange avec le Naaru corrompu nous intéresse au plus haut point.', '', 26124),
(143644, 'frFR', '', 'Parlons de cela une autre fois. Nous vous cherchions. Nous avons eu vent de votre exil de Lune-d’Argent et pensons que nous partageons certaines idées.', 26124),
(143645, 'frFR', 'En effet ! Tout comme vous, nous sommes convaincus que le Vide peut être utilisé pour défendre la vie au lieu de la dévorer. Nous avons fait d’immenses progrès, dame Coursevent, mais de nombreux mystères persistent.', '', 26124),
(143646, 'frFR', 'Prenez ce cube, par exemple. Il s’agit d’un ancien dispositif qui existait avant même que la vie n’apparaisse sur Azeroth. Mais il est verrouillé et nous ne parvenons pas à l’ouvrir.', '', 26124),
(143647, 'frFR', '', 'Prenez garde, Umbric. Les réponses à de tels mystères ont bien souvent un prix.', 26124),
(143662, 'frFR', 'Je vous salue au nom de Lune-d’Argent.', '', 26124),
(143663, 'frFR', 'Bal’a dash, malanore.', '', 26124),
(143664, 'frFR', 'C’est un honneur pour moi que d’être seigneur régent.', '', 26124),
(143665, 'frFR', 'Nous avons accompli de nombreux sacrifices.', '', 26124),
(143666, 'frFR', 'La reconstruction se poursuit.', '', 26124),
(143667, 'frFR', 'Le soleil éternel nous guide toujours.', '', 26124),
(143668, 'frFR', 'La beauté des Chants éternels demeure.', '', 26124),
(143669, 'frFR', 'Lune-d’Argent retrouvera sa prospérité d’antan.', '', 26124),
(143670, 'frFR', 'La lumière du Puits de soleil vous bénisse.', '', 26124),
(143671, 'frFR', 'Tout ce que je fais, je le fais pour Quel’Thalas.', '', 26124),
(143672, 'frFR', 'La Horde nous donne la force.', '', 26124),
(143673, 'frFR', 'Al diel shala.', '', 26124),
(143674, 'frFR', 'Notre nation est en plein essor.', '', 26124),
(143675, 'frFR', 'Plus jamais un roi ne régnera sur Lune-d’Argent.', '', 26124),
(143676, 'frFR', 'Si je prends autant soin de mes cheveux, c’est parce que je le vaux bien !', '', 26124),
(143677, 'frFR', 'Queen\'s champion or no, I can out-shoot Nathanos any day of the week.', '', 26124),
(143678, 'frFR', 'Working for Sylvanas has its... challenges. Being dead has made her even bossier. But, uh... do not tell her I said that.', '', 26124),
(143679, 'frFR', 'Mon cache-œil n’a jamais changé de côté ! Franchement… comme si ce genre d’erreur pouvait se produire !', '', 26124),
(143680, 'frFR', 'Salutations.', '', 26124),
(143681, 'frFR', 'Bal’a dash, malanore.', '', 26124),
(143682, 'frFR', 'Les ténèbres sont à notre service.', '', 26124),
(143683, 'frFR', 'Nous ne craignons pas le pouvoir.', '', 26124),
(143684, 'frFR', 'Toutes les voies sont possibles.', '', 26124),
(143685, 'frFR', 'Venez l’esprit ouvert.', '', 26124),
(143686, 'frFR', 'J’ai beaucoup à vous enseigner.', '', 26124),
(143687, 'frFR', 'Les Ren’dorei prouveront leur valeur.', '', 26124),
(143688, 'frFR', 'La Lumière n’est pas la seule solution.', '', 26124),
(143689, 'frFR', 'Nous servons l’Alliance.', '', 26124),
(143690, 'frFR', 'Les ténèbres veillent sur vous.', '', 26124),
(143691, 'frFR', 'Envisagez toutes les possibilités.', '', 26124),
(143692, 'frFR', 'Ne laissez pas les murmures prendre le dessus.', '', 26124),
(143693, 'frFR', 'Maîtrise et concentration.', '', 26124),
(143694, 'frFR', 'Moi, un Haut-Elfe ? Mais qui aurait donc envie d’être un Haut-Elfe, alors qu’on peut avoir l’air sombre et tourmenté ?', '', 26124),
(143695, 'frFR', 'Du violet, encore du violet… Je commence à en avoir plein le dos, littéralement !', '', 26124),
(143696, 'frFR', 'Je peux vous pardonner de ne pas aimer les Elfes. Après tout, la moitié de notre peuple déteste cordialement l’autre.', '', 26124),
(143697, 'frFR', 'Alleria et Turalyon ? Aucune chance que ça dure. Non pas que je leur souhaite malheur, mais… Bref. Et si on changeait de sujet ?', '', 26124),
(143699, 'frFR', 'Nous avons établi un campement de fortune en Silithus. Allez voir nos agents sur place… et faites attention à la Horde.', '', 26124),
(143700, 'frFR', 'Gallywix est actif en Silithus. Allez-y immédiatement. Et si des rats de l’Alliance rôdent dans les parages, vous savez quoi faire.', '', 26124),
(143712, 'frFR', '', 'Enfin, la Horde et l’Alliance arrêtent de nager entre deux eaux.$b$bL’heure de la guerre est proche.', 26124),
(143713, 'frFR', 'Je suis prêt à rechercher notre prochain allié.', 'Je suis prête à rechercher notre prochain allié.', 26124),
(143726, 'frFR', '', 'Informez votre chef de guerre sans tarder.', 26124),
(143727, 'frFR', '', 'Ne me faites pas perdre mon temps.', 26124),
(143728, 'frFR', '', 'Approchez.', 26124),
(143729, 'frFR', '', 'Salutations.', 26124),
(143730, 'frFR', '', 'Notre ouvrage ne fait que commencer.', 26124),
(143731, 'frFR', '', 'La Horde connaîtra un nouvel avenir.', 26124),
(143732, 'frFR', '', 'Servez-moi et vos efforts seront récompensés.', 26124),
(143733, 'frFR', '', 'Partez. J’ai beaucoup à faire.', 26124),
(143735, 'frFR', '', 'Servez la Horde. Servez-moi.', 26124),
(143736, 'frFR', '', 'L’Alliance se soumettra à nous.', 26124),
(143737, 'frFR', '', 'Les rangs des Réprouvés grossiront. D’une manière ou d’une autre.', 26124),
(143738, 'frFR', '', 'Tous finiront par servir la Horde.', 26124),
(143739, 'frFR', '', 'Nous prendrons ce qui nous revient de droit.', 26124),
(143741, 'frFR', '', 'L’essence vitale d’Azeroth appartient à la Horde.', 26124),
(143742, 'frFR', '', 'Je suis votre préférée des sœurs Coursevent, n’est-ce pas ? N’est-ce pas ?', 26124),
(143743, 'frFR', '', 'J’ai suivi votre parcours. Je pense que je vais vous envoyer chez Nathanos pour une petite remise à niveau.', 26124),
(143744, 'frFR', '', 'Vous croyez que je n’ai pas remarqué la façon dont vous lorgnez mes forestiers-sombres ? Je vous conseille d’arrêter ça tout de suite.', 26124),
(143745, 'frFR', '', 'Comploter ? Moi ? Qu’est-ce que l’innocente demoiselle que je suis pourrait bien comploter ?', 26124),
(143747, 'frFR', 'Le Puits de soleil doit être protégé.', '', 26124),
(143748, 'frFR', 'Qu’y a-t-il ?', '', 26124),
(143749, 'frFR', 'Ne gaspillez pas vos ressources.', '', 26124),
(143750, 'frFR', 'Je suis occupé.', '', 26124),
(143751, 'frFR', 'Je sers Lune-d’Argent.', '', 26124),
(143752, 'frFR', 'Que voulez-vous ?', '', 26124),
(143753, 'frFR', 'Le soleil éternel nous guide toujours.', '', 26124),
(143754, 'frFR', 'Respectez nos usages.', '', 26124),
(143755, 'frFR', 'Ne laissez aucun étranger s’en mêler.', '', 26124),
(143756, 'frFR', 'Faites ce que vous avez à faire.', '', 26124),
(143757, 'frFR', 'Nos traditions sont le fondement de notre avenir.', '', 26124),
(143758, 'frFR', 'Nous avons surmonté tant d’épreuves.', '', 26124),
(143759, 'frFR', 'Pour Quel’thalas !', '', 26124),
(143760, 'frFR', 'Mieux vaut ne pas s’opposer à nous.', '', 26124),
(143761, 'frFR', 'Si vous faisiez ce que je dis au lieu de penser par vous-mêmes, Azeroth se porterait bien mieux.', '', 26124),
(143762, 'frFR', 'Le Kirin Tor ? Je dirais plutôt le Kirin Dort.', '', 26124),
(143763, 'frFR', 'Khadgar ? Vous voulez dire Rat’dgar ?', '', 26124),
(143764, 'frFR', 'Jaina ? Vous voulez dire Jain-arde. Et Modera ? Euh… Bon, cette fois aucun de ces excellents jeux de mots ne me vient.', '', 26124),
(143767, 'frFR', 'T’laartos !', '', 26124),
(143768, 'frFR', 'T’laartos ?', '', 26124),
(143769, 'frFR', 'T’laartos salue le petit être chétif.', '', 26124),
(143770, 'frFR', 'Le petit être chétif a besoin de l’aide de T’laartos ?', '', 26124),
(143771, 'frFR', 'Un danger ? T’laartos se moque du danger !', '', 26124),
(143772, 'frFR', 'La Lumière soit avec vous.', '', 26124),
(143773, 'frFR', 'T’laartos est prêt !', '', 26124),
(143775, 'frFR', 'T’laartos.', '', 26124),
(143776, 'frFR', 'T’laartos vous reverra bientôt.', '', 26124),
(143777, 'frFR', 'T’laartos a tant à faire.', '', 26124),
(143778, 'frFR', 'T’laartos doit se remettre au travail.', '', 26124),
(143779, 'frFR', 'Revenez voir T’laartos quand vous voulez.', '', 26124),
(143780, 'frFR', 'T’laartos est fier d’être un Sancteforge !', '', 26124),
(143781, 'frFR', 'T’laartos a toujours un peu peur des serpents.', '', 26124),
(143782, 'frFR', 'Le petit être chétif n’essaierait jamais d’abuser la gentillesse de T’laartos, hein ?', '', 26124),
(143783, 'frFR', 'Oui, T’laartos sait lire. Surtout des livres avec peu de mots et plein d’images… mais ça compte quand même.', '', 26124),
(143784, 'frFR', 'Voilà la liste des choses que T’laartos n’aime pas : les serpents, les vilains enfants, les grottes sombres, les serpents… et les petits êtres chétifs qui embêtent T’laartos.', '', 26124),
(143785, 'frFR', 'Ah, ils sont tous tombés dans le panneau ! C’est incroyable qu’ils aient pu croire que je sois assez simple d’esprit pour… Attendez, vous m’écoutiez ? Je, euh… T’laartos !', '', 26124),
(143786, 'frFR', 'Trois larrons et un tas d’os. Trois larrons et tas d’os. T’larrons’ et tas d’os. T’laar et tos. T’laartos. T’laartos !', '', 26124),
(143881, 'frFR', 'Eh, vous. Par ici.', '', 26124),
(143882, 'frFR', 'Par ici !', '', 26124),
(143883, 'frFR', 'Attention !', '', 26124),
(143884, 'frFR', 'Par ici.', '', 26124),
(143885, 'frFR', 'Par ici.', '', 26124),
(143886, 'frFR', 'Attention !', '', 26124),
(143887, 'frFR', 'Par ici !', '', 26124),
(143888, 'frFR', 'Venez par ici.', '', 26124),
(144262, 'frFR', '', '<Alleria observe le froid visage de pierre de la statue avant de porter son attention sur la plaque où a été gravée son épitaphe.>', 26124),
(144263, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 26124),
(144264, 'frFR', '', 'Alleria soupire et fronce les sourcils.', 26124),
(144269, 'frFR', 'Excellent. Encore une fois !', '', 26124),
(144301, 'frFR', 'À présent, concentrez votre chi et expulsez l’énergie.', '', 26124),
(144305, 'frFR', 'Je n’arrive toujours pas à croire que mes frères et mes sœurs aient succombé à la corruption.', 'Je n’arrive toujours pas à croire que mes frères et mes sœurs aient succombé à la corruption.', 26124),
(144308, 'frFR', 'ZZzzzz…', 'ZZzzzz…', 26124),
(144309, 'frFR', '<Le Tauren endormi ronfle et se retourne.>', '<La Taurène endormie ronfle et se retourne.>', 26124),
(144310, 'frFR', 'Merci pour votre intervention auprès de Torok. Il refusait d’ouvrir les yeux sur le dangereux pouvoir qu’il convoitait.', 'Merci pour votre intervention auprès de Torok. Il refusait d’ouvrir les yeux sur le dangereux pouvoir qu’il convoitait.', 26124),
(144321, 'frFR', 'Nos frères et sœurs corrompus errent encore dans la nature.', 'Nos frères et sœurs corrompus errent encore dans la nature.', 26124),
(144322, 'frFR', 'Heureusement, je n’ai pas eu à TOUT donner.', 'Heureusement, je n’ai pas eu à TOUT donner.', 26124),
(144323, 'frFR', 'Lorsque vous prodiguez des soins, vous devez concentrer votre force intérieure afin de la transmettre à un autre.', '', 26124),
(144324, 'frFR', 'Le chi, une fois focalisé, devient extrêmement puissant. Maître Tau Li vous guidera dès que vous serez $gprêt:prête;.', '', 26124),
(144325, 'frFR', 'Il est dangereux de dépenser une importante quantité d’énergie d’une traite. Dosez votre effort.', '', 26124),
(144326, 'frFR', 'Excellent ! Recommencez encore une fois.', '', 26124),
(144365, 'frFR', '', 'Qu’est-ce que c’est que ça ? De la lumière dans les ténèbres ! C’est trop lumineux…', 26124),
(144366, 'frFR', '', 'Il fait un peu plus clair ! Je vois ! Un peu.', 26124),
(144367, 'frFR', '', 'Nuu-Nuu ! J’ai eu peur de ne jamais te revoir ! Comment as-tu atterri ici ?', 26124),
(144368, 'frFR', '', 'Une couronne ! Trop jolie !', 26124),
(144369, 'frFR', '', 'J’avais une baguette magique comme ça avant ! Mais je l’ai perdue il y a longtemps.', 26124),
(144370, 'frFR', '', 'Les ténèbres sont revenues ! Où êtes-vous ? Ne me laissez pas !', 26124),
(144371, 'frFR', '', 'Non ! Lâchez-moi ! Au secours ! À L’AIDE !', 26124),
(144383, 'frFR', 'Ces portails sont extrêmement difficiles à maintenir et, qui plus est, ils détournent notre attention de nos précieuses recherches.$B$BLa télémancie devrait pouvoir nous apporter une solution durable.', '', 26124),
(144384, 'frFR', 'J’ai entendu dire que Dalaran a tout un espace dédié aux déplacements magiques.$B$BImaginez les possibilités !', '', 26124),
(144386, 'frFR', 'Vous pouvez emprunter le portail d’Orgrimmar pour rejoindre la capitale de nos nouveaux alliés de la Horde en Kalimdor.', '', 26124),
(144394, 'frFR', 'Certains de nos vignerons ont cessé de travailler dans leurs vignobles pour s’adonner à d’autres activités botaniques.', '', 26124),
(144395, 'frFR', 'J’ai apporté des échantillons pour dissiper les rumeurs qui veulent que notre vin ait un arôme de pieds… de vigne, il va sans dire !', '', 26124),
(144396, 'frFR', '', 'Les Sacrenuit sont véritablement libres. Nous n’avons plus besoin du Puits de la nuit, ni de sa puissance.$B$BIl nous faut à présent forger notre propre destin.', 26124),
(144397, 'frFR', '', 'On en a fini avec Élisande, mais il reste encore beaucoup à faire pour la ville.', 26124),
(144399, 'frFR', '', 'Il fait trop sombre ! Je ne vois rien !', 26124),
(144400, 'frFR', '', 'Qui êtes-vous ? Vous pouvez m’aider ?', 26124),
(144401, 'frFR', '', 'À l’aide ! À L’AIDE !', 26124),
(144402, 'frFR', '', 'Au moins maintenant on est ensemble. Même si on ne sait pas où.', 26124),
(144403, 'frFR', '', 'Mais on est $gamis:amies;, alors je suis certaine que ça va aller.', 26124),
(144404, 'frFR', '', 'Si seulement on pouvait y voir plus clair. Il fait si sombre ici !', 26124),
(144442, 'frFR', '', 'Il y a trop de lumière ! Trop de lumière ! Aaaah !', 26124),
(144444, 'frFR', '', 'Oh, bonjour ! Qui êtes-vous ? Moi, c’est Uuna. Vous voulez être mon $gami:amie; ? Ensemble, on parviendra à sortir d’ici.', 26124),
(144445, 'frFR', '', 'Si seulement Nuu était là, il saurait quoi faire.', 26124),
(144563, 'frFR', '', 'Diriger l’énergie du chi vers une cible peut s’avérer difficile de prime abord.

Vous, là ! Essayez de toucher le mannequin d’entraînement là-bas.', 26124),
(144564, 'frFR', '', 'Excellent ! Je suis impressionnée !', 26124),
(144565, 'frFR', 'Je veillerai sur lui. Il a l’air ravi de flâner dans les jardins.', 'Je veillerai sur lui. Il a l’air ravi de flâner dans les jardins.', 26124),
(144566, 'frFR', 'Il y a encore des dégâts structurels et de l’énergie instable dans les aqueducs. Les portes resteront fermées pour le moment.', 'Il y a encore des dégâts structurels et de l’énergie instable dans les aqueducs. Les portes resteront fermées pour le moment.', 26124),
(144567, 'frFR', '', 'Nuu est là pour nous aider. Je savais que tu nous retrouverais, Nuu !', 26124),
(144568, 'frFR', 'Argus l’Annihilateur déploie des modules de réorigination !', 'Argus l’Annihilateur déploie des modules de réorigination !', 26124),
(144575, 'frFR', '', 'Je le serrerai contre moi, comme ça il ne se perdra plus.', 26124),
(144621, 'frFR', '', 'Salutations, $p ! De nouvelles contrées et rencontres nous attendent sur Azeroth.$B$BOculeth a préparé des portails en bas qui n’attendent plus que vous.', 26124),
(144672, 'frFR', 'Je suis heureux de voir qu’Arluelle continue l’entraînement, elle m’a l’air déjà bien plus forte.$B$BPeut-être devrais-je mesurer ses progrès.', '', 26124),
(144674, 'frFR', 'Que la Garde crépusculaire puisse compter Victoire dans ses rangs à nouveau est une bonne chose.', '', 26124),
(144676, 'frFR', 'Il est regrettable que les Sancteforge n’aient pas rallié notre cause. Leurs prouesses martiales sont impressionnantes.', '', 26124),
(144677, 'frFR', '', 'J’ai le sentiment que notre ville sera bientôt sollicitée. Je serai prête le moment venu.', 26124),
(144678, 'frFR', '', '<Arluelle a le regard lointain.>$B$BSi seulement mon frère pouvait voir la ville aujourd’hui…', 26124),
(144712, 'frFR', '', 'Elle tire des étoiles ! Les méchants détestent ça.', 26124),
(144713, 'frFR', '', 'Personne peut battre les ténèbres sans couronne. C’est comme ça !', 26124),
(144714, 'frFR', 'T’LAARTOS !', '', 26124),
(144715, 'frFR', '', 'Je me sens beaucoup mieux.', 26124),
(144716, 'frFR', 'T’laartos est là !', '', 26124),
(144721, 'frFR', 'Les Ténèbres approchent…', 'Les Ténèbres approchent…', 26124),
(144722, 'frFR', 'FAITES QUE ÇA CESSE !', 'FAITES QUE ÇA CESSE !', 26124),
(144723, 'frFR', 'Votre mort est nécessaire.', 'Votre mort est nécessaire.', 26124),
(144725, 'frFR', 'Les ténèbres vous dévoreront.', 'Les ténèbres vous dévoreront.', 26124),
(144726, 'frFR', 'Écoutez les murmures. Ils sont si doux.', 'Écoutez les murmures. Ils sont si doux.', 26124),
(144745, 'frFR', '', 'Encore, T’laartos ? Combien de fois il faudra…', 26124),
(144749, 'frFR', 'Pas assez pour arrêter T’laartos !', '', 26124),
(144750, 'frFR', 'T’laartos est reconnaissant envers Lysara. T’laartos sent qu’il est prêt à retourner au combat !', '', 26124),
(144751, 'frFR', '', 'Même la meilleure arme s’use quand elle est utilisée trop souvent. Prenez le temps de bien vous reposer, T’laartos.', 26124),
(144752, 'frFR', 'Merci, $gchampion:championne;.', 'Merci, $gchampion:championne;.', 26124),
(144753, 'frFR', 'Ces murmures… me rendaient fou !', 'Ces murmures… me rendaient folle !', 26124),
(144754, 'frFR', 'Je dois… Mon esprit… Il faut que je parte d’ici !', 'Je dois… Mon esprit… Il faut que je parte d’ici !', 26124),
(144755, 'frFR', 'C’était horrible, $R.', 'C’était horrible, $R.', 26124),
(144756, 'frFR', 'Que la Terre-Mère vous bénisse !', 'Que la Terre-Mère vous bénisse !', 26124),
(144757, 'frFR', 'Je pensais avoir perdu l’esprit.', 'Je pensais avoir perdu l’esprit.', 26124),
(144758, 'frFR', 'Le redresseur de torts sancteforge grogne.', 'La redresseuse de torts sancteforge grogne.', 26124),
(144759, 'frFR', 'Que la Lumière me protège… Il est de retour.', 'Que la Lumière me protège… Il est de retour.', 26124),
(144760, 'frFR', 'Chut, ne bougez plus ! Sa vision est basée sur le mouvement.', 'Chut, ne bougez plus ! Sa vision est basée sur le mouvement.', 26124),
(144770, 'frFR', 'Je n’ai plus de matériaux pour le moment. Toutes mes excuses.', '', 26124),
(144772, 'frFR', 'Ça fait du bien de se reposer de temps en temps.$B$BEn particulier après des affaires fructueuses !', '', 26124),
(144800, 'frFR', 'Dites-moi ce qui s’est passé au Repos du lion.', 'Dites-moi ce qui s’est passé au Repos du lion.', 26124),
(144804, 'frFR', 'Il est de bonne humeur aujourd’hui, non ?', '', 26124),
(144806, 'frFR', '', 'Oh oui, comme hier, avant-hier, et le jour d’avant !', 26124),
(144807, 'frFR', '', 'C’est une qualité remarquable, je l’apprécie pour ça.', 26124),
(144825, 'frFR', 'Nos agents ont déjà infiltré l’exploitation minière gobeline souterraine. Nous saurons bientôt ce qu’ils préparent…', '', 26124),
(144826, 'frFR', '', 'Est-ce que c’est vous ?', 26124),
(144827, 'frFR', '', 'Je n’abandonnerai pas ! Je vous le promets !', 26124),
(144828, 'frFR', '', 'J’ai si froid et il fait tellement sombre ici. Je ne sais pas quoi faire !', 26124),
(144833, 'frFR', 'Ha ha ! T’laartos est content de voir que vous allez bien ! T’laartos a aussi apporté un cadeau, qu’il a trouvé en Val’sharah.', '', 26124),
(144834, 'frFR', '', 'Vous voilà ! Je préfère ça.', 26124),
(144835, 'frFR', '', 'Ils seront bientôt là, mon $gami:amie;.', 26124),
(144836, 'frFR', '', 'Je n’arrête pas de courir… mais ils me retrouvent toujours.', 26124),
(144837, 'frFR', '', 'Mais maintenant, vous êtes là. Ensemble, on peut les combattre ! Je crois…', 26124),
(144838, 'frFR', '', 'Promettez-moi que vous ne m’abandonnerez pas, mon $gami:amie;. Même quand il fera tout sombre…', 26124),
(144839, 'frFR', '', 'T’laartos !', 26124),
(144840, 'frFR', 'La Dame noire a une tâche importante à vous confier, $c. J’espère que vous êtes $gprêt:prête;…', '', 26124),
(144841, 'frFR', 'Racontez-moi ce qui s’est passé lors du festin.', 'Racontez-moi ce qui s’est passé lors du festin.', 26124),
(144842, 'frFR', '', 'Ahh !', 26124),
(144845, 'frFR', 'T’laartos doit ramener ce petit, maintenant. Dites au revoir, les enfants.', '', 26124),
(144846, 'frFR', 'Ne vous inquiétez pas, T’laartos reviendra bientôt avec de nouvelles histoires et peut-être un autre copain.', '', 26124),
(144847, 'frFR', '', ' C’est T’laartos !', 26124),
(144848, 'frFR', '', 'Il est de retour !', 26124),
(144849, 'frFR', '', 'Non ! Reste et raconte-nous encore des histoires d’aventure, T’laartos !', 26124),
(144850, 'frFR', '', 'Je peux le garder ?', 26124),
(144851, 'frFR', '', 'Sa queue est toute douce !', 26124),
(144853, 'frFR', 'Nos guerriers les plus courageux sont souvent à l’avant-garde. Le moins que je puisse faire est de protéger leurs familles jusqu’à leur retour.', 'Nos guerriers les plus courageux sont souvent à l’avant-garde. Le moins que je puisse faire est de protéger leurs familles jusqu’à leur retour.', 26124),
(144862, 'frFR', '', 'T’laartos nous a montré comment jouer à Rocher, parchemin, lame mais j’ai oublié les règles.', 26124),
(144863, 'frFR', 'Je cherche une petite fille du nom d’Uuna, est-ce que vous l’avez vue ?', 'Je cherche une petite fille du nom d’Uuna, est-ce que vous l’avez vue ?', 26124),
(144864, 'frFR', 'Que la Lumière soit avec vous.', 'Que la Lumière soit avec vous.', 26124),
(144866, 'frFR', '', 'J’ai entendu les pleurs de l’enfant dont vous parlez.

Je vais vous marquer, pour que vous puissiez vous rendre dans ce royaume pour la chercher.

Elle se trouve à l’endroit où la barrière entre le royaume de la vie et de la mort est la plus mince, et où elle déborde dans votre monde.

Mais faites attention, vous n’avez aucun pouvoir dans ce lieu, les mortels ne peuvent pas blesser ses habitants.

Vous aurez beau essayer, vous ne pourrez peut-être pas aider votre amie.', 26124),
(144873, 'frFR', '<Une larme de dragon vert, cachée dans l’ombre par des forces inconnues.>', '', 26124),
(144875, 'frFR', '<Toucher la larme.>', '<Toucher la larme.>', 26124),
(144895, 'frFR', '', 'Ils sont là…', 26124),
(144896, 'frFR', '', 'Vous avez raté l’échéance de paiement une fois de trop, M. Front-de-Pierre. Je saisis vos biens, comme convenu dans notre contrat.', 26124),
(144897, 'frFR', 'Je vous ai envoyé l’argent ce matin, je vous le jure ! Vous ne pouvez pas me laisser en plan comme ça !', '', 26124),
(144898, 'frFR', '', 'Monsieur Chu, veuillez raccompagner ce Nain à la sortie. Madame Xiulan, remettez l’armure en vente.', 26124),
(144899, 'frFR', '%s hoche la tête.', '', 26124),
(144900, 'frFR', '', 'Partez ! Vous ne nous faites pas peur !', 26124),
(144901, 'frFR', '', 'Oui, madame.', 26124),
(144902, 'frFR', 'Enlève tes sales pattes de là, boule de poils !', '', 26124),
(144903, 'frFR', '', 'On dirait que vous avez de la chance aujourd’hui, M. Front-de-Pierre. Vous pouvez reprendre les marchandises.', 26124),
(144904, 'frFR', 'Un peu que je vais tout reprendre ! J’ai obtenu cette armure de façon honnête, même si je n’ai pas encore fini de la payer.', '', 26124),
(144905, 'frFR', 'Ahh, je préfère ça. Une armure digne d’un véritable héros ! Un de ceux dont les actes légendaires font trembler les fondations mêmes d’Azeroth !', '', 26124),
(144906, 'frFR', 'Très bien, en route pour l’auberge, maintenant.', '', 26124),
(144907, 'frFR', 'Merci pour votre aide, $gmon gars:ma belle; ! À charge de revanche !', '', 26124),
(144908, 'frFR', 'Le Vindicaar est prêt pour son prochain voyage.

Tout comme moi.', '', 26124),
(144921, 'frFR', '', 'Que la Lumière emporte cette table ! Je ne pourrai peut-être plus jamais utiliser cet atelier.$B$BJ’ai beau récurer cette table encore et encore, la corruption provenant de ces peaux de bêtes d’Argus subsiste.', 26124),
(144923, 'frFR', 'Si c’est Maela que vous cherchez, elle donne un coup de main sur le front.$B$BIl y a à Hurlevent de nombreux couturiers très compétents qui peuvent vous apprendre une chose ou deux.', '', 26124),
(144924, 'frFR', '', '<Fareeya vous accueille avec un sourire chaleureux.>$B$BVous vous avez affronté les épreuves avec brio, $c. J’ai le sentiment que votre histoire ne fait que commencer.', 26124),
(144925, 'frFR', '', 'N’oubliez jamais ce que vouer sa vie à la Lumière signifie.', 26124),
(144926, 'frFR', '', 'Salutations, $c.', 26124),
(144994, 'frFR', '', 'Oui, bien sûr que je l’aime toujours. Mais ça ne vous regarde pas.', 26124),
(145018, 'frFR', '', 'C’est compliqué de s’entendre avec ses sœurs. Surtout les mortes-vivantes.', 26124),
(145022, 'frFR', '', 'Le Vide en moi vous engloutira… si vous me le demandez gentiment.', 26124),
(145026, 'frFR', '', 'J’étais portée disparue pendant des années et c’est comme ça que vous me traitez ?', 26124),
(145027, 'frFR', '', 'C’est un bon jour pour chasser.', 26124),
(145028, 'frFR', '', 'Utilisez toutes les armes à votre disposition.', 26124),
(145031, 'frFR', '', 'Quelles sont les nouvelles ?', 26124),
(145036, 'frFR', '', 'Nous suivons tous une voie différente. Choisissez la vôtre.', 26124),
(145038, 'frFR', '', 'Salutations.', 26124),
(145039, 'frFR', '', 'Les ombres peuvent être nos alliées… si nous parvenons à les contrôler.', 26124),
(145040, 'frFR', '', 'Adieu.', 26124),
(145041, 'frFR', '', 'Visez juste.', 26124),
(145042, 'frFR', '', 'Nous faisons notre devoir pour protéger ceux que nous aimons.', 26124),
(145043, 'frFR', '', 'Gardez les yeux sur la cible.', 26124),
(145102, 'frFR', 'Curieux.', 'Curieux.', 26124),
(145140, 'frFR', '', '$GMon ami:Mon amie; ? Vous êtes toujours là ? J’ai peur !', 26124),
(145141, 'frFR', '', 'Je… Je ne peux pas ! Je veux juste rentrer chez moi !', 26124),
(145142, 'frFR', '', 'Uuna entoure ses épaules de ses bras et se met à pleurer.', 26124),
(145154, 'frFR', '', '$GM-mon ami:M-mon amie;, vous êtes là ! Vous ne m’avez pas abandonnée !', 26124),
(145155, 'frFR', '', 'Maman m’a dit que la Lumière me retrouverait toujours ! C’est vous. Vous êtes ma lumière !', 26124),
(145156, 'frFR', '', 'Tant que ma lumière est avec moi, les ténèbres ne peuvent pas gagner !', 26124),
(145158, 'frFR', '', 'Ma lumière est super forte !', 26124),
(145159, 'frFR', '', 'JE N’AI PLUS PEUR !', 26124),
(145172, 'frFR', 'Je suis prêt. Commençons le rituel.', 'Je suis prête. Commençons le rituel.', 26124),
(145185, 'frFR', '', 'Les ombres ont disparu ! Je peux voir !', 26124),
(145186, 'frFR', '', 'Oh, mon $gami:amie; ! On a réussi ! On les a battus !', 26124),
(145187, 'frFR', '', 'Que… qu’est-ce qui s’est passé ?', 26124),
(145188, 'frFR', '', 'La lumière… Elle me demande de la suivre…', 26124),
(145189, 'frFR', '', 'Maman ! Papa ! Ils m’attendent !', 26124),
(145190, 'frFR', '', 'Une seconde…', 26124),
(145191, 'frFR', '', 'Il y a tellement de choses que je n’ai jamais pu faire. Tellement d’endroits où je ne suis jamais allée…', 26124),
(145192, 'frFR', '', 'Je peux rester avec mon $gami:amie; ? Juste un petit peu ?', 26124);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145193, 'frFR', '', 'La lumière dit que je peux rester ! You-hou !', 26124),
(145194, 'frFR', '', 'Dites à maman et à papa qu’ils me manquent et… que je les reverrai bientôt !', 26124),
(145195, 'frFR', '', 'Très bien, mon $gami:amie;, partons d’ici ! Nous avons tellement d’endroits à visiter !', 26124),
(145197, 'frFR', '', 'Uuna vous serre dans ses bras.', 26124),
(145199, 'frFR', '', 'Ouh là là ! C’est le plus grand mur que j’aie jamais vu !', 26124),
(145200, 'frFR', '', 'À votre avis, de quoi il les protégeait ?', 26124),
(145201, 'frFR', '', 'Des insectes ? Je parie que c’était des insectes. Beurk ! Je déteste les insectes !', 26124),
(145202, 'frFR', '', 'Beurk !', 26124),
(145203, 'frFR', '', 'Ouah ! C’est la plus jolie maison que j’aie jamais vue !', 26124),
(145204, 'frFR', '', 'Vous savez qui habite ici ? Je parie que c’est une princesse.', 26124),
(145205, 'frFR', '', 'Vous voulez jouer à la princesse avec moi ?', 26124),
(145206, 'frFR', '', 'Ouah… Une ville volante ! Vraiment ?!', 26124),
(145207, 'frFR', '', 'Comment c’est possible ?', 26124),
(145208, 'frFR', '', 'Est-ce que vous habitez ici ?', 26124),
(145209, 'frFR', '', 'Maintenant que j’y pense… Est-ce que vous habitez quelque part ?', 26124),
(145210, 'frFR', '', 'Hé, c’est quoi ces trucs qui volent ? C’est trop joli !', 26124),
(145211, 'frFR', '', 'C’est une grande tour. On dirait un… nichoir géant !', 26124),
(145212, 'frFR', '', 'Mais pour des lézards qui volent.', 26124),
(145213, 'frFR', '', 'Je peux en avoir un comme mascotte ?', 26124),
(145218, 'frFR', '', 'Regardez ! On est sous un arbre géant !', 26124),
(145221, 'frFR', '', 'Je me demande combien d’oiseaux vivent dans cet arbre. Il doit y en avoir des tas !', 26124),
(145225, 'frFR', '', 'Genre… au moins DIX !', 26124),
(145237, 'frFR', '', 'Piou piou piou piou !', 26124),
(145240, 'frFR', '', 'Je peux tout voir d’ici !', 26124),
(145241, 'frFR', '', 'Je ne savais pas que des montagnes pouvaient être aussi hautes !', 26124),
(145243, 'frFR', '', 'Ne tombez pas, surtout ! Si je tombe, c’est pas grave, mais vous, vous finiriez comme une crêpe !', 26124),
(145245, 'frFR', '', 'Alors faites attention, d’accord ?', 26124),
(145246, 'frFR', '', 'Où sommes-nous ? C’est quoi toute cette fumée ?', 26124),
(145247, 'frFR', '', 'Regardez là-bas. C’est tout brillant !', 26124),
(145253, 'frFR', '', 'Mais ça bouge comme de l’eau… C’est un lac lumineux ?', 26124),
(145254, 'frFR', '', 'C’est vraiment idiot.', 26124),
(145255, 'frFR', '', 'C’est… tellement beau…', 26124),
(145256, 'frFR', '', 'C’est mon peuple ! Il a survécu !', 26124),
(145257, 'frFR', '', 'Ils ne sont pas tous morts sur Argus ?', 26124),
(145258, 'frFR', '', 'Merci BEAUCOUP de m’avoir montré ça, mon $gami:amie; !', 26124),
(145263, 'frFR', '', 'Vous m’avez fait voir tellement de choses géniales. Vous êtes vraiment trop super !', 26124),
(145265, 'frFR', '', 'Je sais qu’un jour, je devrai retrouver maman et papa.', 26124),
(145266, 'frFR', '', 'Mais… pas tout de suite.', 26124),
(145275, 'frFR', '', 'Aaaahhh ! Non ! À l’aide !', 26124),
(145276, 'frFR', 'Uuna est engloutie par les ténèbres.', 'Uuna est engloutie par les ténèbres.', 26124),
(145721, 'frFR', '', 'L’évolution biologique des espèces silithides est absolument fascinante !', 26124),
(145890, 'frFR', 'Nous sommes un peu occupés pour le moment, comme vous pouvez le voir.', 'Nous sommes un peu occupés pour le moment, comme vous pouvez le voir.', 26124),
(145892, 'frFR', '<La concentration de l’Elfe faiblit momentanément et il vous lance un regard noir.>', '<La concentration de l’Elfe faiblit momentanément et elle vous lance un regard noir.>', 26124),
(145895, 'frFR', '', 'Les voix ne cessent jamais. Elles provoquent, persécutent, implorent. Elles ne laissent aucun répit.

Mais votre volonté surpasse leur emprise. Vous avez en vous la force de percer leurs secrets, d’user de leur pouvoir.', 26124),
(145896, 'frFR', 'Fascinant.

J’avais pressenti qu’une telle transformation était destinée à Alleria Coursevent. Mais je n’avais pas prévu que les siens changeraient aussi.

Les enjeux sont nombreux. Ces évènements me donnent matière à penser.', '', 26124),
(145897, 'frFR', 'Nous ne risquons plus l’exil dans notre quête de connaissances.', 'Nous ne risquons plus l’exil dans notre quête de connaissances.', 26124),
(145898, 'frFR', 'Une voie qui nous a longtemps été refusée s’ouvre enfin à nous.', 'Une voie qui nous a longtemps été refusée s’ouvre enfin à nous.', 26124),
(145977, 'frFR', 'Trouvez-moi un peu de tissu et je serai paré !', '', 26124),
(146006, 'frFR', 'Faites attention aux failles du Vide instables et à leurs rejetons. Cette zone n’est pas vraiment sûre.', 'Faites attention aux failles du Vide instables et à leurs rejetons. Cette zone n’est pas vraiment sûre.', 26124),
(146007, 'frFR', 'Vous voulez quoi ?', '', 26124),
(146008, 'frFR', 'Merveilleux.', '', 26124),
(146009, 'frFR', 'On attend de moi que je vous salue. Bonjour.', '', 26124),
(146010, 'frFR', 'Félicitations.', '', 26124),
(146011, 'frFR', 'Tout est conçu pour vous tuer.', '', 26124),
(146012, 'frFR', 'J’imagine que c’est très douloureux.', '', 26124),
(146013, 'frFR', 'J’imagine que c’est très douloureux.', '', 26124),
(146014, 'frFR', 'Pour le moment.', '', 26124),
(146015, 'frFR', 'Possible.', '', 26124),
(146016, 'frFR', 'Merveilleux.', '', 26124),
(146017, 'frFR', 'Je crains de ne pas pouvoir l’autoriser.', '', 26124),
(146018, 'frFR', 'Quand on la mélange avec du gaz naturel, l’azérite liquide durcit rapidement, ce qui nous permet de la récupérer plus facilement. Gardez les yeux rivés au sol à la recherche d’activité instable à la surface. Avec les récentes secousses… elle pourrait jaillir de crevasses ou de fissures.', '', 26124),
(146019, 'frFR', 'Nous avons observé une puissante activité géothermique sur cette île inconnue.

De l’azérite, très certainement !', '', 26124),
(146020, 'frFR', 'Que pouvez-vous me dire sur les Draeneï sancteforge ?', 'Que pouvez-vous me dire sur les Draeneï sancteforge ?', 26124),
(146021, 'frFR', 'Que savons-nous des Elfes du Vide ?', 'Que savons-nous des Elfes du Vide ?', 26124),
(146022, 'frFR', 'La guerre se prépare en Azeroth, $n. Il est temps pour nous de convaincre de nouveaux alliés de rejoindre notre cause.', '', 26124),
(146023, 'frFR', 'Ahh… Cette soie est plus agréable qu’une pluie par une chaude journée d’été…', '', 26124),
(146024, 'frFR', 'Je suis prête à rechercher notre prochain allié.', 'Je suis prête à rechercher notre prochain allié.', 26124),
(146025, 'frFR', 'Maintenant, je vais juste enflammer une allumette pour m’occuper des émanations…', '', 26124),
(146026, 'frFR', 'FEU !', '', 26124),
(146027, 'frFR', 'AAAAHHHHHHHHHHHH !', '', 26124),
(146029, 'frFR', 'C’est pas passé loin ! Je ferais mieux de faire l’inventaire. Sourcils… OK. Barbe… OK. Pantalon…', '', 26124),
(146030, 'frFR', 'Pas le temps pour le pantalon ! Il faut vite que je trouve une clinique pour les grands brûlés…', '', 26124),
(146031, 'frFR', 'Oohhh…', '', 26124),
(146032, 'frFR', 'Aïe !', '', 26124),
(146033, 'frFR', 'Haaa…', '', 26124),
(146044, 'frFR', '', 'Bonjour ! Que puis-je faire pour vous ?', 26124),
(146045, 'frFR', 'J’aimerais jeter un œil à mon courrier.', 'J’aimerais jeter un œil à mon courrier.', 26124),
(146049, 'frFR', 'Des ennemis !', 'Des ennemis !', 26124),
(146050, 'frFR', 'Des créatures du Vide ! Abattez-les !', 'Des créatures du Vide ! Abattez-les !', 26124),
(146064, 'frFR', '', 'On dirait que le maître de poste a besoin de moi immédiatement. À plus !', 26124),
(146067, 'frFR', '', 'Le courrier doit arriver à destination ! À la prochaine !', 26124),
(146068, 'frFR', '', 'Oh non, je suis en retard ! Ces lettres ne vont pas se trier toutes seules !', 26124),
(146069, 'frFR', '', 'La journée est finie pour moi. À plus !', 26124),
(146070, 'frFR', '', 'Vous avez sonné ?', 26124),
(146071, 'frFR', '', 'Katy Siffletimbre au rapport !', 26124),
(146072, 'frFR', '', 'Quand il y a du courrier à déclarer, vous pouvez être certains que je suis dans le coin !', 26124),
(146073, 'frFR', '', 'Le courrier doit circuler !', 26124),
(146080, 'frFR', 'Merci encore, $n. À la revoyure ! Faut que je me trouve un pantalon…', '', 26124),
(146083, 'frFR', 'Bon sang de bonsoir ! J’ai oublié mon futal !', '', 26124),
(146090, 'frFR', 'L’énergie du Vide pure est absorbée par ce lieu… Magnifique.', 'L’énergie du Vide pure est absorbée par ce lieu… Magnifique.', 26124),
(146098, 'frFR', 'La tempête de Vide grandit. Elle pourrait bien engloutir toute l’île.', 'La tempête de Vide grandit. Elle pourrait bien engloutir toute l’île.', 26124),
(146099, 'frFR', 'Les énergies du Vide non contenues ravagent les autres îles. Il est trop dangereux de naviguer pour le moment.', 'Les énergies du Vide non contenues ravagent les autres îles. Il est trop dangereux de naviguer pour le moment.', 26124),
(146105, 'frFR', '', 'Voilà !', 26124),
(146117, 'frFR', 'Eh bien, qu’avons-nous là ?', '', 26124),
(146118, 'frFR', 'Je me demande comment vous avez appris que nous nous trouvions ici ?', '', 26124),
(146119, 'frFR', 'Vous autres mortels, vous êtes tous pareils. Vous vous battez, mais vous ne savez pas pourquoi.', '', 26124),
(146120, 'frFR', 'Quel dommage. Votre place aurait été à mon service.', '', 26124),
(146122, 'frFR', 'Je vois, vous vous mêlez de ce qui ne vous regarde pas. C’est compréhensible.', '', 26124),
(146148, 'frFR', 'Il faut vous concentrer.', 'Il faut vous concentrer.', 26124),
(146149, 'frFR', 'Ouais ? C’est à quel sujet ?', 'Ouais ? C’est à quel sujet ?', 26124),
(146150, 'frFR', 'Eh ! Mêlez-vous de vos affaires !', 'Eh ! Mêlez-vous de vos affaires !', 26124),
(146151, 'frFR', 'J’ai pas de temps à perdre. Videz vos poches !', 'J’ai pas de temps à perdre. Videz vos poches !', 26124),
(146152, 'frFR', 'Le temps, c’est de l’argent !', 'Le temps, c’est de l’argent !', 26124),
(146154, 'frFR', '', 'Un portail, un !', 26124),
(146159, 'frFR', 'Vous avez acquis les bases. Mais seule la pratique vous apportera la maîtrise.', '', 26124),
(146165, 'frFR', 'Heureusement, ce lieu convient parfaitement à…', '', 26124),
(146179, 'frFR', 'J’ai volé ça dans les règles de l’art ! C’est à moi !', 'J’ai volé ça dans les règles de l’art ! C’est à moi !', 26124),
(146180, 'frFR', 'Oh… Vous allez le payer !', 'Oh… Vous allez le payer !', 26124),
(146181, 'frFR', 'Vous cherchez des noises au mauvais gobelin !', 'Vous cherchez des noises au mauvais gobelin !', 26124),
(146182, 'frFR', 'C’est à moi ! À MOI !', 'C’est à moi ! À MOI !', 26124),
(146183, 'frFR', 'Aïe ! Ça suffit ! Vous pouvez la garder !', 'Aïe ! Ça suffit ! Vous pouvez la garder !', 26124),
(146184, 'frFR', 'J’abandonne ! Tenez, prenez-la !', 'J’abandonne ! Tenez, prenez-la !', 26124),
(146185, 'frFR', 'Je vous la donne, c’est bon !', 'Je vous la donne, c’est bon !', 26124),
(146186, 'frFR', 'Pitié ! Prenez tout, je n’en voulais pas de toute façon !', 'Pitié ! Prenez tout, je n’en voulais pas de toute façon !', 26124),
(146187, 'frFR', 'Accélérez le mouvement, $nistine, ou comment dites-vous déjà, ou j’accorderai ce grand honneur à un autre plébéien !', '', 26124),
(146188, 'frFR', 'C’est bon, prenez tout ! Je n’en veux plus !', 'C’est bon, prenez tout ! Je n’en veux plus !', 26124),
(146189, 'frFR', 'Derrière vous !', 'Derrière vous !', 26124),
(146191, 'frFR', 'Parfait ! Je n’aurais pas choisi meilleur moment !', '', 26124),
(146192, 'frFR', 'Qu’attendez-vous donc ? Concentrez-vous et chassez cette créature !', '', 26124),
(146194, 'frFR', 'Très… très bien !', 'Très… très bien !', 26124),
(146195, 'frFR', 'Pitoyable.', '', 26124),
(146200, 'frFR', 'Je ne me sens pas très bien…', 'Je ne me sens pas très bien…', 26124),
(146201, 'frFR', 'Reprenez votre calme, et cela passera.', '', 26124),
(146202, 'frFR', 'Vos émotions révèlent vos faiblesses. Le Vide s’en servira contre vous si vous le lui permettez.', '', 26124),
(146212, 'frFR', 'Pour l’Alliance !', 'Pour l’Alliance !', 26124),
(146213, 'frFR', '', 'Ne vous souciez pas du vaisseau, je m’assurerai d’éloigner les… indésirables.', 26124),
(146214, 'frFR', 'Tout membre de l’Alliance qui montera à bord de ce vaisseau sera brûlé vif !', '', 26124),
(146231, 'frFR', 'Malgré la désolation des lieux, cette faille renferme de nombreux secrets. Elle nous en apprendra beaucoup sur la nature des ténèbres.', '', 26124),
(146233, 'frFR', 'Ouvrez le feu !', '', 26124),
(146237, 'frFR', 'Le courrier doit arriver à destination !', '', 26124),
(146238, 'frFR', 'Je veux trier le courrier !', 'Je veux trier le courrier !', 26124),
(146239, 'frFR', 'J’ai besoin d’aide pour trier toutes ces lettres !', '', 26124),
(146350, 'frFR', '', 'À peine le temps d’en finir avec la Légion ardente que la Horde prépare déjà un mauvais coup !', 26124),
(146351, 'frFR', 'Ça va ! Ça va ! Je retourne travailler !', 'Ça va ! Ça va ! Je retourne travailler !', 26124),
(146352, 'frFR', 'Je prenais juste le temps de souffler !', 'Je prenais juste le temps de souffler !', 26124),
(146353, 'frFR', 'C’est bon, j’y retourne !', 'C’est bon, j’y retourne !', 26124),
(146354, 'frFR', 'Pas la peine de sortir les crocs ! Je me remets au boulot !', 'Pas la peine de sortir les crocs ! Je me remets au boulot !', 26124),
(146355, 'frFR', 'Je ne faisais que me reposer les yeux !', 'Je ne faisais que me reposer les yeux !', 26124),
(146356, 'frFR', 'Ils envoient les gros bras ! On se taille !', 'Ils envoient les gros bras ! On se taille !', 26124),
(146358, 'frFR', 'Je ne peux pas m’attarder, allons à l’essentiel.', '', 26124),
(146359, 'frFR', 'Nous prendrons ce territoire pour la gloire de la Horde !', '', 26124),
(146360, 'frFR', '', 'Disséquer des insectes géants n’est pas une partie de plaisir. Par contre, ça paye bien !', 26124),
(146361, 'frFR', 'PAR LA BARBE D’ODYN ! JE SUIS EN FEU !', '', 26124),
(146367, 'frFR', 'Tu l’as cherché !', 'Tu l’as cherché !', 26124),
(146368, 'frFR', 'Je vais te remettre les idées en place !', 'Je vais te remettre les idées en place !', 26124),
(146369, 'frFR', 'On ne plaisante pas avec le cartel !', 'On ne plaisante pas avec le cartel !', 26124),
(146370, 'frFR', 'Tu vas regretter ton insolence !', 'Tu vas regretter ton insolence !', 26124),
(146371, 'frFR', 'On ne passe pas !', 'On ne passe pas !', 26124),
(146372, 'frFR', 'Je vais te refaire le portrait !', 'Je vais te refaire le portrait !', 26124),
(146373, 'frFR', 'L’heure du jugement est déjà arrivée pour vous !', '', 26124),
(146374, 'frFR', 'Ogmot va engloutir ton âme ! HA HA HA !', '', 26124),
(146375, 'frFR', 'Je vais te faire la peau, ordure |2 $R !', 'Je vais te faire la peau, ordure |2 $R !', 26124),
(146376, 'frFR', 'Tu vas payer pour tes crimes contre l’Alliance !', 'Tu vas payer pour tes crimes contre l’Alliance !', 26124),
(146377, 'frFR', 'Ton heure a sonné !', 'Ton heure a sonné !', 26124),
(146378, 'frFR', 'Ne meurs pas trop vite ! Je suis d’humeur joueuse !', 'Ne meurs pas trop vite ! Je suis d’humeur joueuse !', 26124),
(146379, 'frFR', 'Je suis la dernière chose que tu verras !', 'Je suis la dernière chose que tu verras !', 26124),
(146380, 'frFR', 'Crève, pourriture de la Horde !', 'Crève, pourriture de la Horde !', 26124),
(146422, 'frFR', '', 'Welcome! Now where are the chairs?$B$BOh. Feel free to pull up that... block of wood and sit...down?', 26124),
(146423, 'frFR', '', 'Honestly, if the local cuisine wasn\'t absolutely mouthwatering I wouldn\'t know what to do with myself.', 26124),
(146431, 'frFR', 'Incroyable ! Cette simple zone rassemble pas moins de quarante espèces de plantes qui me sont étrangères.', '', 26124),
(146432, 'frFR', 'Je suis partant pour le défi ! Je veux trier les lettres avec une adresse incomplète.', 'Je suis partante pour le défi ! Je veux trier les lettres avec une adresse incomplète.', 26124),
(146433, 'frFR', 'Il reste du courrier à trier, si ça vous tente !$B$BMais vous aspirez peut-être à un plus gros défi… Nous avons reçu des lettres avec une adresse incomplète.$B$BVous voulez vous en charger ?', '', 26124),
(146434, 'frFR', 'Excellent travail, $n ! Je pense qu’on peut passer à la vitesse supérieure… Venez me voir si ça vous intéresse !', '', 26124),
(146448, 'frFR', '', 'Cet atelier est un peu « rustique » à mon goût.', 26124),
(146449, 'frFR', '', 'Ils disent que les dispositifs sans magie sont bons pour les dragonnets en manque de mana, qu’ils ne servent à rien.$B$BPresque rien ne fonctionnerait à Orgrimmar sans ces créations !$B$BIl est temps que je montre à ces siphonnés du palanquin comment on atteint la perfection !', 26124),
(146461, 'frFR', '', 'Suivez la voie empruntée par Huln il y a si longtemps, et faites honneur au nom… de Haut-Roc.', 26124),
(146462, 'frFR', '', 'Et en retour, nous renaissons afin de servir son pouvoir.', 26124),
(146463, 'frFR', '', 'En revanche, pour ceux qui menacent notre monde… ou s’en prennent à nos alliés… vous incarnez le courroux de la Lumière.', 26124),
(146471, 'frFR', '', 'Avez-vous réuni les informations dont j’ai besoin ?', 26124),
(146472, 'frFR', '', 'Oui, voici les résultats.', 26124),
(146473, 'frFR', '', 'Excellent travail. Mon maître sera ravi.', 26124),
(146475, 'frFR', '', 'Parcourir le monde avec nos nouveaux alliés et montrer à tous la noblesse et la puissance de l’héritage des Sacrenuit.', 26124),
(146476, 'frFR', '', 'Ses murmures ont brisé la volonté des dragons… et même conduit les enfants des titans à la folie.', 26124),
(146477, 'frFR', '', 'Le pouvoir du Vide peut être mis à profit… et servir ceux dont la volonté est inflexible.', 26124),
(146482, 'frFR', '', 'Brandissez les ténèbres telle l’arme de notre salut… et défendez l’Alliance !', 26124),
(146516, 'frFR', 'L’énergie du Vide que les Éthériens ont libérée lors de leur attaque a rendu les autres îles instables. Nul n’est autorisé à s’aventurer au-delà de ce point.', 'L’énergie du Vide que les Éthériens ont libérée lors de leur attaque a rendu les autres îles instables. Nul n’est autorisé à s’aventurer au-delà de ce point.', 26124),
(146517, 'frFR', 'Les derniers à avoir franchi cette zone ont été dévorés par les ténèbres.', 'Les derniers à avoir franchi cette zone ont été dévorés par les ténèbres.', 26124),
(146522, 'frFR', 'Vous venez faire réparer votre équipement ?$B$BÀ moins que vous ne cherchiez des outils de qualité ?', '', 26124),
(146543, 'frFR', '', 'Je vous emmène ? J’espère que votre destination en vaut la peine !', 26124),
(146544, 'frFR', 'Il faut que je me rende à la halte de Forteramure.', 'Il faut que je me rende à la halte de Forteramure.', 26124),
(146552, 'frFR', 'Votre connexion au monde des esprits commence à s’étioler…', 'Votre connexion au monde des esprits commence à s’étioler…', 26124),
(146561, 'frFR', 'Le temps guérit toutes les blessures… surtout quand il est possible de retourner dans le passé.', '', 26124),
(146562, 'frFR', 'Montrez-moi Silithus avant que la région ne soit transpercée.', 'Montrez-moi Silithus avant que la région ne soit transpercée.', 26124),
(146563, 'frFR', 'Renvoyez-moi dans le présent.', 'Renvoyez-moi dans le présent.', 26124),
(146605, 'frFR', '', 'Notre priorité est de faire échouer les plans de la Horde. Nous ne pouvons pas nous permettre de consacrer des ressources au fonctionnement normal du réseau de transport aérien.

Si vous voulez quitter ce maudit désert, vous devrez le faire par vos propres moyens.

Toutefois, en cas d’extrême urgence, je suppose que je devrais pouvoir arranger un vol…', 26124),
(146606, 'frFR', 'Je dois m’entretenir avec Magni Barbe-de-Bronze au plus vite.', 'Je dois m’entretenir avec Magni Barbe-de-Bronze au plus vite.', 26124),
(146636, 'frFR', 'Nous avons pour ordre de nous procurer de ce mystérieux minerai coûte que coûte.', '', 26124),
(146637, 'frFR', '', 'J’ai hâte de voir leurs têtes quand tous leurs déchiqueteurs seront réduits en pièces !', 26124),
(146638, 'frFR', '', 'Nous devons découvrir comment les silithides ont pu survivre à l’épée de Sargeras !', 26124),
(146641, 'frFR', 'Nous ne pouvons permettre la résurgence du Marteau du crépuscule. Marche-Vide doit mourir !', '', 26124),
(146737, 'frFR', 'Votre ascendance est chargée d’histoire. C’est fascinant ! J’ai hâte d’en apprendre plus, $R. Mais je ferais bien de trouver un encens plus puissant !', '', 26124),
(146745, 'frFR', 'Ces gobelins sont tellement occupés avec leur matériel d’extraction qu’ils n’ont pas pris la peine d’aménager une station de vol digne de ce nom.

<Urok ronchonne et tape du pied sur le sol.>

Vous allez devoir vous débrouiller pour quitter cet endroit.

Enfin, si c’était la fin du monde, je pourrais sans doute improviser une solution.', '', 26124),
(146755, 'frFR', '', 'Seuls les imbéciles se disputent les terres. Les visionnaires, eux, dominent les cieux !', 26124),
(146757, 'frFR', 'Il faut que je me rende au village de Sudevent.', 'Il faut que je me rende au village de Sudevent.', 26124),
(146851, 'frFR', '', 'Ayez pas peur d’vous salir les mains en broyant des crânes silithides !', 26124),
(146854, 'frFR', '', 'Les résultats de la recherche vont nous permettre de comprendre le pouvoir de cette épée gigantesque !', 26124),
(146857, 'frFR', 'Éliminez ces maudits espions du SI:7 avant qu’ils sabotent toute l’opération !', '', 26124),
(146861, 'frFR', 'Allez là-bas et remettez ces feignasses de prospecteurs à leur place !', '', 26124),
(146863, 'frFR', 'Nous devons empêcher ce fanatique de gagner les survivants restants à sa cause ! Apportez-moi sa tête !', '', 26124),
(146918, 'frFR', '', 'Encore une fournée parfaite ! Mmm, ça me met l’eau à la bouche !', 26124),
(146920, 'frFR', 'Ce lieu est très ancien. Détruit par la rage, et pourtant façonné par les fils du destin.

Il y a beaucoup à apprendre ici. Je crois que je vais rester un peu plus longtemps.

Au revoir.', '', 26124),
(146922, 'frFR', 'Que savez-vous au sujet de Telogrus ?', 'Que savez-vous au sujet de Telogrus ?', 26124),
(146958, 'frFR', 'Notre ambassadeur fait partie des Réprouvés, ce qui me semble pertinent, considérant notre chef de guerre.

Malgré tout, je continue de me demander ce que cela nous a coûté.

Auriez-vous un moment pour me faire part de votre expérience avec l’ambassadeur Gardenoire ?', '', 26124),
(146959, 'frFR', 'Merci d’avoir pris le temps de me répondre, $n.

Je présenterai la pétition une fois que nous aurons rassemblé assez de signatures.

Je vous souhaite une agréable journée, $R.', '', 26124),
(146960, 'frFR', 'Il s’est montré grossier et délibérément injurieux.', 'Il s’est montré grossier et délibérément injurieux.', 26124),
(146961, 'frFR', 'Son apparence était rebutante.', 'Son apparence était rebutante.', 26124),
(146962, 'frFR', 'Il devrait être remplacé sans plus attendre !', 'Il devrait être remplacé sans plus attendre !', 26124),
(147039, 'frFR', '', 'La Légion nous a presque tout arraché… alors que j’avais une confiance aveugle en Élisande.

Je suis soulagée que Suramar soit à nouveau entre nos mains.', 26124),
(147040, 'frFR', '', 'J’imagine que je devrais vous remercier.$B$B<Anarys incline légèrement la tête vers l’avant.>', 26124),
(147041, 'frFR', '', 'J’ai regardé Élisande nous conduire à notre perte sans agir.

J’avais tort… sur toute la ligne.', 26124),
(147042, 'frFR', 'J’imagine que je devrais vous remercier.$B$B<Anarys incline légèrement la tête vers l’avant.>', '', 26124),
(147043, 'frFR', 'J’ai regardé Élisande nous conduire à notre perte sans agir.

J’avais tort… sur toute la ligne.', '', 26124),
(147044, 'frFR', 'Vous venez pour vous gausser, c’est ça ?', 'Vous venez pour vous gausser, c’est ça ?', 26124),
(147047, 'frFR', 'Par les branches de l’arcan’dor ! Avez-vous glissé ?', '', 26124),
(147048, 'frFR', 'Faites attention quand vous approchez du bord, $n.', '', 26124),
(147049, 'frFR', 'Avez-vous trébuché, ou s’agissait-il d’un saut voué à imiter une chute maladroite ?', '', 26124),
(147050, 'frFR', 'Faites attention où vous mettez les pieds ! Je ne peux pas y passer la journée ! Hmm, si, techniquement, je pourrais.', '', 26124),
(147051, 'frFR', 'Seriez-vous en train de mener une expérience dangereuse ? Ça me plaît !', '', 26124),
(147052, 'frFR', 'Si votre objectif est de faire une chute mortelle, procédez ailleurs.', '', 26124),
(147053, 'frFR', 'Attention à la marche.', '', 26124),
(147084, 'frFR', 'Oh ! Bonjour… membre de l’Alliance.

Loin de moi l’idée de vous manquer de respect, mais… je ne pense pas que la cathédrale soit le lieu le plus… approprié pour… pour…

Quelqu’un qui a de tels… penchants.', '', 26124),
(147098, 'frFR', 'La Lumière ne traite pas avec le Vide, Elfe. Vous feriez mieux de quitter ces lieux.', 'La Lumière ne traite pas avec le Vide, Elfe. Vous feriez mieux de quitter ces lieux.', 26124),
(147100, 'frFR', 'Vous n’avez rien à faire ici.', 'Vous n’avez rien à faire ici.', 26124),
(147104, 'frFR', 'Je perçois les ténèbres en vous. Bien que la Lumière les dissipe quelque peu.', 'Je perçois les ténèbres en vous. Bien que la Lumière les dissipe quelque peu.', 26124),
(147109, 'frFR', 'Merci, mais je n’ai aucun besoin de votre aide.', 'Merci, mais je n’ai aucun besoin de votre aide.', 26124),
(147130, 'frFR', 'Êtes-vous ici pour implorer le pardon de la Lumière ? $b$bSi vous cherchez l’archevêque Benedictus, je suis au regret de vous informer qu’il est parti en mission.', '', 26124),
(147153, 'frFR', 'Je vous aiderai autant que possible mais, de grâce, veuillez ne pas vous éterniser ici.', 'Je vous aiderai autant que possible mais, de grâce, veuillez ne pas vous éterniser ici.', 26124),
(147159, 'frFR', 'Je loue votre dévouement. Toutefois, je crains que vous ne suivez une voie dangereuse.$B$BVous rendrez grand service à l’Alliance en vous éloignant de cette cathédrale.', 'Je loue votre dévouement. Toutefois, je crains que vous ne suivez une voie dangereuse.$B$BVous rendrez grand service à l’Alliance en vous éloignant de cette cathédrale.', 26124),
(147169, 'frFR', 'Prenez garde, $c. Le nom de dame Alleria ne vous offrira jamais qu’une protection limitée.', '', 26124),
(147173, 'frFR', 'Peut-être qu’Alleria Coursevent a raison quand elle affirme qu’il est possible de contrôler les murmures des ténèbres.

Prenez garde, mon ami, et que la Lum…

Hmm. Eh bien, que la chance vous sourie.', '', 26124),
(147183, 'frFR', 'J’ai passé suffisamment de temps avec des maladroits pour apprendre une chose ou deux sur la façon de soigner des blessures. Peut-être que je peux vous les enseigner aussi ?', '', 26124),
(147187, 'frFR', 'J’avoue avoir mis du temps à m’habituer à cette nouvelle forme. Je me suis même heurté à quelques problèmes de dextérité au début.$B$BMais je peux vous garantir que les techniques en elles-mêmes n’en ont pas souffert.', '', 26124),
(147188, 'frFR', 'Ces machines sont fantastiques ! Comment est-il possible qu’elles fonctionnent sans la moindre anomalie, sans risque de panne ?$B$BOh, veuillez m’excuser, vous désiriez quelque chose ?', '', 26124),
(147191, 'frFR', 'Nous avons tiré de nombreux enseignements de notre combat contre la Légion. Les exossatures sont d’ailleurs le fruit de plusieurs années de recherche.$B$B
Si vous le souhaitez, je peux vous enseigner comment fabriquer des dispositifs similaires.', '', 26124),
(147192, 'frFR', 'Hmm. Pas mal, mais il manque une touche de ténèbres à votre tenue.', '', 26124),
(147193, 'frFR', 'Il s’agit d’une fête sur invitation uniquement. Où se trouve la vôtre ?$B$BOh, vous n’en avez pas. C’est bien ce qu’il me semblait.', '', 26124),
(147196, 'frFR', '', 'Que puis-je faire pour vous ?', 26124),
(147197, 'frFR', 'Oui, j’ai une minute. C’est pour quoi ?', '', 26124),
(147200, 'frFR', '', 'Venez-vous pour faire enchanter quelque chose, ou pour apprendre ?', 26124),
(147205, 'frFR', 'J’étais un pirate réputé, vous savez !

Mais il a fallu qu’ils viennent me chercher, m’affublent de ce haut-de-forme et exigent que j’accueille les nouveaux venus en affichant mon plus beau sourire…', '', 26124),
(147206, 'frFR', 'Vous savez ce qu’il m’en coûte d’esquisser un sourire ?

C’est ridicule !', '', 26124),
(147207, 'frFR', 'Que dois-je faire pour échapper à ce supplice ?

J’ai déjà essayé de m’échapper, mais des Orcs m’ont retrouvé et m’ont ramené ici.', '', 26124),
(147208, 'frFR', 'Psst… Oui, vous, $R.

Vous pourriez dire du mal de moi au chef de guerre ? J’ai besoin de me faire renvoyer, et apparemment, être odieux avec tout le monde ne suffit pas !', '', 26124),
(147209, 'frFR', 'J’ai trouvé ce haut-de-forme immonde dès que je l’ai vu. Un bon vieux tricorne, c’est trop demander ?

Enfin… je dois quand même avouer qu’il tombe parfaitement sur mon crâne.', '', 26124),
(147210, 'frFR', 'Salutations, Sancteforge ! La cathédrale de la Lumière vous sera toujours ouverte.', '', 26124),
(147211, 'frFR', 'Votre absolue dévotion à la Lumière est un exemple pour nous tous.', 'Votre absolue dévotion à la Lumière est un exemple pour nous tous.', 26124),
(147212, 'frFR', 'Vous trouverez toujours des alliés dévoués ici.', 'Vous trouverez toujours des alliés dévoués ici.', 26124),
(147213, 'frFR', 'Vous saurez où me trouver si vous avez besoin de mon aide.', 'Vous saurez où me trouver si vous avez besoin de mon aide.', 26124),
(147214, 'frFR', 'Puisse la Lumière toujours vous guider, $n.', 'Puisse la Lumière toujours vous guider, $n.', 26124),
(147217, 'frFR', 'On m’a pris ma monture !$B$BIl paraît qu’on appelle ça une mise à pied.', 'On m’a pris ma monture !$B$BIl paraît qu’on appelle ça une mise à pied.', 26124),
(147218, 'frFR', 'On m’a remercié, alors j’ai répondu : de rien ! Mais je ne sais toujours pas pourquoi…', 'On m’a remerciée, alors j’ai répondu : de rien ! Mais je ne sais toujours pas pourquoi…', 26124),
(147219, 'frFR', 'Notre boss, Mida, m’a invité à prendre la porte. Mais je n’avais pas les outils pour la dégonder…', 'Notre boss, Mida, m’a invitée à prendre la porte. Mais je n’avais pas les outils pour la dégonder…', 26124),
(147220, 'frFR', 'J’ai été promu vers le bas.', 'J’ai été promue vers le bas.', 26124),
(147221, 'frFR', 'Nous avons fait l’objet d’un « réaménagement des effectifs ».', 'Nous avons fait l’objet d’un « réaménagement des effectifs ».', 26124),
(147223, 'frFR', '', 'Un jour, Lune-d’Argent se tiendra à nouveau aux côtés de l’Alliance. J’en suis persuadée.', 26124),
(147224, 'frFR', 'En mon absence, bien des choses ont changé en Azeroth. Mais l’Alliance demeure un idéal qui mérite d’être défendu.

Et je ferai tout ce qui est en mon pouvoir pour la rendre plus puissante.', '', 26124),
(147225, 'frFR', 'Avant, j’avais un boulot tranquille à Orgrimmar.', 'Avant, j’avais un boulot tranquille à Orgrimmar.', 26124),
(147226, 'frFR', 'La campagne d’Argus nous a beaucoup coûté, mais elle était nécessaire. À présent, ce sont nos propres terres qu’il faut défendre.

Nous ne pouvons pas rester les bras croisés alors que les monstres de la Horde renforcent leurs rangs.', '', 26124),
(147227, 'frFR', 'Mon poste a été supprimé… C’est un peu comme une retraite anticipée.', 'Mon poste a été supprimé… C’est un peu comme une retraite anticipée.', 26124),
(147228, 'frFR', 'Le jeune roi me rappelle beaucoup son père. Mais je doute qu’il en ait pleinement conscience.

Il a les épaules pour mener cette entreprise à bien et apporter du sang frais à l’Alliance.', '', 26124),
(147231, 'frFR', '', '<Tyrande est silencieuse, les sourcils froncés, comme plongée dans une intense réflexion.>', 26124),
(147233, 'frFR', 'Pendant bien trop longtemps, je m’en suis remis à mes visions.

Il est temps de forger notre propre destin. Et cela commence par la recherche de nouveaux alliés.', '', 26124),
(147235, 'frFR', 'L’esprit du vieux Vol’jin, il est encore fort dans cette cité. Votre travail honore sa mémoire.', '', 26124),
(147236, 'frFR', 'Eh bien… mais c’est l’illustre $ct. Vous devez encore être en train de célébrer votre victoire sur la Légion, pas vrai ?$B$B<Nathanos lève les yeux au ciel.>$B$BLa Dame noire vous a confié la mission de trouver de nouveaux alliés à la Horde. Pour votre propre bien, espérons qu’elle ne vous a pas fait confiance à tort.', '', 26124),
(147237, 'frFR', 'La cuisine locale a de… curieuses saveurs.', 'La cuisine locale a de… curieuses saveurs.', 26124),
(147238, 'frFR', 'Ouais, des alliés. Je vois le genre.

Mais j’ai une affaire à faire tourner. Et une opération assez délicate sur le feu avec ça.

Alors remplissez votre part du contrat et j’en ferai de même.', '', 26124),
(147239, 'frFR', 'La diplomatie n’a jamais été mon point fort.

Mieux vaut que vous vous en chargiez.', '', 26124),
(147240, 'frFR', 'La Horde a besoin d’alliés, c’est indéniable.

Mais seuls ceux dont le cœur est empli de bravoure méritent leur place parmi nous. Ceux qui en sont dépourvus ne font que nous affaiblir.', '', 26124),
(147241, 'frFR', 'Cette boisson est verte ! Mais pourquoi ?', 'Cette boisson est verte ! Mais pourquoi ?', 26124),
(147250, 'frFR', 'Il n’y a pas de héros qui tienne dans l’oubli !', 'Il n’y a pas de héros qui tienne dans l’oubli !', 26124),
(147251, 'frFR', 'Nul ne s’opposera au Marteau du crépuscule !', 'Nul ne s’opposera au Marteau du crépuscule !', 26124),
(147252, 'frFR', 'Nous sommes les messagers de la destruction !', 'Nous sommes les messagers de la destruction !', 26124),
(147253, 'frFR', 'Allez-y, appelez à l’aide… Personne ne viendra vous sauver !', 'Allez-y, appelez à l’aide… Personne ne viendra vous sauver !', 26124),
(147254, 'frFR', 'L’heure du Crépuscule scellera votre perte !', 'L’heure du Crépuscule scellera votre perte !', 26124),
(147255, 'frFR', 'Nul ne résiste au Maître !', 'Nul ne résiste au Maître !', 26124),
(147256, 'frFR', 'J’incarne votre destruction !', 'J’incarne votre destruction !', 26124),
(147257, 'frFR', 'Tous se prosterneront devant notre maître !', 'Tous se prosterneront devant notre maître !', 26124),
(147263, 'frFR', '', 'Ils viennent de Haut-Roc et ne manquent pas d’audace. Les Taurens de Haut-Roc sont dans la place !', 26124),
(147264, 'frFR', '', 'Ils vont vous électriser ! Un tonnerre d’applaudissements pour les Taurens de Haut-Roc !', 26124),
(147265, 'frFR', '', 'Super aventuriers le jour, sacrés danseurs la nuit. Il est temps d’accueillir les Sacrenuit !', 26124),
(147266, 'frFR', '', 'Une illusion ? Tout faux ! Simplement les Sacrenuit qui se déhanchent !', 26124),
(147267, 'frFR', '', 'Qui a dit que les âmes sombres et tourmentées ne savaient pas s’amuser ? À vous, Elfes du Vide !', 26124),
(147268, 'frFR', '', 'Elfes du Vide, montrez-nous votre côté sombre !', 26124),
(147269, 'frFR', '', 'Pas besoin de boules à facettes quand les Draeneï sancteforge enflamment la scène !', 26124),
(147270, 'frFR', '', 'Préparez-vous à être éblouis ! Les Draeneï sancteforge ont bien l’intention d’illuminer votre nuit !', 26124),
(147271, 'frFR', '', 'N’oubliez jamais que la maîtrise implique des sacrifices. Le pouvoir n’est jamais sans contrepartie. Il vous faudra parfois mettre vos proches en péril pour les sauver.

Tel est le marché que nous avons conclu.

<Alleria détourne les yeux.>', 26124),
(147272, 'frFR', '', 'L’étude de cette faille est sûrement digne d’intérêt, mais n’oublions pas notre devoir.

Azeroth a besoin de notre protection. Notre place est ici, à combattre pour notre monde.

La puissance qui circule en nous est une arme. Nous nous devons de l’utiliser.', 26124),
(147276, 'frFR', 'L’Arpenteur des ombres est un curieux personnage.

Alleria semble lui faire confiance… jusqu’à un certain point.

Je pense que nous pouvons apprendre beaucoup de lui, tant que nous restons sur nos gardes quant à ses véritables intentions.', '', 26124),
(147298, 'frFR', ' :', ' :', 26124),
(147299, 'frFR', 'Khadgar m’a demandé de remettre cette lettre.', 'Khadgar m’a demandé de remettre cette lettre.', 26124),
(147304, 'frFR', 'La situation en Silithus est maintenant sous contrôle. Je me charge du reste de l’opération. Allez dans l’honneur, $n.', '', 26124),
(147308, 'frFR', '', 'Grâce à vous, nous avons fait un pas de plus dans la compréhension des effets de la lame sur Silithus !', 26124),
(147309, 'frFR', 'Je n’ai jamais rien vu de tel de toute ma carrière ! Qu’est-ce que ça peut bien être ?', '', 26124),
(147310, 'frFR', 'Je pense que la situation est sous contrôle en Silithus. Le SI:7 va pouvoir reprendre l’opération. Merci encore, $n.', '', 26124),
(147341, 'frFR', 'La Horde a réuni plus de 1200 unités d’azérite, et est proche de la victoire !', '', 26124),
(147342, 'frFR', 'L’Alliance a réuni plus de 1200 unités d’azérite, et est proche de la victoire !', '', 26124),
(147378, 'frFR', 'J’ai regardé cette épée toute la journée, mais impossible de me convaincre qu’elle est bien réelle.', 'J’ai regardé cette épée toute la journée, mais impossible de me convaincre qu’elle est bien réelle.', 26124),
(147379, 'frFR', 'Le monde se vide de son énergie. Pouvez-vous le guérir ?', 'Le monde se vide de son énergie. Pouvez-vous le guérir ?', 26124),
(147380, 'frFR', 'On ne survivra jamais à ça.', 'On ne survivra jamais à ça.', 26124),
(147381, 'frFR', 'C’est peut-être le début de la fin.', 'C’est peut-être le début de la fin.', 26124),
(147382, 'frFR', 'Les auspices funestes avaient raison. Azeroth se meurt.', 'Les auspices funestes avaient raison. Azeroth se meurt.', 26124),
(147384, 'frFR', 'Je devrais être chez moi avec ma famille…', 'Je devrais être chez moi avec ma famille…', 26124),
(147385, 'frFR', 'J’espère que vous pouvez faire quelque chose pour nous sauver.', 'J’espère que vous pouvez faire quelque chose pour nous sauver.', 26124),
(147387, 'frFR', 'Où sont donc passés les héros censés nous protéger ?', 'Où sont donc passés les héros censés nous protéger ?', 26124),
(147388, 'frFR', 'J’ai passé ma journée à regarder cette épée. J’arrive toujours pas à croire qu’elle est réelle.', 'J’ai passé ma journée à regarder cette épée. J’arrive toujours pas à croire qu’elle est réelle.', 26124),
(147389, 'frFR', 'Le monde se vide de son énergie. Vous pouvez le soigner, n’est-ce pas ?', 'Le monde se vide de son énergie. Vous pouvez le soigner, n’est-ce pas ?', 26124),
(147390, 'frFR', 'Cette fois-ci, la Dame noire ne pourra pas nous sauver…', 'Cette fois-ci, la Dame noire ne pourra pas nous sauver…', 26124),
(147391, 'frFR', 'J’espère que le chef sait ce qu’il fait.', 'J’espère que le chef sait ce qu’il fait.', 26124),
(147392, 'frFR', 'Dur, dur d’atteindre mon quota avec cette épée géante au-dessus de la tête !', 'Dur, dur d’atteindre mon quota avec cette épée géante au-dessus de la tête !', 26124),
(147393, 'frFR', 'Votre truc, c’est de sauver le monde, nan ? Bah, vous feriez bien de vous y mettre !', 'Votre truc, c’est de sauver le monde, nan ? Bah, vous feriez bien de vous y mettre !', 26124),
(147394, 'frFR', 'Je devrais toucher une prime de risque pour ça !', 'Je devrais toucher une prime de risque pour ça !', 26124),
(147414, 'frFR', '<Souvenir des évènements ayant suivi la campagne d’Argus>', '<Souvenir des évènements ayant suivi la campagne d’Argus>', 26124),
(147415, 'frFR', '<Souvenir des répercussions de la Plaie en Silithus>', '<Souvenir des répercussions de la Plaie en Silithus>', 26124),
(147416, 'frFR', '<Souvenir des répercussions de la Plaie en Silithus>', '<Souvenir des répercussions de la Plaie en Silithus>', 26124);

